window.BANCO = window.BANCO || {};
window.BANCO['CIEN'] = window.BANCO['CIEN'] || {};
window.BANCO['CIEN']["8º Ano"] = [
  {"id": 1, "uid": "CIEN-8-001", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Grandezas Elétricas: Tensão e Volts", "dificuldade": "Fácil", "enunciado": "Nas residências brasileiras, as tomadas elétricas mais comuns fornecem uma diferença de potencial elétrico (tensão) de 127 volts ou 220 volts. A grandeza física 'tensão elétrica' é medida no Sistema Internacional em:", "alternativas": {"A": "Ampères (A).", "B": "Volts (V).", "C": "Watts (W).", "D": "Joules (J).", "E": "Ohms (Ω)."}, "resposta_correta": "B", "justificativa": "A tensão elétrica (ou diferença de potencial elétrico - ddp) representa a força que impulsiona as cargas elétricas através de um condutor, sendo medida em volts (V).", "possui_imagem": true},
  {"id": 2, "uid": "CIEN-8-002", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Grandezas Elétricas: Potência Elétrica", "dificuldade": "Fácil", "enunciado": "A taxa com que um aparelho eletrodoméstico converte energia elétrica em outra forma de energia (como calor, luz ou movimento) a cada segundo é a potência elétrica, cuja unidade de medida no SI é o:", "alternativas": {"A": "Volt (V).", "B": "Watt (W).", "C": "Quilowatt-hora (kWh).", "D": "Ampère (A).", "E": "Caloria (cal)."}, "resposta_correta": "B", "justificativa": "A potência elétrica indica o consumo ou transformação de energia por unidade de tempo (1 Watt = 1 Joule por segundo).", "possui_imagem": true},
  {"id": 3, "uid": "CIEN-8-003", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Efeito Joule no Cotidiano", "dificuldade": "Fácil", "enunciado": "Quando a corrente elétrica percorre a resistência de um chuveiro elétrico, de um ferro de passar roupas ou de uma torradeira, o condutor se aquece rapidamente. Esse aquecimento provocado pela passagem da corrente elétrica através de uma resistência é denominado:", "alternativas": {"A": "Efeito fotoelétrico.", "B": "Efeito Joule.", "C": "Efeito estufa elétrico.", "D": "Efeito Doppler.", "E": "Indução eletromagnética pura."}, "resposta_correta": "B", "justificativa": "O Efeito Joule é o fenômeno físico no qual choques entre os elétrons livres em movimento e os átomos da rede cristalina do condutor transformam energia elétrica em energia térmica (calor).", "possui_imagem": true},
  {"id": 4, "uid": "CIEN-8-004", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Fórmula do Consumo de Energia Elétrica", "dificuldade": "Fácil", "enunciado": "O consumo de energia elétrica de um eletrodoméstico depende diretamente de dois fatores fundamentais, calculados pela fórmula básica E = P x t. Esses dois fatores são:", "alternativas": {"A": "A voltagem da tomada e o tamanho do fio elétrico.", "B": "A potência elétrica do aparelho e o tempo durante o qual ele permanece ligado.", "C": "O preço do aparelho na loja e a marca do fabricante.", "D": "A cor da carcaça do aparelho e a temperatura do dia.", "E": "A quantidade de interruptores presentes na casa."}, "resposta_correta": "B", "justificativa": "A quantidade de energia elétrica consumida (E) é obtida pelo produto da potência elétrica do aparelho (P) pelo tempo de funcionamento (t): E = P x Δt.", "possui_imagem": true},
  {"id": 5, "uid": "CIEN-8-005", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Unidade Comercial de Energia: O Quilowatt-hora (kWh)", "dificuldade": "Fácil", "enunciado": "Na conta de luz mensal emitida pelas concessionárias de distribuição de energia elétrica, o consumo total de eletricidade da residência é cobrado na unidade comercial chamada:", "alternativas": {"A": "Volts por segundo (V/s).", "B": "Quilowatt-hora (kWh).", "C": "Ampères por hora (Ah).", "D": "Joules por metro cúbico.", "E": "Watts por minuto (W/min)."}, "resposta_correta": "B", "justificativa": "O quilowatt-hora (kWh) é a unidade prática comercial adotada para medir o consumo de energia elétrica, equivalendo à energia consumida por um aparelho de 1.000 Watts ligado continuamente durante 1 hora (1 kWh = 3,6 milhões de Joules).", "possui_imagem": true},
  {"id": 6, "uid": "CIEN-8-006", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Matriz Elétrica Brasileira", "dificuldade": "Fácil", "enunciado": "No Brasil, a maior parte da eletricidade consumida nas indústrias e residências é gerada em usinas que utilizam a força da água em represas e rios, conhecidas como:", "alternativas": {"A": "Usinas termonucleares.", "B": "Usinas hidrelétricas.", "C": "Usinas a carvão fóssil.", "D": "Usinas geotérmicas.", "E": "Usinas solares espaciais."}, "resposta_correta": "B", "justificativa": "As usinas hidrelétricas são responsáveis por mais de 55% a 65% de toda a eletricidade gerada no Brasil, caracterizando uma matriz predominantemente renovável em relação à média global.", "possui_imagem": true},
  {"id": 7, "uid": "CIEN-8-007", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Usinas Hidrelétricas: Transformação de Energia", "dificuldade": "Fácil", "enunciado": "Em uma usina hidrelétrica, a água represada em grande altitude possui energia potencial gravitacional. Ao descer pelos dutos, essa água ganha velocidade e faz girar pás de turbinas gigantes, que acionam geradores. A sequência correta das transformações de energia na hidrelétrica é:", "alternativas": {"A": "Energia nuclear -> Energia química -> Eletricidade.", "B": "Energia potencial gravitacional -> Energia cinética (movimento) -> Energia elétrica.", "C": "Energia solar -> Energia térmica -> Eletricidade pura.", "D": "Energia elétrica -> Energia eólica -> Energia mecânica.", "E": "Energia fóssil -> Energia de biomassa -> Eletricidade."}, "resposta_correta": "B", "justificativa": "A queda d'água converte energia potencial gravitacional em energia cinética da água em escoamento, que movimenta as turbinas hidráulicas (energia mecânica de rotação), convertida em energia elétrica pelos geradores eletromagnéticos.", "possui_imagem": true},
  {"id": 8, "uid": "CIEN-8-008", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Bandeiras Tarifárias na Conta de Luz", "dificuldade": "Fácil", "enunciado": "O sistema de bandeiras tarifárias aplicado na conta de energia elétrica no Brasil utiliza cores (verde, amarela e vermelha) para sinalizar aos consumidores se a geração de energia está mais barata ou mais cara a cada mês. A bandeira vermelha é acionada principalmente quando:", "alternativas": {"A": "Há chuvas torrenciais que enchem todas as represas do país.", "B": "O nível de água nos reservatórios das hidrelétricas fica criticamente baixo devido à seca, exigindo o acionamento de usinas termelétricas, que são mais caras e poluentes.", "C": "A população consome menos eletricidade que a média.", "D": "O governo decide dar desconto nas tarifas de energia elétrica.", "E": "Todas as lâmpadas da cidade são trocadas por modelos LED."}, "resposta_correta": "B", "justificativa": "Em períodos de escassez hídrica prolongada (seca nos reservatórios), o Operador Nacional do Sistema (ONS) despacha usinas termelétricas movidas a óleo e gás natural, cujo custo de geração por combustível é significativamente mais alto, ativando a bandeira vermelha.", "possui_imagem": true},
  {"id": 9, "uid": "CIEN-8-009", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Eficiência Energética: Lâmpadas LED", "dificuldade": "Fácil", "enunciado": "Substituir antigas lâmpadas incandescentes ou fluorescentes por lâmpadas de tecnologia LED em uma residência proporciona grande economia de energia porque as lâmpadas LED:", "alternativas": {"A": "Não precisam ser ligadas a fios elétricos.", "B": "Convertem uma fração muito maior de energia elétrica diretamente em luz, desperdiçando muito menos energia na forma de calor indesejado por Efeito Joule.", "C": "Funcionam apenas quando o ambiente está frio.", "D": "Emitem raios gama que duram 50 anos sem gastar bateria.", "E": "Produzem energia elétrica em vez de consumir."}, "resposta_correta": "B", "justificativa": "Lâmpadas incandescentes dissipam mais de 90% da eletricidade na forma de calor (radiação infravermelha), aproveitando menos de 10% como luz visível. O LED (diodo emissor de luz) possui altíssima eficiência luminosa, gerando a mesma claridade consumindo até 80-85% menos energia.", "possui_imagem": true},
  {"id": 10, "uid": "CIEN-8-010", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Transformações de Energia: Ventilador e Liquidificador", "dificuldade": "Fácil", "enunciado": "Ao ligar um ventilador ou um liquidificador na tomada, a energia elétrica fornecida pela rede é transformada primariamente em:", "alternativas": {"A": "Energia mecânica de rotação (movimento das pás/hélices).", "B": "Energia térmica para congelar alimentos.", "C": "Energia nuclear de fissão atômica.", "D": "Energia química pura de glicose.", "E": "Luz ultravioleta bactericida."}, "resposta_correta": "A", "justificativa": "Motores elétricos operam com base na força magnética sobre condutores percorridos por corrente, convertendo energia elétrica predominantemente em energia mecânica (cinética de rotação).", "possui_imagem": true},
  {"id": 11, "uid": "CIEN-8-011", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Aparelhos de Alta Potência em uma Residência", "dificuldade": "Fácil", "enunciado": "Em uma residência típica de uma família de quatro pessoas, o aparelho eletrodoméstico que costuma apresentar a maior potência elétrica individual e que responde por grande parte do valor da conta de luz mensal é o:", "alternativas": {"A": "Relógio digital de cabeceira (5 W).", "B": "Chuveiro elétrico (5.500 W a 7.500 W).", "C": "Carregador de celular (15 W).", "D": "Roteador de internet Wi-Fi (12 W).", "E": "Abajur com lâmpada LED (9 W)."}, "resposta_correta": "B", "justificativa": "O chuveiro elétrico opera com altíssimas potências (entre 5.500 W e 7.800 W na posição inverno) para aquecer instantaneamente um fluxo contínuo de água fria em frações de segundo, sendo um dos maiores vilões do consumo doméstico.", "possui_imagem": true},
  {"id": 12, "uid": "CIEN-8-012", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Condutores e Isolantes Elétricos", "dificuldade": "Fácil", "enunciado": "Para que um circuito elétrico funcione com segurança, os fios condutores de eletricidade são feitos de cobre e encapados externamente com plástico de PVC. O plástico é utilizado na capa externa porque atua como:", "alternativas": {"A": "Um excelente condutor que aumenta a velocidade da corrente elétrica.", "B": "Um isolante elétrico, impedindo que a corrente elétrica escape e prevenindo choques elétricos e curtos-circuitos.", "C": "Um combustível que queima os elétrons excedentes.", "D": "Um amplificador de voltagem para os eletrodomésticos.", "E": "Um ímã permanente que atrai parafusos."}, "resposta_correta": "B", "justificativa": "Materiais isolantes (como borracha, PVC e vidro) possuem elétrons fortemente ligados aos núcleos atômicos, apresentando altíssima resistividade elétrica e impedindo a passagem de corrente para a pele humana ou objetos adjacentes.", "possui_imagem": true},
  {"id": 13, "uid": "CIEN-8-013", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Circuitos Elétricos: Interruptor", "dificuldade": "Fácil", "enunciado": "Em uma instalação elétrica residencial, a função primordial de um interruptor de parede é:", "alternativas": {"A": "Aumentar a voltagem da lâmpada de 127 V para 220 V.", "B": "Abrir ou fechar o circuito elétrico, interrompendo ou permitindo a passagem da corrente elétrica para ligar ou desligar a lâmpada.", "C": "Armazenar eletricidade na parede como uma bateria de lítio.", "D": "Purificar a corrente elétrica retirando elétrons oxidados.", "E": "Medir a temperatura do teto da casa."}, "resposta_correta": "B", "justificativa": "Um interruptor é um dispositivo mecânico de controle: na posição 'fechado', ele estabelece continuidade física no condutor permitindo a circulação da corrente; na posição 'aberto', ele cria uma barreira de ar isolante, cessando o circuito.", "possui_imagem": true},
  {"id": 14, "uid": "CIEN-8-014", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Fusíveis e Disjuntores: Dispositivos de Proteção", "dificuldade": "Fácil", "enunciado": "No quadro de distribuição de energia elétrica de uma casa existem disjuntores (ou fusíveis). A função desses componentes de segurança é:", "alternativas": {"A": "Produzir eletricidade extra quando falta luz na rua.", "B": "Desarmar (interromper a corrente elétrica) automaticamente caso ocorra uma sobrecarga excessiva ou curto-circuito na fiação, evitando que os fios esquentem e provoquem incêndios.", "C": "Diminuir a conta de luz pela metade todos os meses.", "D": "Tornar todos os aparelhos da casa à prova de água.", "E": "Substituir o medidor de relógio da concessionária."}, "resposta_correta": "B", "justificativa": "Disjuntores termomagnéticos atuam como chaves seccionadoras automáticas de proteção: desarmam por dilatação térmica bimetálica (sobrecorrente prolongada) ou por atração eletromagnética instantânea (curto-circuito), protegendo condutores contra fogo.", "possui_imagem": true},
  {"id": 15, "uid": "CIEN-8-015", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Perigo do Curto-Circuito", "dificuldade": "Fácil", "enunciado": "Um curto-circuito ocorre quando fios elétricos desencapados com potenciais diferentes entram em contato direto sem nenhuma resistência intermediária entre eles. A consequência física imediata de um curto-circuito é:", "alternativas": {"A": "O congelamento instantâneo de toda a fiação elétrica.", "B": "A elevação brusca e extrema da intensidade da corrente elétrica para valores perigosos, gerando calor intenso por Efeito Joule capaz de derreter isolamentos e iniciar incêndios.", "C": "A transformação da corrente alternada em água líquida.", "D": "O desligamento eterno de todas as usinas hidrelétricas do país.", "E": "O aumento da resistência elétrica dos fios para o infinito."}, "resposta_correta": "B", "justificativa": "Pela Primeira Lei de Ohm (I = U / R), quando a resistência do circuito cai para valores próximos de zero (R -> 0), a intensidade da corrente elétrica atinge valores colossais (I -> infinito), liberando energia térmica fulminante por Efeito Joule (P = R . I²).", "possui_imagem": false},
  {"id": 16, "uid": "CIEN-8-016", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Consumo em Modo Stand-by", "dificuldade": "Fácil", "enunciado": "Muitos aparelhos eletrônicos (como televisores, micro-ondas e aparelhos de som) continuam consumindo energia elétrica mesmo quando estão 'desligados', mantendo uma luzinha vermelha acesa ou relógio digital no painel. Esse consumo contínuo e silencioso é denominado:", "alternativas": {"A": "Modo de corte total de eletricidade.", "B": "Consumo em modo de espera (stand-by).", "C": "Efeito Joule reverso.", "D": "Transformação de voltagem passiva.", "E": "Potência nominal zero."}, "resposta_correta": "B", "justificativa": "O modo stand-by mantém circuitos receptores de controle remoto, relógios e memórias ativas; embora a potência unitária seja baixa (1 a 10 W), somada ao longo de 24 horas por dia durante 30 dias em múltiplos aparelhos, representa de 5% a 12% da conta residencial.", "possui_imagem": false},
  {"id": 17, "uid": "CIEN-8-017", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Selo Procel de Economia de Energia", "dificuldade": "Fácil", "enunciado": "Ao comprar uma geladeira nova em uma loja, é recomendado conferir a etiqueta com o Selo Procel. Um eletrodoméstico que possui a classificação 'A' no Selo Procel indica que ele:", "alternativas": {"A": "Funciona sem ser ligado na tomada.", "B": "Possui excelente eficiência energética, consumindo menos eletricidade para realizar a mesma tarefa em comparação com modelos de classes 'D' ou 'E'.", "C": "Dura apenas duas semanas antes de quebrar.", "D": "É feito exclusivamente de madeira reflorestada.", "E": "Causa choques elétricos fracos propositais no usuário."}, "resposta_correta": "B", "justificativa": "O Selo Procel (Programa Nacional de Conservação de Energia Elétrica) identifica e premia equipamentos com os melhores coeficientes de desempenho e menor consumo específico de kWh da categoria comercial.", "possui_imagem": false},
  {"id": 18, "uid": "CIEN-8-018", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Usinas Termelétricas: Vantagens e Desvantagens", "dificuldade": "Fácil", "enunciado": "As usinas termelétricas geram eletricidade a partir da queima de combustíveis como gás natural, óleo diesel ou carvão mineral. Embora possam ser ligadas rapidamente em períodos de seca das hidrelétricas, a grande desvantagem ambiental das termelétricas fósseis é:", "alternativas": {"A": "Ocuparem áreas terrestres dez vezes maiores que as represas da Amazônia.", "B": "A alta emissão de gases poluentes e de dióxido de carbono (CO2), contribuindo para a poluição do ar e para o aquecimento global.", "C": "Consumirem todo o oxigênio da camada de ozônio em duas horas.", "D": "Não funcionarem durante o período da noite.", "E": "Fazerem as linhas de transmissão de energia congelarem."}, "resposta_correta": "B", "justificativa": "Termelétricas a combustíveis fósseis possuem alto custo operacional por queima de insumo não renovável e são intensivas na emissão de gases de efeito estufa (CO2) e poluentes locais (SOx, NOx e particulados).", "possui_imagem": false},
  {"id": 19, "uid": "CIEN-8-019", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Energia Eólica: Fonte Limpa e Renovável", "dificuldade": "Fácil", "enunciado": "A energia eólica é considerada uma das fontes de geração de eletricidade que mais crescem no Brasil, principalmente na Região Nordeste. Uma grande vantagem ambiental dessa forma de energia é:", "alternativas": {"A": "Não emitir gases causadores do efeito estufa durante sua operação de geração e utilizar uma fonte natural inesgotável (o vento).", "B": "Produzir vento frio que resfria as cidades no verão.", "C": "Funcionar com a queima de folhas secas de árvores do cerrado.", "D": "Eliminar totalmente a necessidade de linhas de transmissão.", "E": "Gerar eletricidade através da força da gravidade lunar subterrânea."}, "resposta_correta": "A", "justificativa": "Parques eólicos operam sem emissões diretas de carbono ou efluentes líquidos e utilizam o fluxo cinético inesgotável dos ventos alísios litorâneos, integrando a matriz limpa e sustentável.", "possui_imagem": false},
  {"id": 20, "uid": "CIEN-8-020", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Energia Solar Fotovoltaica em Residências", "dificuldade": "Fácil", "enunciado": "O sistema de microgeração solar fotovoltaica residencial permite que uma família gere sua própria eletricidade durante o dia através de placas no telhado. A energia elétrica excedente gerada sob sol forte e não consumida de imediato pela casa é:", "alternativas": {"A": "Armazenada em baldes de água no quintal.", "B": "Injetada na rede elétrica da concessionária de distribuição, gerando créditos energéticos compensatórios na conta de luz.", "C": "Descartada na atmosfera na forma de fumaça branca.", "D": "Queimada em disjuntores especiais de emergência.", "E": "Transformada em gás natural comprimido na cozinha."}, "resposta_correta": "B", "justificativa": "Pelo sistema de compensação de energia elétrica (Net Metering regulado pela ANEEL), o excedente gerado durante o dia é injetado na rede da distribuidora, gerando créditos em kWh com validade regulamentar para abater no consumo noturno.", "possui_imagem": false},
  {"id": 21, "uid": "CIEN-8-021", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Segurança com Eletricidade: O Fio Terra", "dificuldade": "Fácil", "enunciado": "O terceiro pino presente nas tomadas padronizadas brasileiras (pino central do padrão NBR 14136) é conectado ao chamado 'fio terra'. A finalidade de segurança desse pino é:", "alternativas": {"A": "Aumentar a velocidade dos jogos de videogame no computador.", "B": "Desviar com segurança para a terra eventuais fugas de corrente elétrica da carcaça metálica de aparelhos (como lavadoras e micro-ondas), protegendo os usuários contra choques elétricos perigosos.", "C": "Resfriar os fios para que eles não precisem de plástico protetor.", "D": "Permitir que a tomada receba energia solar da calçada.", "E": "Substituir o cabo de antena de televisão na sala."}, "resposta_correta": "B", "justificativa": "O condutor de proteção (fio terra) oferece um caminho de baixíssima impedância conectado ao solo; se um fio energizado entrar em contato acidental com a carcaça de metal de um aparelho, a corrente de fuga drena pelo fio terra e desarma o disjuntor/DR, evitando choque no usuário.", "possui_imagem": false},
  {"id": 22, "uid": "CIEN-8-022", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Cálculo de Consumo de Energia Elétrica", "dificuldade": "Médio", "enunciado": "Um chuveiro elétrico de potência P = 5.000 Watts (5 kW) é utilizado diariamente por quatro pessoas em uma casa, somando um tempo total de funcionamento de 1 hora por dia (1 h/dia). Ao final de um mês de 30 dias, qual será o consumo total de energia elétrica desse chuveiro em quilowatts-hora (kWh)?", "alternativas": {"A": "5 kWh.", "B": "30 kWh.", "C": "150 kWh.", "D": "500 kWh.", "E": "5.000 kWh."}, "resposta_correta": "C", "justificativa": "Cálculo: Potência em kW = 5.000 W / 1.000 = 5 kW. Tempo mensal = 1 hora/dia x 30 dias = 30 horas. Energia consumida: E = P x t = 5 kW x 30 h = 150 kWh.", "possui_imagem": false},
  {"id": 23, "uid": "CIEN-8-023", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Cálculo Financeiro da Conta de Luz", "dificuldade": "Médio", "enunciado": "Considerando o exercício anterior, no qual o chuveiro elétrico consumiu 150 kWh no mês, sabendo que a tarifa cobrada pela concessionária de energia é de R$ 0,80 por cada quilowatt-hora (incluindo impostos), quanto essa família pagará na conta de luz SOMENTE pelo uso desse chuveiro no mês?", "alternativas": {"A": "R$ 40,00.", "B": "R$ 80,00.", "C": "R$ 120,00.", "D": "R$ 150,00.", "E": "R$ 187,50."}, "resposta_correta": "C", "justificativa": "Cálculo do custo financeiro: Custo = Consumo (kWh) x Tarifa (R$/kWh) = 150 kWh x R$ 0,80/kWh = R$ 120,00.", "possui_imagem": false},
  {"id": 24, "uid": "CIEN-8-024", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Comparação de Consumo: Potência vs. Tempo", "dificuldade": "Médio", "enunciado": "Considere dois aparelhos elétricos em uma residência:\n- Aparelho X: ferro de passar roupas de 1.500 W ligado durante 2 horas por semana.\n- Aparelho Y: televisão de 100 W ligada durante 5 horas por dia (35 horas por semana).\nQual dos dois aparelhos consome mais energia elétrica ao longo de uma semana?", "alternativas": {"A": "O aparelho X consome mais, pois possui potência 15 vezes maior que a televisão.", "B": "O aparelho Y consome mais, pois, apesar de ter menor potência, o seu tempo prolongado de uso semanal (E = 3,5 kWh) supera o consumo do ferro de passar (E = 3,0 kWh).", "C": "Ambos consomem exatamente a mesma quantidade de energia elétrica.", "D": "Nenhum consome energia se estiverem ligados em tomadas de 127 V.", "E": "O ferro consome zero kWh porque esquenta sem gastar energia."}, "resposta_correta": "B", "justificativa": "Cálculo: Ferro (X): E = 1,5 kW x 2 h = 3,0 kWh/semana. TV (Y): E = 0,1 kW x 35 h = 3,5 kWh/semana. O aparelho Y consome mais energia devido ao longo tempo de funcionamento acumulado.", "possui_imagem": false},
  {"id": 25, "uid": "CIEN-8-025", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Ligação de Aparelhos em Paralelo nas Casas", "dificuldade": "Médio", "enunciado": "Em todas as instalações elétricas residenciais bem projetadas, as lâmpadas e as tomadas da casa são ligadas entre si em um circuito em paralelo (e não em série). A razão técnica essencial para adotar a ligação em paralelo é:", "alternativas": {"A": "Garantir que todos os aparelhos recebam a mesma voltagem nominal (como 127 V) e que o desligamento ou queima de um aparelho não interrompa o funcionamento dos demais aparelhos da casa.", "B": "Fazer com que todas as lâmpadas da casa tenham que ficar sempre acesas juntas o tempo todo.", "C": "Diminuir a voltagem da rede para 1,5 volt de pilha em todas as tomadas.", "D": "Eliminar totalmente o uso de fios de cobre na residência.", "E": "Fazer a conta de luz ser cobrada em ampères em vez de quilowatts-hora."}, "resposta_correta": "A", "justificativa": "Em circuitos em paralelo, todos os ramos compartilham a mesma diferença de potencial (ddp) da rede e funcionam como ramificações independentes: desligar uma lâmpada não abre o circuito das outras tomadas.", "possui_imagem": false},
  {"id": 26, "uid": "CIEN-8-026", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Desvantagem do Circuito em Série", "dificuldade": "Médio", "enunciado": "Antigamente, em conjuntos simples de lâmpadas decorativas de árvores de Natal (pisca-pisca ligados em circuito em série puro), quando uma única lâmpada do cordão queimava ou se soltava do bocal, ocorria um problema clássico:", "alternativas": {"A": "Todas as outras lâmpadas continuavam acesas brilhando o dobro.", "B": "Todas as outras lâmpadas do circuito se apagavam imediatamente, pois a queima da lâmpada abria o caminho único por onde a corrente elétrica passava.", "C": "A árvore de Natal pegava fogo instantaneamente devido ao gelo.", "D": "A voltagem da casa inteira subia para 10.000 volts.", "E": "A tomada explodia liberando fumaça de enxofre."}, "resposta_correta": "B", "justificativa": "Em circuitos puramente em série, existe apenas um único caminho contínuo para o fluxo de corrente. A interrupção de qualquer elemento (filamento rompido) quebra o circuito, cessando a circulação de corrente para todos os componentes a jusante.", "possui_imagem": false},
  {"id": 27, "uid": "CIEN-8-027", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Alta Tensão nas Linhas de Transmissão", "dificuldade": "Médio", "enunciado": "A energia elétrica gerada em usinas distantes (como a Usina de Itaipu) viaja centenas de quilômetros até as cidades através de torres e cabos de transmissão operando em altíssima tensão (frequentemente entre 230.000 V e 750.000 V). A física por trás do uso de tensões tão altas nas linhas de transmissão visa:", "alternativas": {"A": "Aumentar o peso dos cabos de transmissão para evitar balanços pelo vento.", "B": "Reduzir drasticamente a intensidade da corrente elétrica para a mesma potência transmitida, minimizando as perdas de energia por aquecimento (Efeito Joule, P = R . I²) ao longo das centenas de quilômetros de fio.", "C": "Permitir que a eletricidade viaje pelo ar sem tocar em nenhum cabo metálico.", "D": "Gelar os cabos de alumínio para transformá-los em ouro.", "E": "Tornar as torres de transmissão imunes à gravidade."}, "resposta_correta": "B", "justificativa": "Pela relação P = U . I, ao elevar a tensão (U) por transformadores elevadores, a corrente (I) diminui na mesma proporção. Como a potência dissipada por calor nos fios varia com o quadrado da corrente (P_perda = R . I²), reduzir a corrente minimiza drasticamente a dissipação Joule nas longas distâncias.", "possui_imagem": false},
  {"id": 28, "uid": "CIEN-8-028", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Transformadores de Tensão", "dificuldade": "Médio", "enunciado": "Nos postes das ruas das cidades existem transformadores elétricos cilíndricos com aletas de resfriamento. A função precípua desses transformadores de distribuição urbana é:", "alternativas": {"A": "Transformar eletricidade em carvão mineral refinado.", "B": "Reduzir a média tensão das redes de distribuição da rua (como 13.800 V) para as tensões seguras e padronizadas utilizadas nas tomadas residenciais (127 V e 220 V).", "C": "Armazenar eletricidade durante o dia para usar nos feriados nacionais.", "D": "Medir a quantidade de água que os moradores bebem nas casas.", "E": "Bloquear a passagem de correntes alternadas na rede."}, "resposta_correta": "B", "justificativa": "Transformadores redutores baseados na Lei da Indução Eletromagnética de Faraday ajustam a relação de espiras entre o enrolamento primário e secundário, rebaixando a tensão perigosa da linha aérea (13,8 kV) para os níveis de consumo doméstico (127/220 V).", "possui_imagem": false},
  {"id": 29, "uid": "CIEN-8-029", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Disjuntor Residual Diferencial (DR)", "dificuldade": "Médio", "enunciado": "Nas instalações elétricas prediais modernas construídas conforme as normas técnicas (NBR 5410), é obrigatório o uso do Dispositivo Diferencial Residual (DR). A função especializada desse dispositivo de proteção à vida humana é:", "alternativas": {"A": "Desarmar o circuito instantaneamente quando detecta uma pequena fuga de corrente (da ordem de 30 miliampères), como no caso de uma pessoa tocando acidentalmente um fio desencapado, salvando-a de choque elétrico fatal.", "B": "Aumentar a potência do chuveiro elétrico no inverno.", "C": "Garantir que a conta de luz venha com valor zero a cada seis meses.", "D": "Evitar que a fiação elétrica enferruje com o ar atmosférico.", "E": "Transformar energia elétrica em energia solar à noite."}, "resposta_correta": "A", "justificativa": "O dispositivo DR monitora o balanço vetorial de corrente: se a corrente que retorna pelo condutor neutro for menor que a que entra pela fase (diferença ≥ 30 mA), indica que a corrente está escoando para a terra (potencialmente através do corpo humano); o DR secciona o circuito em milissegundos.", "possui_imagem": false},
  {"id": 30, "uid": "CIEN-8-030", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Impactos Socioambientais de Grandes Hidrelétricas", "dificuldade": "Médio", "enunciado": "Embora a energia hidrelétrica seja renovável e tenha baixíssima emissão operacional de carbono, a construção de megausinas com grandes reservatórios (como Belo Monte e Tucuruí) gera sérios impactos socioambientais, tais como:", "alternativas": {"A": "A liberação de radiação atômica na água dos rios.", "B": "O alagamento de extensas áreas de floresta nativa, alteração profunda do regime hídrico dos rios, perda de biodiversidade aquática e deslocamento forçado de comunidades ribeirinhas e terras indígenas.", "C": "A extinção definitiva de todas as aves voadoras da região.", "D": "O resfriamento do clima global a ponto de congelar os rios amazônicos.", "E": "A contaminação permanente da água potável por petróleo cru."}, "resposta_correta": "B", "justificativa": "Grandes represamentos inundam ecossistemas terrestres (provocando decomposição anaeróbia de biomassa submersa com emissão transitória de metano), interrompem a piracema de peixes reofílicos e desestruturam populações tradicionais e povos originários.", "possui_imagem": false},
  {"id": 31, "uid": "CIEN-8-031", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Usinas Termonucleares: Princípio de Fissão", "dificuldade": "Médio", "enunciado": "Na Central Nuclear de Angra dos Reis (Angra 1 e Angra 2), no Rio de Janeiro, a energia elétrica é gerada a partir da fissão nuclear do elemento urânio enriquecido. O calor liberado pela quebra controlada dos núcleos atômicos de urânio é utilizado para:", "alternativas": {"A": "Queimar carvão vegetal dentro do reator atômico.", "B": "Ferver água sob alta pressão para gerar vapor, o qual aciona uma turbina e um gerador elétrico idênticos aos de uma usina termoelétrica convencional.", "C": "Produzir raios solares que alimentam painéis fotovoltaicos no teto do reator.", "D": "Congelar o mar para produzir água mineral pura sem sais.", "E": "Empurrar o navio de passageiros por repulsão eletrostática pura."}, "resposta_correta": "B", "justificativa": "Uma usina nuclear é tecnicamente uma usina térmica cuja fonte de calor é a reação em cadeia de fissão nuclear de urânio-235. O calor aquece o circuito primário, que transfere calor ao circuito secundário produzindo vapor d'água a alta pressão para turbinar o gerador elétrico.", "possui_imagem": false},
  {"id": 32, "uid": "CIEN-8-032", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Sobrecarga Elétrica e o Uso de Benjamins ('Tês')", "dificuldade": "Médio", "enunciado": "Ligar simultaneamente vários aparelhos de alta potência (como forno de micro-ondas, fritadeira elétrica air fryer e cafeteira) em uma mesma tomada utilizando adaptadores múltiplos conhecidos como 'benjamins' ou 'tês' é perigoso porque:", "alternativas": {"A": "A voltagem da tomada divide-se por três e queima os circuitos dos aparelhos.", "B": "A corrente elétrica total solicitada por todos os aparelhos se soma na fiação daquela tomada, ultrapassando a capacidade limite de condução dos fios de cobre e provocando superaquecimento perigoso e risco de incêndio.", "C": "Os aparelhos começam a sugar eletricidade do ar da cozinha.", "D": "O benjamim atrai raios cósmicos de tempestades para a tomada.", "E": "A água dos alimentos evapora em forma de fumaça atômica tóxica."}, "resposta_correta": "B", "justificativa": "Aparelhos conectados em paralelo no mesmo ponto somam suas correntes elétricas no ramo principal (I_total = I1 + I2 + I3). Exceder a corrente máxima nominal da fiação e da tomada (geralmente 10 A ou 20 A) gera sobreaquecimento resistivo Joule que derrete isolamentos plásticos e inicia incêndios.", "possui_imagem": false},
  {"id": 33, "uid": "CIEN-8-033", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Corrente Alternada (CA) vs. Corrente Contínua (CC)", "dificuldade": "Médio", "enunciado": "Pilhas comuns e baterias de automóveis fornecem Corrente Contínua (CC), enquanto a eletricidade que chega pelas tomadas de nossas casas é Corrente Alternada (CA, com frequência de 60 Hertz no Brasil). A diferença física entre esses dois tipos de corrente é:", "alternativas": {"A": "Na CC os elétrons nunca se movem; na CA eles viajam na velocidade da luz pelo ar.", "B": "Na Corrente Contínua os elétrons livres fluem em um único sentido constante; na Corrente Alternada o sentido de deslocamento dos elétrons inverte-se periodicamente para a frente e para trás várias vezes por segundo (60 vezes por segundo no Brasil).", "C": "A CC só funciona na água salgada e a CA só funciona no ar seco.", "D": "A CA não dá choque elétrico em seres humanos.", "E": "A CC é produzida exclusivamente por painéis solares à noite."}, "resposta_correta": "B", "justificativa": "Em CC (Direct Current), a polaridade é fixa e as cargas migram unidirecionalmente. Em CA (Alternating Current), a ddp senoidal inverte ciclicamente de sentido (frequência f = 60 Hz no Brasil), facilitando a elevação e rebaixamento de tensão por transformadores eletromagnéticos.", "possui_imagem": false},
  {"id": 34, "uid": "CIEN-8-034", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Dimensionamento de Fios Elétricos: Seção Transversal", "dificuldade": "Médio", "enunciado": "Na engenharia elétrica residencial, os circuitos que alimentam chuveiros elétricos exigem cabos de cobre grossos (com bitola de 6 mm² ou 10 mm²), enquanto circuitos de lâmpadas LED utilizam fios mais finos (1,5 mm²). A justificativa física para utilizar cabos mais grossos no chuveiro é:", "alternativas": {"A": "Cabos finos transmitem voltagens de 1.000 volts que quebram o chuveiro.", "B": "Pela Segunda Lei de Ohm, condutores com maior área de seção transversal apresentam menor resistência elétrica, permitindo a condução de correntes elevadas (acima de 30 ou 40 ampères) com mínima perda de calor e sem superaquecimento perigoso da fiação.", "C": "Cabos grossos são mais baratos de produzir e pesam menos.", "D": "Cabos finos só funcionam quando a água do chuveiro é quente.", "E": "A concessionária exige cabos grossos apenas por razões estéticas da parede."}, "resposta_correta": "B", "justificativa": "A Segunda Lei de Ohm estabelece que a resistência elétrica é inversamente proporcional à área da seção transversal do fio (R = ρ . L / A). Para correntes elevadas de aparelhos de alta potência, cabos com maior bitola reduzem a resistência R, minimizando quedas de tensão e dissipação excessiva de calor (P = R . I²).", "possui_imagem": false},
  {"id": 35, "uid": "CIEN-8-035", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Energia Solar: Sistema On-Grid vs. Off-Grid", "dificuldade": "Médio", "enunciado": "Sistemas de energia solar fotovoltaica podem ser instalados como 'on-grid' (conectados à rede) ou 'off-grid' (isolados da rede). Em propriedades rurais remotas ou comunidades isoladas na Amazônia onde não passam postes de luz da rede pública, utiliza-se obrigatoriamente o sistema off-grid, cujo funcionamento exige:", "alternativas": {"A": "A queima de carvão mineral sob os painéis durante a madrugada.", "B": "Bancos de baterias elétricas recarregáveis para armazenar a energia gerada durante o dia e fornecer eletricidade durante a noite e em dias chuvosos nublados.", "C": "Espelhos espaciais que refletem a luz do sol 24 horas por dia.", "D": "Fios submarinos de cobre conectados à cidade mais próxima.", "E": "Que os moradores durmam durante todo o período sem sol."}, "resposta_correta": "B", "justificativa": "Sistemas autônomos off-grid requerem controladores de carga e bancos de baterias eletroquímicas (como baterias estacionárias de chumbo-ácido ou íons de lítio) para desacoplar a geração diurna intermitente do consumo residencial noturno.", "possui_imagem": false},
  {"id": 36, "uid": "CIEN-8-036", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Aparelhos de Refrigeração e o Motor Inverter", "dificuldade": "Médio", "enunciado": "Geladeiras e condicionadores de ar modernos equipados com compressores de tecnologia 'Inverter' chegam a economizar até 40% a 60% de energia elétrica em relação a modelos convencionais. Essa economia expressiva de energia decorre do fato de que o motor Inverter:", "alternativas": {"A": "Desliga e liga o compressor com força máxima a cada dois minutos.", "B": "Ajusta continuamente a velocidade de rotação do compressor por controle eletrônico em vez de ficar ligando e desligando bruscamente, mantendo a temperatura estável e eliminando os picos de alta corrente de partida do motor.", "C": "Funciona sem queimar nenhuma substância química refrigerante.", "D": "Utiliza água da chuva para gerar frio sem eletricidade.", "E": "Opera exclusivamente em corrente contínua de pilhas pequenas."}, "resposta_correta": "B", "justificativa": "Compressores convencionais funcionam no modo liga-desliga (on/off): quando o termostato atinge a meta, o motor desliga; ao subir a temperatura, religa consumindo corrente de partida pico (inrush current). O inversor de frequência modula suavemente a rotação do motor em regime contínuo parcial, operando em altíssima eficiência térmica.", "possui_imagem": false},
  {"id": 37, "uid": "CIEN-8-037", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Biomassa na Geração Termelétrica no Brasil", "dificuldade": "Médio", "enunciado": "No setor sucroalcooleiro brasileiro, usinas termelétricas de biomassa geram grandes quantidades de eletricidade a partir da queima de resíduos agroindustriais. O principal combustível sólido renovável utilizado nessas usinas é:", "alternativas": {"A": "O óleo diesel refinado de petróleo fóssil.", "B": "O bagaço da cana-de-açúcar gerado após a moagem do caldo nas usinas.", "C": "O carvão mineral importado de navio da Europa.", "D": "Pneus velhos recolhidos das estradas pavimentadas.", "E": "Troncos de pau-brasil extraídos de parques nacionais."}, "resposta_correta": "B", "justificativa": "O bagaço de cana residual da moagem possui expressivo poder calorífico. Queimado em caldeiras de alta pressão com ciclos de cogeração turbinada, ele abastece integralmente a demanda elétrica da usina no período de safra e exporta excedentes volumosos de bioeletricidade limpa para o Sistema Interligado Nacional (SIN).", "possui_imagem": false},
  {"id": 38, "uid": "CIEN-8-038", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Leitura e Interpretação do Medidor de Energia (Relógio de Luz)", "dificuldade": "Médio", "enunciado": "O funcionário da concessionária de energia elétrica comparece à residência para realizar a leitura mensal do medidor de eletricidade. Se na leitura do mês anterior o relógio registrava 14.250 kWh e na leitura do mês atual ele registra 14.530 kWh, qual foi o consumo de energia da residência no período apurado?", "alternativas": {"A": "280 kWh.", "B": "530 kWh.", "C": "14.530 kWh.", "D": "28.780 kWh.", "E": "28 kWh."}, "resposta_correta": "A", "justificativa": "O consumo do período de faturamento é calculado pela diferença aritmética direta entre a leitura atual e a leitura anterior do medidor ciclométrico ou digital: Consumo = Leitura Atual - Leitura Anterior = 14.530 kWh - 14.250 kWh = 280 kWh.", "possui_imagem": false},
  {"id": 39, "uid": "CIEN-8-039", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Choque Elétrico e Efeitos no Corpo Humano", "dificuldade": "Médio", "enunciado": "A gravidade dos danos biológicos causados por um choque elétrico no corpo humano depende principalmente da intensidade da corrente elétrica (em miliampères, mA) que atravessa os órgãos vitais. Uma corrente elétrica de apenas 50 a 100 mA (0,05 a 0,1 A) atravessando o tórax humano pode causar parada cardiorrespiratória por desencadear:", "alternativas": {"A": "A queima imediata de todos os ossos do esqueleto.", "B": "Fibrilação ventricular do coração, desordenando os impulsos elétricos naturais do músculo cardíaco e impedindo o bombeamento eficaz de sangue para o cérebro.", "C": "A evaporação de toda a água presente no sangue da pessoa.", "D": "O crescimento acelerado das unhas e dos cabelos.", "E": "Congelamento instantâneo do estômago e intestino."}, "resposta_correta": "B", "justificativa": "O miocárdio é controlado por impulsos de potenciais de ação bioelétricos intrínsecos. Correntes externas da ordem de dezenas de miliampères que cruzem a região torácica interferem no período refratário cardíaco, deflagrando fibrilação ventricular desorganizada incompatível com a vida se não revertida por desfibrilador.", "possui_imagem": false},
  {"id": 40, "uid": "CIEN-8-040", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Resistores e Potência em Chuveiros de Duas Posições (Verão/Inverno)", "dificuldade": "Médio", "enunciado": "Em um chuveiro elétrico comum dotado de chave seletora Verão/Inverno alimentado por tensão constante de 127 V, para que o chuveiro esquente MAIS a água na posição 'Inverno', o circuito precisa ter maior potência (P = U² / R). Para aumentar a potência e aquecer mais a água no inverno, o chuveiro seleciona uma resistência elétrica de valor:", "alternativas": {"A": "Muito maior do que a resistência da posição verão.", "B": "Menor do que a resistência da posição verão, pois quanto menor a resistência para uma tensão constante, maior é a corrente elétrica e maior é a potência térmica dissipada.", "C": "Rigorosamente igual a zero sem nenhum fio condutor.", "D": "Infinito para bloquear a passagem de elétrons.", "E": "Negativo através de baterias auxiliares."}, "resposta_correta": "B", "justificativa": "Pela equação P = U² / R, como a tensão U é constante (127 V), a potência P é inversamente proporcional à resistência R. Para obter maior aquecimento (posição Inverno com 5.500 W), o aparelho conecta um trecho menor de resistor (menor resistência R), aumentando a corrente I e a dissipação de calor.", "possui_imagem": false},
  {"id": 41, "uid": "CIEN-8-041", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Eletricidade Estática no Dia a Dia", "dificuldade": "Médio", "enunciado": "Em dias de inverno com ar muito seco, ao caminhar sobre carpetes sintéticos e tocar na maçaneta metálica de uma porta ou sair de um carro, é comum levar um pequeno 'choque' com estalo audível. Esse choque cotidiano decorre de:", "alternativas": {"A": "Eletricidade que vazou da rede elétrica da rua através do chão.", "B": "Eletrização por atrito estático que acumulou excesso de cargas elétricas no corpo humano, as quais se descarregam repentinamente quando a pessoa se aproxima de um condutor metálico aterrado.", "C": "Vapor de água fervendo nos calçados da pessoa.", "D": "Atrito com o campo magnético do Polo Norte da Terra.", "E": "Queima de oxigênio pelas roupas de lã."}, "resposta_correta": "B", "justificativa": "O atrito triboelétrico entre calçados e superfícies sintéticas em ar seco (baixa umidade que impede a dissipação lenta de cargas) transfere elétrons, acumulando potencial eletrostático de milhares de volts no corpo humano; a aproximação de metal descarrega a centelha capacitiva instantânea.", "possui_imagem": false},
  {"id": 42, "uid": "CIEN-8-042", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Usinas Maremotrizes e Energia das Ondas", "dificuldade": "Médio", "enunciado": "Usinas maremotrizes geram eletricidade aproveitando o movimento periódico de subida e descida das marés oceânicas e as correntes marinhas. A fonte gravitacional cósmica primária responsável por movimentar as massas de água dos oceanos e viabilizar a energia maremotriz é:", "alternativas": {"A": "O calor de vulcões submarinos ativos no fundo do mar.", "B": "A atração gravitacional combinada da Lua e do Sol sobre as águas oceânicas da Terra.", "C": "A queima de combustíveis fósseis por navios cargueiros.", "D": "A rotação das hélices de submarinos nucleares.", "E": "A evaporação de água na foz dos rios amazônicos."}, "resposta_correta": "B", "justificativa": "As marés astronômicas oceânicas decorrem do gradiente diferencial de atração gravitacional exercido pela Lua (principalmente) e pelo Sol sobre a hidrosfera da Terra em rotação diária, fornecendo energia mecânica perene e previsível para turbinas de maré.", "possui_imagem": false},
  {"id": 43, "uid": "CIEN-8-043", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Primeira Lei de Ohm e Resistor Ôhmico", "dificuldade": "Difícil", "enunciado": "A Primeira Lei de Ohm estabelece que, para condutores mantidos a temperatura constante (resistores ôhmicos), a diferença de potencial elétrico aplicada é diretamente proporcional à intensidade da corrente que o atravessa (U = R . I). Se um aquecedor ôhmico alimentado por uma tensão de 120 V é percorrido por uma corrente de 10 A, qual será a corrente que o atravessará se ele for ligado a uma tomada de 60 V?", "alternativas": {"A": "2,5 A.", "B": "5,0 A.", "C": "10,0 A.", "D": "20,0 A.", "E": "40,0 A."}, "resposta_correta": "B", "justificativa": "Cálculo da resistência constante: R = U1 / I1 = 120 V / 10 A = 12 Ω. Ao aplicar nova tensão U2 = 60 V: I2 = U2 / R = 60 V / 12 Ω = 5,0 A (a corrente cai pela metade acompanhando proporcionalmente a tensão).", "possui_imagem": false},
  {"id": 44, "uid": "CIEN-8-044", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Segunda Lei de Ohm e Resistividade de Materiais", "dificuldade": "Difícil", "enunciado": "Dois fios condutores cilíndricos, X e Y, são feitos do mesmo material de cobre de alta pureza e possuem o mesmo comprimento L. O fio X possui o dobro do diâmetro transversal em relação ao fio Y (dx = 2 . dy). Sabendo que a área da seção transversal varia com o quadrado do diâmetro (A = π . d² / 4), qual é a relação correta entre a resistência elétrica do fio X (Rx) e a do fio Y (Ry)?", "alternativas": {"A": "Rx = 4 . Ry.", "B": "Rx = 2 . Ry.", "C": "Rx = Ry / 2.", "D": "Rx = Ry / 4 (o fio mais grosso tem 4 vezes menor resistência).", "E": "Rx = Ry (possuem a mesma resistência)."}, "resposta_correta": "D", "justificativa": "Pela Segunda Lei de Ohm: R = ρ . L / A. Se o diâmetro é o dobro, a área da seção transversal é Ax = π.(2d)²/4 = 4.Ay. Como a resistência é inversamente proporcional à área A, a resistência do fio X é Rx = Ry / 4.", "possui_imagem": false},
  {"id": 45, "uid": "CIEN-8-045", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Fator de Potência em Instalações Industriais", "dificuldade": "Difícil", "enunciado": "Em instalações elétricas industriais que utilizam centenas de motores elétricos de indução e transformadores, além da potência ativa útil (medida em kW), surge a chamada 'potência reativa indutiva' (medida em kvar). A circulação excessiva de potência reativa reduz o 'fator de potência' da indústria, acarretando como problema técnico direto:", "alternativas": {"A": "A queima imediata de lâmpadas LED dos escritórios.", "B": "O aumento desnecessário da corrente elétrica total circulante nos cabos e transformadores sem realizar trabalho útil, elevando as perdas por Efeito Joule e provocando quedas de tensão e cobrança de multas pela distribuidora se o fator de potência for inferior a 0,92.", "C": "A transformação de motores elétricos em baterias químicas líquidas.", "D": "O desligamento eterno de todas as usinas solares da região.", "E": "A redução da voltagem da tomada para zero."}, "resposta_correta": "B", "justificativa": "Cargas indutivas demandam campos magnéticos periódicos, criando corrente defasada (potência reativa). Essa corrente sobrecarrega cabos, transformadores e alimentadores sem produzir trabalho útil no eixo mecânico, exigindo correção por bancos de capacitores para manter FP ≥ 0,92 conforme regulação da ANEEL.", "possui_imagem": false},
  {"id": 46, "uid": "CIEN-8-046", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Curto-Circuito e Corrente de Interrupção de Disjuntores", "dificuldade": "Difícil", "enunciado": "Ao selecionar um disjuntor para o quadro geral de entrada de um edifício comercial próximo a um transformador de rua de grande porte, além da corrente nominal de disparo (como 50 A), o engenheiro eletricista deve verificar obrigatoriamente a 'Capacidade de Interrupção de Curto-Circuito' (expressa em kA, como 3 kA, 5 kA ou 10 kA). Esse parâmetro técnico representa:", "alternativas": {"A": "O tempo máximo em anos que o disjuntor dura na parede.", "B": "A corrente de curto-circuito máxima que o disjuntor é capaz de interromper em milissegundos com segurança física sem explodir, sem soldar seus contatos internos por arco elétrico e sem propagar fogo para o quadro.", "C": "A quantidade de água que o disjuntor consegue bombear no telhado.", "D": "O peso máximo que o disjuntor suporta pendurado nos cabos.", "E": "A voltagem solar gerada pelos polos magnéticos do disjuntor."}, "resposta_correta": "B", "justificativa": "A capacidade nominal de interrupção (Icn ou Icu em kA) define a máxima corrente de falha simétrica que a câmara de extinção de arco do disjuntor consegue extinguir sem soldar os contatos metálicos ou explodir sob o extremo estresse térmico e mecânico de um curto-circuito franco.", "possui_imagem": false},
  {"id": 47, "uid": "CIEN-8-047", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Efeito Joule em Supercondutores: Resistência Nula", "dificuldade": "Difícil", "enunciado": "Em aparelhos médicos de Ressonância Magnética (RMN) e em aceleradores de partículas de ponta, utilizam-se eletroímãs de materiais supercondutores mantidos resfriados com hélio líquido a temperaturas próximas do zero absoluto (-269 ºC / 4 Kelvin). A extraordinária vantagem eletrodinâmica dos supercondutores nessas máquinas é:", "alternativas": {"A": "Produzir energia a partir da luz do sol mesmo no escuro.", "B": "Apresentar resistência elétrica RIGOROSAMENTE NULA (R = 0), permitindo que correntes elétricas colossais circulem indefinidamente sem dissipar nenhum calor por Efeito Joule (P = R . I² = 0) e gerando campos magnéticos ultra-intensos com consumo quase nulo de energia de manutenção.", "C": "Transformar fios de cobre em ouro puro durante o exame.", "D": "Não precisar de computadores para processar imagens médicas.", "E": "Resfriar o paciente com gelo atômico durante o diagnóstico."}, "resposta_correta": "B", "justificativa": "Abaixo da temperatura crítica Tc, materiais supercondutores sofrem transição de fase quântica na qual pares de Cooper de elétrons fluem através da rede sem espalhamento inelástico; a resistividade cai a zero absoluto, viabilizando correntes de milhares de ampères sem perdas ôhmicas Joule.", "possui_imagem": false},
  {"id": 48, "uid": "CIEN-8-048", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Ressonância e Impedância em Circuitos RLC", "dificuldade": "Difícil", "enunciado": "Em circuitos eletrônicos sintonizadores presentes em rádios receptores e equipamentos de comunicação sem fio, utiliza-se a associação de resistores (R), indutores (L) e capacitores (C) em circuito RLC. Quando a frequência da onda eletromagnética captada coincide com a 'frequência de ressonância' natural do circuito (f = 1 / [2π.√(L.C)]):", "alternativas": {"A": "A corrente elétrica cai a zero e o rádio queima os alto-falantes.", "B": "A reatância indutiva anula a reatância capacitiva (XL = XC), a impedância total do circuito atinge seu valor mínimo estritamente resistivo e a corrente elétrica atinge amplitude máxima, selecionando com nitidez a estação emissora desejada.", "C": "A voltagem da bateria se transforma em energia solar líquida.", "D": "O circuito passa a funcionar como uma máquina a vapor de alta pressão.", "E": "Todos os capacitores explodem devido ao excesso de calor."}, "resposta_correta": "B", "justificativa": "Na condição de ressonância série em circuitos RLC, as reatâncias de fase oposta se cancelam perfeitamente: XL = ωL = 1/(ωC) = XC, resultando em impedância puramente resistiva Z = R (mínima). Isso gera um pico pronunciado de seletividade de corrente para a frequência angular ressonante exata.", "possui_imagem": false},
  {"id": 49, "uid": "CIEN-8-049", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Cálculo de Custo com Aparelhos de Uso Intermitente: Geladeira", "dificuldade": "Difícil", "enunciado": "O manual de uma geladeira moderna informa que o aparelho possui consumo mensal estimado de 45 kWh/mês. Sabendo que o compressor dessa geladeira tem potência nominal de 150 W quando está funcionando e desliga periodicamente ao atingir a temperatura programada, qual é a fração média do dia (fator de carga operacional) em que o motor do compressor permanece efetivamente ligado?", "alternativas": {"A": "Cerca de 10% do dia.", "B": "Cerca de 41,7% do dia (aproximadamente 10 horas ligada e 14 horas desligada em repouso por dia).", "C": "100% do dia ininterruptamente sem parar.", "D": "Cerca de 80% do dia.", "E": "Apenas 1% do dia."}, "resposta_correta": "B", "justificativa": "Cálculo: Consumo diário = 45 kWh / 30 dias = 1,5 kWh/dia = 1.500 Wh/dia. Tempo diário com motor ligado = Energia diária / Potência do motor = 1.500 Wh / 150 W = 10 horas/dia. Fração do dia = 10 h / 24 h = 0,4167 (aproximadamente 41,7% do tempo).", "possui_imagem": false},
  {"id": 50, "uid": "CIEN-8-050", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Linhas de Transmissão HVDC (Corrente Contínua de Alta Tensão)", "dificuldade": "Difícil", "enunciado": "Para transportar a imensa potência elétrica gerada na Usina Hidrelétrica de Belo Monte (no Pará) até os grandes centros de consumo no Sudeste (a mais de 2.000 km de distância), o Brasil construiu linhas de transmissão em Corrente Contínua de Alta Tensão (HVDC de ±800 kV) em vez da tradicional Corrente Alternada. A vantagem técnica do sistema HVDC para distâncias continentais superiores a 1.000 km é:", "alternativas": {"A": "Eliminar as perdas reativas capacitivas e indutivas intrínsecas às longas linhas de corrente alternada e requerer apenas dois condutores por circuito em vez de três fases, tornando a transmissão mais eficiente e econômica a longas distâncias.", "B": "Permitir que os elétrons pulem pelo ar sem tocar nos cabos de alumínio.", "C": "Fazer com que a energia chegue antes de ter sido gerada na usina.", "D": "Impedir que os cabos esquentem mesmo sem vento.", "E": "Transformar a eletricidade em combustível diesel no meio do caminho."}, "resposta_correta": "A", "justificativa": "Em linhas longas de CA (>600-800 km), o efeito de capacitância shunt distribuída e reatância indutiva gera corrente de carregamento massiva e perdas de estabilidade angular de sincronismo. Sistemas HVDC transmitem potência puramente ativa em dois polos (bipolo), sem perdas dielétricas por frequência de rede e com menor custo de torres.", "possui_imagem": false},
  {"id": 51, "uid": "CIEN-8-051", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Lei de Faraday-Lenz e Freio Magnético em Trens de Alta Velocidade", "dificuldade": "Difícil", "enunciado": "Trens de alta velocidade (como o Shinkansen e trens Maglev) utilizam sistemas de freio eletrodinâmico por Correntes de Foucault (Eddy currents). Quando um forte campo magnético é aproximado dos trilhos metálicos ou discos condutores em movimento sem tocá-los, o trem freia com suavidade e sem atrito mecânico porque:", "alternativas": {"A": "O ímã cola fisicamente no trilho como cola instantânea.", "B": "Pela Lei de Faraday e Lei de Lenz, a variação do fluxo magnético induz correntes elétricas circulares parasitas (correntes de Foucault) no metal, que geram campos magnéticos opostos que exercem uma força contrária ao movimento, convertendo a energia cinética do trem em calor dissipado no trilho.", "C": "O campo magnético congela o ar atmosférico ao redor do trem.", "D": "A velocidade do trem cai porque a eletricidade desliga os trilhos.", "E": "O atrito do ar com as janelas do trem atinge valor infinito."}, "resposta_correta": "B", "justificativa": "Pela Lei de Lenz, o sentido da corrente induzida opõe-se à causa que lhe deu origem (a variação temporal do fluxo magnético decorrente da translação relativa). As correntes circulares de Foucault no condutor geram forças de Lorentz orientadas no sentido oposto ao vetor velocidade (força de arrasto eletromagnético).", "possui_imagem": false},
  {"id": 52, "uid": "CIEN-8-052", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Células a Combustível vs. Baterias de Lítio: Termodinâmica", "dificuldade": "Difícil", "enunciado": "Diferente de uma bateria eletroquímica fechada (que armazena reagentes finitos dentro de sua carcaça selada e precisa ser recarregada lentamente quando descarrega), uma Célula a Combustível (como a de hidrogênio) é um conversor termodinâmico aberto que:", "alternativas": {"A": "Transforma calor em eletricidade através do ciclo de Carnot com rendimento de 20%.", "B": "Gera eletricidade e calor de forma contínua e ininterrupta enquanto for alimentada externamente por um fluxo contínuo de reagentes (combustível como H2 e comburente como O2), sem sofrer perdas por recarga interna de eletrólitos selados.", "C": "Opera exclusivamente em temperaturas de congelamento de -100 ºC.", "D": "Queima gasolina produzindo fuligem radioativa de carbono.", "E": "Destrói átomos de hidrogênio gerando luz estroboscópica pura."}, "resposta_correta": "B", "justificativa": "Baterias são dispositivos de armazenamento eletroquímico fechado cujo tempo de operação é limitado pela massa molar dos eletrodos incorporados. Células a combustível são conversores contínuos de energia eletroquímica livre de Gibbs (ΔG = -n.F.E) alimentados continuamente por fluxos externos de combustível e oxidante.", "possui_imagem": false},
  {"id": 53, "uid": "CIEN-8-053", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Efeito Peltier e Refrigeração Termoelétrica", "dificuldade": "Difícil", "enunciado": "Frigobares portáteis de viagem e sistemas de resfriamento de lasers de laboratório utilizam pastilhas semicondutoras de Efeito Peltier que resfriam sem utilizar compressores mecânicos nem gases refrigerantes. O funcionamento do Efeito Peltier consiste em:", "alternativas": {"A": "Produzir gelo por atrito de engrenagens de plástico internas.", "B": "Criar uma diferença de temperatura entre duas faces opostas de uma pastilha semicondutora quando uma corrente elétrica contínua a atravessa, absorvendo calor em uma face (resfriamento) e liberando calor na face oposta.", "C": "Queimar gás metano em alta pressão dentro de fios de cobre.", "D": "Transformar água da chuva em ar comprimido congelado.", "E": "Fazer os elétrons evaporarem para fora da pastilha metálica."}, "resposta_correta": "B", "justificativa": "O Efeito Peltier é o inverso do efeito Seebeck termelétrico: quando corrente contínua flui através de junções de semicondutores tipo p e tipo n com diferentes coeficientes de Seebeck, elétrons absorvem calor ao transicionar de bandas energéticas em uma junção (face fria) e o rejeitam na outra (face quente).", "possui_imagem": false},
  {"id": 54, "uid": "CIEN-8-054", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Equilíbrio de Carga em Smart Grids (Redes Elétricas Inteligentes)", "dificuldade": "Difícil", "enunciado": "Com a massiva entrada de painéis solares residenciais, fazendas eólicas e frotas de carros elétricos recarregando nas garagens, as redes elétricas modernas adotam o conceito de 'Smart Grids' (Redes Inteligentes). A engenharia fundamental de uma Smart Grid baseia-se em:", "alternativas": {"A": "Substituir todos os fios de cobre por cabos de borracha sem eletricidade.", "B": "Integrar sensores IoT, telemetria bidirecional em tempo real, algoritmos preditivos e automação de chaveamento para balancear instantaneamente a oferta intermitente e o consumo elétrico, prevenindo apagões e otimizando o fluxo de energia na rede.", "C": "Desligar todas as fábricas durante o período diurno de sol.", "D": "Fazer com que os carros elétricos gerem energia a partir de óleo diesel.", "E": "Impedir que residências vendam energia solar excedente para a rede."}, "resposta_correta": "B", "justificativa": "Smart Grids combinam sensoriamento fasorial em tempo real (PMUs), controle avançado de distribuição (ADMS) e inteligência artificial para coordenar recursos energéticos distribuídos (DERs), gerenciar resposta de demanda (Demand Response) e balancear fluxos bidirecionais de potência sem instabilidades de frequência.", "possui_imagem": false},
  {"id": 55, "uid": "CIEN-8-055", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Associação Mista de Resistores e Cálculo de Corrente", "dificuldade": "Difícil", "enunciado": "Considere um circuito composto por uma bateria ideal de 12 V conectada a uma associação mista de resistores: dois resistores idênticos de 6 Ω cada associados em paralelo entre si, e essa combinação colocada em série com um terceiro resistor de 7 Ω. Qual é a resistência equivalente total (Req) do circuito e qual é a corrente total (I) fornecida pela bateria?", "alternativas": {"A": "Req = 19 Ω e I = 0,63 A.", "B": "Req = 10 Ω e I = 1,2 A.", "C": "Req = 3 Ω e I = 4,0 A.", "D": "Req = 12 Ω e I = 1,0 A.", "E": "Req = 20 Ω e I = 0,6 A."}, "resposta_correta": "B", "justificativa": "Cálculo: Resistores de 6 Ω em paralelo: R_paralelo = (6 x 6) / (6 + 6) = 36 / 12 = 3 Ω. Esse bloco em série com o resistor de 7 Ω resulta em: Req = 3 Ω + 7 Ω = 10 Ω. Pela 1ª Lei de Ohm: I = U / Req = 12 V / 10 Ω = 1,2 A.", "possui_imagem": false},
  {"id": 56, "uid": "CIEN-8-056", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "O Efeito Corona em Linhas de Alta Tensão", "dificuldade": "Difícil", "enunciado": "Em dias úmidos ou com nevoeiro, pessoas que caminham sob torres de linhas de transmissão de altíssima tensão (500 kV) escutam um zumbido característico contínuo e, à noite, podem observar um brilho violeta tênue ao redor dos cabos. Esse fenômeno físico é o 'Efeito Corona', que ocorre porque:", "alternativas": {"A": "Os cabos de transmissão entram em combustão lenta com o oxigênio do ar.", "B": "O campo elétrico intenso na superfície dos cabos ultrapassa a rigidez dielétrica do ar ao redor, ionizando as moléculas de ar e provocando pequenas descargas elétricas parciais que geram ozônio, ruído audível e perda indesejada de energia.", "C": "O calor dos cabos ferve as gotas de chuva antes que elas toquem o chão.", "D": "O metal dos cabos de alumínio está derretendo e caindo como faíscas.", "E": "As torres de transmissão atraem ondas sonoras de estações de rádio."}, "resposta_correta": "B", "justificativa": "Quando o gradiente de potencial elétrico superficial do condutor excede a rigidez dielétrica do ar (aproximadamente 30 kV/cm em ar seco a 1 atm), ocorre ionização por impacto e quebra parcial do isolamento do ar (Efeito Corona), gerando emissão luminosa violeta, rádio-interferência e dissipação parasita de potência ativa.", "possui_imagem": false},
  {"id": 57, "uid": "CIEN-8-057", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Baterias de Íons de Lítio: Mecanismo de Intercalação", "dificuldade": "Difícil", "enunciado": "As baterias recarregáveis de íons de lítio que alimentam smartphones e veículos elétricos modernos ganharam o Prêmio Nobel de Química de 2019. O mecanismo eletroquímico que permite que essas baterias sejam recarregadas centenas de vezes sem destruir seus eletrodos sólidos é a:", "alternativas": {"A": "Combustão reversível de lítio metálico em água pura.", "B": "Intercalação e desintercalação reversível de íons de lítio (Li+) que migram e se alojam entre as camadas atômicas da rede cristalina do cátodo (óxido de metal de transição) e do ânodo (grafite), sem alterar de forma irreversível a estrutura do material.", "C": "Destruição atômica do grafite em cada ciclo de carga.", "D": "Fusão de núcleos de lítio para gerar átomos de hélio na bateria.", "E": "Transformação de íons de lítio em gás oxigênio respirável."}, "resposta_correta": "B", "justificativa": "Diferente de baterias primárias com dissolução e redeposição de fases, as baterias de íon-lítio operam pelo mecanismo 'rocking chair': cátions Li+ intercalam-se e desintercalam-se reversiblemente nos sítios intersticiais das estruturas lamelares do grafite e do óxido misto (LiCoO2/NMC), conferindo alta densidade energética e longa ciclabilidade.", "possui_imagem": false},
  {"id": 58, "uid": "CIEN-8-058", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Tarifação por Horário: Tarifa Branca no Brasil", "dificuldade": "Difícil", "enunciado": "No Brasil, os consumidores residenciais de baixa tensão podem optar pela modalidade de 'Tarifa Branca' da ANEEL. Nessa modalidade, o valor do kWh varia conforme o horário do dia: mais caro no 'horário de ponta' (início da noite, das 17h30 às 20h30), intermediário no horário intermediário e muito mais barato no 'horário fora de ponta' (madrugada e dia). O objetivo econômico e sistêmico dessa tarifação é:", "alternativas": {"A": "Punir financeiramente as famílias que têm crianças em idade escolar.", "B": "Incentivar os consumidores a deslocarem o uso de aparelhos de alta potência (como chuveiros, máquinas de lavar e ferros) para horários fora de ponta, aliviando o pico de demanda máxima que sobrecarrega as linhas de transmissão e geradores no início da noite.", "C": "Eliminar o uso de eletricidade em todas as indústrias aos finais de semana.", "D": "Forçar todas as casas a usarem geradores a diesel durante a noite.", "E": "Tornar a tarifa de energia igual em todos os estados da federação."}, "resposta_correta": "B", "justificativa": "A Tarifa Branca aplica sinais econômicos de preços marginais de ponta (Peak-Load Pricing). Como a infraestrutura do sistema elétrico nacional é dimensionada para atender a demanda de pico das 18h às 21h, modular o consumo residencial fora desse horário otimiza o uso de ativos instalados e evita o acionamento de termelétricas caras.", "possui_imagem": false},
  {"id": 59, "uid": "CIEN-8-059", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Rejeição de Calor em Usinas Termelétricas e Ciclo Rankine", "dificuldade": "Difícil", "enunciado": "Em uma usina termoelétrica operando sob o Ciclo Rankine, o vapor de água superaquecido a mais de 500 ºC sai da turbina de alta pressão e entra obrigatoriamente em um equipamento chamado 'condensador', onde é resfriado até voltar ao estado líquido para ser bombeado de volta à caldeira. O resfriamento do vapor até o estado líquido no condensador é indispensável porque:", "alternativas": {"A": "A caldeira só consegue queimar combustíveis se receber vapor fervendo.", "B": "Bombear água no estado líquido consome uma quantidade insignificante de energia mecânica da usina em comparação ao trabalho monumental e inviável que seria exigido para recomprimir vapor gasoso a alta pressão, viabilizando o rendimento líquido positivo do ciclo.", "C": "O vapor de água no estado gasoso é tóxico para os funcionários da usina.", "D": "A condensação transforma a água pura em petróleo pesado.", "E": "As turbinas elétricas não funcionam se houver eletricidade nos canos."}, "resposta_correta": "B", "justificativa": "Pela equação de trabalho de fluxo em bombas e compressores (W = ∫ v . dP), o volume específico da água líquida (v_liq ≈ 0,001 m³/kg) é centenas de vezes menor que o do vapor gasoso (v_vap > 0,1 m³/kg). A condensação permite bombear fluido incompressível com gasto ínfimo de potência de bombeamento, assegurando trabalho líquido substancial gerado pela turbina.", "possui_imagem": false},
  {"id": 60, "uid": "CIEN-8-060", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Relação entre Frequência de Rede (60 Hz) e Velocidade dos Geradores", "dificuldade": "Difícil", "enunciado": "No Sistema Interligado Nacional do Brasil, a frequência da corrente alternada é rigorosamente mantida em 60 Hertz (ciclos por segundo). Em uma usina hidrelétrica cujo gerador síncrono possui 72 polos magnéticos no rotor, qual deve ser a velocidade angular de rotação mecânica (em rotações por minuto, rpm) com que a turbina deve girar para produzir eletricidade exatamente a 60 Hz (f = [p . n] / 120)?", "alternativas": {"A": "50 rpm.", "B": "100 rpm.", "C": "120 rpm.", "D": "360 rpm.", "E": "1.800 rpm."}, "resposta_correta": "B", "justificativa": "Fórmula de máquinas síncronas: f = (p . n) / 120, onde f é a frequência em Hz, p é o número de polos magnéticos e n é a rotação em rpm. Isolando a velocidade de rotação: n = (120 . f) / p = (120 x 60) / 72 = 7.200 / 72 = 100 rpm.", "possui_imagem": false},
  {"id": 61, "uid": "CIEN-8-061", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Perigo de Incêndio por Conexões Frouxas (Resistência de Contato)", "dificuldade": "Difícil", "enunciado": "Muitos laudos periciais do Corpo de Bombeiros apontam que incêndios residenciais de origem elétrica começaram em emendas de fios mal isoladas ou parafusos frouxos nos bornes de disjuntores e tomadas de alta corrente. A física por trás desse tipo de acidente baseia-se no fato de que:", "alternativas": {"A": "Parafusos soltos atraem raios cósmicos de tempestades para a tomada.", "B": "Um aperto frouxo reduz a área de contato efetiva entre os metais, criando uma alta 'resistência de contato' concentrada em um ponto minúsculo; a passagem da corrente do aparelho dissipa calor extremo naquele ponto microscópico (P = R_contato . I²), atingindo temperaturas capazes de queimar os plásticos e inflamar forros.", "C": "Conexões soltas fazem a voltagem da rede subir de 127 V para 1.000 V.", "D": "O cobre se transforma em hidrogênio gasoso inflamável quando não é apertado.", "E": "A fiação solta faz com que a eletricidade flua apenas pelo ar da cozinha."}, "resposta_correta": "B", "justificativa": "A resistência de contato ôhmica surge em pontos de contato mecânico imperfeito ou frouxo. Como a dissipação térmica é proporcional ao produto da resistência local pelo quadrado da corrente (P = R . I²), uma resistência espúria de apenas 0,5 Ω conduzindo 20 A dissipa continuamente 200 W de calor concentrado, atingindo centenas de graus Celsius e ignificando materiais combustíveis vizinhos.", "possui_imagem": false},
  {"id": 62, "uid": "CIEN-8-062", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Armazenamento por Hidrelétricas Reversíveis (Pumped Hydro)", "dificuldade": "Difícil", "enunciado": "Em países com alta participação de energias renováveis intermitentes (como solar e eólica), utilizam-se em larga escala usinas 'hidrelétricas reversíveis' (pumped storage). A lógica operacional dessas instalações hidrelétricas consiste em:", "alternativas": {"A": "Fazer os rios correrem para trás em direção às nascentes durante o ano todo.", "B": "Nos horários em que há sobra de energia eólica/solar barata na rede, utilizar a eletricidade excedente para bombear água de um reservatório inferior para um reservatório superior; nos horários de pico ou falta de vento, a água é turbinada de volta para baixo gerando eletricidade limpa sob demanda imediata.", "C": "Transformar a água da represa em gás oxigênio engarrafado.", "D": "Operar as turbinas apenas quando a Lua estiver cheia no céu.", "E": "Despejar toda a água da represa no mar sem gerar eletricidade."}, "resposta_correta": "B", "justificativa": "Usinas reversíveis operam como gigantescas baterias mecânicas de armazenamento por gravidade com rendimento de ciclo completo de 70% a 80%: compram energia barata em vales de geração de baixo custo para bombear água e despacham energia na ponta do sistema com altíssima flexibilidade e inércia síncrona.", "possui_imagem": false},
  {"id": 63, "uid": "CIEN-8-063", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 16: Energia Elétrica, Consumo e Circuitos", "tema": "Impacto do Aquecimento Global na Matriz Elétrica Brasileira", "dificuldade": "Difícil", "enunciado": "Relatórios de vulnerabilidade climática indicam que a intensificação de secas extremas prolongadas associada às mudanças climáticas globais ameaça diretamente a segurança energética do Brasil. A vulnerabilidade estrutural da matriz elétrica brasileira reside no fato de que:", "alternativas": {"A": "O Brasil consome mais eletricidade do que todos os países da Europa somados.", "B": "A alta dependência de geração hidrelétrica torna o país vulnerável a regimes pluviométricos instáveis e secas nas principais bacias do Sudeste/Centro-Oeste; a escassez de chuvas esvazia os reservatórios de regularização plurianual, forçando o acionamento de termelétricas fósseis caras e poluentes e elevando o risco de racionamento.", "C": "As turbinas das usinas hidrelétricas derretem se a temperatura passar de 30 ºC.", "D": "O Brasil não possui linhas de transmissão conectando os estados.", "E": "A energia solar fotovoltaica para de funcionar em dias quentes de verão."}, "resposta_correta": "B", "justificativa": "Com grande predominância da geração hidrelétrica (~60%), a matriz brasileira depende da afluência hidrológica sazonal (ENA). Secas severas e mudanças no padrão de monções diminuem a vazão afluente aos reservatórios de acumulação, forçando o despacho emergencial de termelétricas de custo marginal de operação elevado e encarecendo as tarifas via bandeiras vermelhas.", "possui_imagem": false},
  {"id": 64, "uid": "CIEN-8-064", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Reprodução Assexuada: Conceito", "dificuldade": "Fácil", "enunciado": "A reprodução é a função biológica fundamental que garante a perpetuação das espécies. Na reprodução assexuada, os novos indivíduos são formados a partir de:", "alternativas": {"A": "Dois organismos parentais que realizam a troca de gametas haploides.", "B": "Um único organismo parental, sem a fusão de gametas (células sexuais), gerando descendentes geneticamente idênticos a ele (clones).", "C": "Fecundação de óvulos por espermatozoides de espécies diferentes.", "D": "Mutações intencionais provocadas pelo calor do sol.", "E": "Combinação de DNA de quatro progenitores distintos."}, "resposta_correta": "B", "justificativa": "A reprodução assexuada envolve mitoses sucessivas a partir de um único indivíduo parental, sem meiose gamética nem fecundação, originando clones geneticamente idênticos.", "possui_imagem": true},
  {"id": 65, "uid": "CIEN-8-065", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Bipartição ou Cissiparidade", "dificuldade": "Fácil", "enunciado": "Bactérias e protozoários unicelulares frequentemente se reproduzem dividindo uma única célula mãe ao meio para originar duas células filhas geneticamente iguais. Esse processo de reprodução assexuada é chamado de:", "alternativas": {"A": "Fecundação externa.", "B": "Bipartição (ou cissiparidade / divisão binária).", "C": "Partenogênese.", "D": "Ovoviviparidade.", "E": "Esporulação sexuada."}, "resposta_correta": "B", "justificativa": "A divisão binária (bipartição ou cissiparidade) é o tipo mais simples de reprodução assexuada em unicelulares: a célula duplica seu material genético e divide o citoplasma em duas células filhas equivalentes.", "possui_imagem": true},
  {"id": 66, "uid": "CIEN-8-066", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Brotamento em Cnidários e Leveduras", "dificuldade": "Fácil", "enunciado": "Em animais simples como as hidras de água doce e em fungos unicelulares como as leveduras do fermento, um pequeno broto cresce na superfície do corpo do genitor, desenvolve-se e pode se desprender para viver de forma independente. Esse tipo de reprodução assexuada é o:", "alternativas": {"A": "Brotamento (ou gemiparidade).", "B": "Fecundação cruzada.", "C": "Regeneração por fratura.", "D": "Estaquia vegetal.", "E": "Acasalamento interno."}, "resposta_correta": "A", "justificativa": "O brotamento caracteriza-se pela formação de uma protuberância (broto) no indivíduo parental que cresce por mitoses celulares sucessivas até atingir maturidade e destacar-se (ou formar colônias).", "possui_imagem": true},
  {"id": 67, "uid": "CIEN-8-067", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Fragmentação e Regeneração", "dificuldade": "Fácil", "enunciado": "Se uma planária (verme platelminto) for cortada transversalmente em três pedaços em um laboratório, cada um dos pedaços é capaz de regenerar as partes que faltam, originando três planárias completas e funcionais. Esse fenômeno é um exemplo de:", "alternativas": {"A": "Reprodução sexuada com fecundação externa.", "B": "Reprodução assexuada por fragmentação e regeneração tecidual.", "C": "Partenogênese artificial de anfíbios.", "D": "Metamorfose incompleta de larvas.", "E": "Hermafroditismo obrigatório."}, "resposta_correta": "B", "justificativa": "Planárias possuem células-tronco totipotentes abundantes (neoblastos) que proliferam rapidamente após a fragmentação do corpo, regenerando todos os tecidos e estruturas ausentes.", "possui_imagem": true},
  {"id": 68, "uid": "CIEN-8-068", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Propagação Vegetativa / Estaquia", "dificuldade": "Fácil", "enunciado": "Na agricultura e jardinagem, é muito comum cortar um pedaço do ramo de uma planta (como roseira ou mandioca) e fincá-lo na terra úmida para que ele desenvolva raízes e gere uma nova planta completa idêntica à planta mãe. Essa técnica é chamada de:", "alternativas": {"A": "Fecundação floral polinizada.", "B": "Estaquia (propagação vegetativa assexuada).", "C": "Partenogênese vegetal.", "D": "Clonagem por sementes híbridas.", "E": "Inseminação artificial de pólen."}, "resposta_correta": "B", "justificativa": "A estaquia utiliza a capacidade de células meristemáticas vegetais indiferenciadas de formar raízes adventícias e brotos a partir de fragmentos de órgãos vegetativos (caule, folhas), clonando a planta de interesse.", "possui_imagem": true},
  {"id": 69, "uid": "CIEN-8-069", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Reprodução Sexuada: Gametas e Fecundação", "dificuldade": "Fácil", "enunciado": "A reprodução sexuada é caracterizada pelo encontro e pela fusão de células sexuais especializadas (gametas). A união do gameta masculino com o gameta feminino recebe o nome biológico de:", "alternativas": {"A": "Brotamento.", "B": "Fecundação (ou fertilização).", "C": "Mitose celular.", "D": "Metamorfose.", "E": "Partenogênese."}, "resposta_correta": "B", "justificativa": "A fecundação é o evento central da reprodução sexuada, correspondendo à penetração do espermatozoide no ovócito e à fusão de seus pronúcleos (cariogamia), originando a célula-ovo ou zigoto.", "possui_imagem": true},
  {"id": 70, "uid": "CIEN-8-070", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Grande Vantagem da Reprodução Sexuada: Variabilidade", "dificuldade": "Fácil", "enunciado": "A principal vantagem evolutiva da reprodução sexuada em relação à reprodução assexuada para as espécies de seres vivos é a:", "alternativas": {"A": "Produção de descendentes sempre 100% idênticos aos pais.", "B": "Geração de grande variabilidade genética entre os descendentes, aumentando as chances de a população se adaptar e sobreviver caso o ambiente sofra alterações.", "C": "Velocidade muito mais rápida de reprodução sem gastar energia.", "D": "Ausência de necessidade de encontrar parceiros sexuais.", "E": "Imunidade absoluta a qualquer doença infecciosa."}, "resposta_correta": "B", "justificativa": "A recombinação gênica gerada pelo crossing-over na meiose e a união aleatória de gametas geram filhos com combinações alélicas inéditas, proporcionando matéria-prima genética para a seleção natural.", "possui_imagem": true},
  {"id": 71, "uid": "CIEN-8-071", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Fecundação Externa", "dificuldade": "Fácil", "enunciado": "Em muitos animais aquáticos, como sapos e a maioria dos peixes ósseos, os machos e as fêmeas liberam seus óvulos e espermatozoides diretamente na água, onde os gametas se encontram e ocorre a fertilização. Esse tipo de fecundação é classificado como:", "alternativas": {"A": "Fecundação interna.", "B": "Fecundação externa.", "C": "Brotamento aquático.", "D": "Partenogênese marinha.", "E": "Reprodução assexuada de rio."}, "resposta_correta": "B", "justificativa": "A fecundação externa ocorre fora do trato genital dos progenitores, diretamente no meio aquático circundante, sendo típica de animais que não possuem órgãos copuladores intromitentes.", "possui_imagem": true},
  {"id": 72, "uid": "CIEN-8-072", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Fecundação Interna", "dificuldade": "Fácil", "enunciado": "Répteis, aves e mamíferos apresentam fecundação interna, na qual o macho deposita os espermatozoides diretamente no interior do sistema reprodutor da fêmea. A grande vantagem da fecundação interna para os animais terrestres é:", "alternativas": {"A": "Fazer os filhotes nascerem já adultos e prontos para caçar.", "B": "Proteger os gametas contra a desidratação no ambiente seco terrestre e aumentar significativamente a probabilidade de encontro e fertilização.", "C": "Permitir que a fêmea coloque ovos sem precisar de espermatozoides.", "D": "Eliminar totalmente o gasto de energia com a reprodução.", "E": "Fazer todos os filhotes serem do sexo masculino."}, "resposta_correta": "B", "justificativa": "No meio aéreo seco, gametas livres sofreriam dessecação instantânea. A fecundação interna fornece um microambiente aquoso protegido dentro das vias genitais femininas, poupando gametas e garantindo a fertilização.", "possui_imagem": true},
  {"id": 73, "uid": "CIEN-8-073", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Animais Ovíparos", "dificuldade": "Fácil", "enunciado": "Animais como galinhas, tartarugas marinhas e a maioria dos insetos botam ovos no ambiente externo, e o desenvolvimento embrionário dos filhotes ocorre inteiramente fora do corpo materno, alimentando-se do vitelo contido no ovo. Esses animais são classificados como:", "alternativas": {"A": "Vivíparos.", "B": "Ovíparos.", "C": "Ovovivíparos.", "D": "Marsupiais.", "E": "Hermafroditas estritos."}, "resposta_correta": "B", "justificativa": "Animais ovíparos depositam ovos fertilizados no ambiente externo; o embrião desenvolve-se e eclode fora do organismo da mãe, suprido exclusivamente pelas reservas energéticas vitelínicas do ovo.", "possui_imagem": true},
  {"id": 74, "uid": "CIEN-8-074", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Animais Vivíparos", "dificuldade": "Fácil", "enunciado": "Cães, gatos, cavalos e os seres humanos são exemplos de animais vivíparos. Nesses animais, o desenvolvimento do embrião ocorre:", "alternativas": {"A": "Dentro de uma casca de ovo de pedra deixada no chão seco.", "B": "Inteiramente no interior do corpo materno (no útero), onde o embrião recebe oxigênio e nutrientes diretamente do sangue da mãe através da placenta até o nascimento.", "C": "Dentro da água de um lago onde a mãe joga o embrião recém-fecundado.", "D": "Nas penas das asas do pai durante o voo.", "E": "Exclusivamente durante os meses de inverno."}, "resposta_correta": "B", "justificativa": "A viviparidade caracteriza-se pelo desenvolvimento intrauterino completo com conexão fisiológica materno-fetal ativa (via placenta nos eutérios), parindo filhotes já formados.", "possui_imagem": true},
  {"id": 75, "uid": "CIEN-8-075", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Animais Ovovivíparos", "dificuldade": "Fácil", "enunciado": "Algumas espécies de tubarões, raias e serpentes (como a jararaca e a cascavel) são classificadas como ovovivíparas. Nesses animais:", "alternativas": {"A": "A fêmea bota ovos sem casca que eclodem em poças de água.", "B": "Os ovos com casca permanecem retidos no interior do corpo da mãe até a eclosão, de modo que o embrião se nutre do vitelo do ovo e os filhotes já nascem vivos e livres da mãe.", "C": "Os filhotes são amamentados por glândulas mamárias aquáticas.", "D": "Não há necessidade de machos para fecundar os óvulos.", "E": "A reprodução é exclusivamente assexuada por bipartição."}, "resposta_correta": "B", "justificativa": "Na ovoviviparidade, os ovos providos de vitelo desenvolvem-se no oviduto materno sem trocas nutricionais diretas (nutrição lecitotrófica); no momento do parto, o filhote rompe a casca e é expelido vivo.", "possui_imagem": true},
  {"id": 76, "uid": "CIEN-8-076", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Conceito de Cuidado Parental", "dificuldade": "Fácil", "enunciado": "O conjunto de comportamentos e investimentos de tempo e energia que os pais dedicam para proteger, alimentar, aquecer e ensinar os filhotes após o nascimento ou postura dos ovos é denominado:", "alternativas": {"A": "Efeito Joule biológico.", "B": "Cuidado parental.", "C": "Metamorfose reflexa.", "D": "Partenogênese ativa.", "E": "Seleção artificial agrícola."}, "resposta_correta": "B", "justificativa": "Cuidado parental designa qualquer investimento comportamental ou fisiológico pós-zigótico fornecido pelos progenitores que eleve as probabilidades de sobrevivência e sucesso reprodutivo da prole.", "possui_imagem": true},
  {"id": 77, "uid": "CIEN-8-077", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Animais Hermafroditas (Monoicos)", "dificuldade": "Fácil", "enunciado": "Animais como a minhoca da terra e o caracol de jardim possuem tanto o sistema reprodutor masculino quanto o sistema reprodutor feminino no mesmo indivíduo. Esses animais são chamados biologicamente de:", "alternativas": {"A": "Dioicos (sexos separados).", "B": "Hermafroditas (ou monoicos).", "C": "Assexuados estritos.", "D": "Clones bacterianos.", "E": "Partenogênicos puros."}, "resposta_correta": "B", "justificativa": "Espécies monoicas (hermafroditas) apresentam gônadas e ductos funcionais de ambos os sexos no mesmo organismo adulto. Na minhoca, dois indivíduos realizam fecundação cruzada recíproca.", "possui_imagem": true},
  {"id": 78, "uid": "CIEN-8-078", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Fecundação Cruzada em Hermafroditas", "dificuldade": "Fácil", "enunciado": "Embora possuam os dois sexos no mesmo corpo, as minhocas geralmente não realizam a autofecundação; elas se unem em pares (cópula) e trocam espermatozoides mutuamente (fecundação cruzada). A importância biológica de realizar fecundação cruzada em vez de autofecundação é:", "alternativas": {"A": "Fazer os filhotes nascerem com penas de ave.", "B": "Garantir a recombinação genética e a variabilidade dos filhotes, unindo genes de dois indivíduos diferentes.", "C": "Economizar tempo para que as minhocas não precisem se alimentar.", "D": "Fazer com que apenas um dos indivíduos fique grávido.", "E": "Evitar que as minhocas precisem viver na terra úmida."}, "resposta_correta": "B", "justificativa": "A autofecundação gera homozigose e expressa alelos deletérios recessivos. A fecundação cruzada recíproca entre dois hermafroditas promove heterozigose e recombinação gênica ampla.", "possui_imagem": false},
  {"id": 79, "uid": "CIEN-8-079", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Dimorfismo Sexual", "dificuldade": "Fácil", "enunciado": "Em muitas espécies animais, machos e fêmeas adultos apresentam diferenças anatômicas externas marcantes de tamanho, cor, presença de chifres ou plumagem (como o leão com juba e a leoa sem juba, ou o pavão colorido e a fêmea marrom). Essa diferença morfológica externa entre os sexos é denominada:", "alternativas": {"A": "Hermafroditismo sequencial.", "B": "Dimorfismo sexual.", "C": "Metamorfose incompleta.", "D": "Bipartição diferenciada.", "E": "Partenogênese externa."}, "resposta_correta": "B", "justificativa": "Dimorfismo sexual é a diferenciação fenotípica externa (tamanho, ornamentos, plumagens, apêndices) manifestada entre machos e fêmeas da mesma espécie, impulsionada pela seleção sexual.", "possui_imagem": false},
  {"id": 80, "uid": "CIEN-8-080", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Rituais de Corte no Reino Animal", "dificuldade": "Fácil", "enunciado": "Apresentações de danças acrobáticas, cantos melodiosos, construção de ninhos decorados com flores e oferendas de alimentos realizadas por machos de muitas espécies de aves e peixes durante a época de acasalamento são exemplos de:", "alternativas": {"A": "Agressividade predatória canibal.", "B": "Rituais de corte (ou cortejo reprodutivo) para atrair e conquistar a fêmea.", "C": "Comportamentos de hibernação polar.", "D": "Mimetismo contra predadores da floresta.", "E": "Luta corporal com morte obrigatória."}, "resposta_correta": "B", "justificativa": "Rituais de cortejo constituem sinais comportamentais estereotipados intraespecíficos que comunicam prontidão fisiológica, compatibilidade de espécie e vigor genético para a escolha do parceiro.", "possui_imagem": false},
  {"id": 81, "uid": "CIEN-8-081", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "A Partenogênese", "dificuldade": "Fácil", "enunciado": "Na colmeia de abelhas, a rainha põe dois tipos de ovos: os ovos fecundados por espermatozoides de zangão originam operárias fêmeas ou novas rainhas; já os ovos que NÃO foram fecundados desenvolvem-se espontaneamente dando origem exclusivamente a zangões machos. Esse tipo de reprodução no qual o óvulo se desenvolve em um embrião sem ter sido fecundado é chamado de:", "alternativas": {"A": "Brotamento externo.", "B": "Partenogênese.", "C": "Cissiparidade múltipla.", "D": "Estaquia celular.", "E": "Fecundação cruzada."}, "resposta_correta": "B", "justificativa": "A partenogênese (do grego parthenos = virgem; genesis = origem) é o desenvolvimento de um gameta feminino em um novo organismo sem a contribuição genética de um gameta masculino (arrenótoca nas abelhas).", "possui_imagem": false},
  {"id": 82, "uid": "CIEN-8-082", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Gametas: Espermatozoide vs. Óvulo", "dificuldade": "Fácil", "enunciado": "Na grande maioria dos animais de reprodução sexuada, existe uma divisão nítida de papéis anatômicos entre o gameta masculino e o feminino. Assinale a alternativa que compara corretamente os dois gametas:", "alternativas": {"A": "O espermatozoide é gigante e imóvel; o óvulo é microscópico e tem cauda.", "B": "O espermatozoide é pequeno, ágil e dotado de flagelo para natação; o óvulo (ovócito) é muito maior, imóvel e rico em substâncias nutritivas de reserva (vitelo).", "C": "Ambos são células idênticas no tamanho, forma e função.", "D": "O espermatozoide possui 100 núcleos e o óvulo não tem nenhum.", "E": "O óvulo é produzido em bilhões todos os dias e o espermatozoide apenas um por mês."}, "resposta_correta": "B", "justificativa": "A anisogamia clássica diferencia os gametas: o micrómeta masculino (espermatozoide) é diminuto, hidrodinâmico e flagelado para locomoção ativa; o macrógameta feminino (ovócito) é volumoso, acumulando vitelo e organelas para nutrir o embrião inicial.", "possui_imagem": false},
  {"id": 83, "uid": "CIEN-8-083", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Reprodução em Plantas com Flores (Angiospermas)", "dificuldade": "Fácil", "enunciado": "Nas plantas com flores (angiospermas), a reprodução sexuada envolve o transporte do grão de pólen da antera de uma flor até o estigma da mesma flor ou de outra flor da mesma espécie. Esse transporte de pólen é chamado de:", "alternativas": {"A": "Fotossíntese floral.", "B": "Polinização.", "C": "Germinação de sementes.", "D": "Transpiração estomática.", "E": "Digestão de seiva."}, "resposta_correta": "B", "justificativa": "A polinização é a transferência do grão de pólen (que abriga o gametófito masculino) até o órgão receptor feminino da flor (estigma), mediada pelo vento (anemofilia), insetos (entomofilia) ou aves (ornitofilia).", "possui_imagem": false},
  {"id": 84, "uid": "CIEN-8-084", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Esporos em Fungos", "dificuldade": "Fácil", "enunciado": "Muitos fungos (como o bolor de pão e os cogumelos) liberam no ar milhões de estruturas celulares minúsculas e resistentes chamadas esporos, que voam com o vento e germinam ao encontrar um local úmido e com alimento. Esse processo de reprodução assexuada é a:", "alternativas": {"A": "Fecundação interna aquática.", "B": "Esporulação.", "C": "Partenogênese fúngica.", "D": "Metamorfose de levedura.", "E": "Bipartição embrionária."}, "resposta_correta": "B", "justificativa": "A esporulação consiste na produção massiva de células reprodutivas especializadas leves e desidratadas (esporos mitóticos/mitósporos) dotadas de parede espessa que garantem ampla dispersão anemocórica.", "possui_imagem": false},
  {"id": 85, "uid": "CIEN-8-085", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Trade-off Evolutivo: Estratégia r vs. Estratégia K", "dificuldade": "Médio", "enunciado": "Em ecologia e biologia evolutiva, as espécies utilizam diferentes estratégias de alocação de energia para reprodução. A comparação correta entre a 'Estratégia r' (como a da sardinha e da rã) e a 'Estratégia K' (como a da baleia e do elefante) é:", "alternativas": {"A": "Estratégia r: poucos filhotes e intenso cuidado parental; Estratégia K: milhões de ovos e nenhum cuidado parental.", "B": "Estratégia r: produção de grande número de filhotes com baixo investimento por descendente e sem cuidado parental (alta mortalidade juvenil); Estratégia K: produção de poucos filhotes com alto investimento energético em cuidado parental e proteção até a fase adulta.", "C": "Ambas as estratégias produzem o mesmo número de filhotes e duram o mesmo tempo.", "D": "A estratégia r é exclusiva de plantas e a K é exclusiva de bactérias.", "E": "A estratégia K gasta zero de energia porque os filhotes não comem."}, "resposta_correta": "B", "justificativa": "Espécies r-estrategistas investem em taxa intrínseca de crescimento populacional rápido produzindo prole numerosa com alta mortalidade; K-estrategistas vivem próximos da capacidade de suporte do meio (K), investindo pesado em poucos descendentes com alta sobrevivência juvenil assegurada pelo cuidado parental.", "possui_imagem": false},
  {"id": 86, "uid": "CIEN-8-086", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Custos Biológicos da Reprodução Sexuada", "dificuldade": "Médio", "enunciado": "Embora a reprodução sexuada seja amplamente predominante entre os animais devido à variabilidade genética gerada, ela envolve o chamado 'duplo custo do sexo' em comparação à reprodução assexuada. Esse custo biológico refere-se ao fato de que:", "alternativas": {"A": "A reprodução sexuada exige produzir machos (que não geram filhotes diretamente), demanda tempo e energia para encontrar parceiros e aumenta o risco de predação e contágio por doenças durante a cópula.", "B": "A reprodução sexuada destrói todos os genes bons da mãe a cada geração.", "C": "Filhotes gerados por reprodução sexuada nunca sobrevivem ao primeiro dia.", "D": "Os machos morrem imediatamente após produzirem espermatozoides.", "E": "A reprodução sexuada só pode ocorrer uma vez a cada cem anos."}, "resposta_correta": "A", "justificativa": "O 'custo dos machos' (two-fold cost of sex de Maynard Smith) indica que populações assexuadas de fêmeas partenogênicas podem crescer o dobro da velocidade porque todas as proles são reprodutoras, além de que a reprodução sexuada despende recursos em cortejo e acasalamento.", "possui_imagem": false},
  {"id": 87, "uid": "CIEN-8-087", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Vantagem da Reprodução Assexuada em Ambientes Estáveis", "dificuldade": "Médio", "enunciado": "Em ambientes ecologicamente favoráveis, estáveis e com recursos abundantes (como uma cultura de bactérias em placa de laboratório rica em nutrientes ou plantas colonizando uma clareira nova), a reprodução assexuada apresenta como grande vantagem imediata:", "alternativas": {"A": "Aumentar a variedade de cores dos indivíduos da colônia.", "B": "Permitir uma rápida e exponencial multiplicação populacional sem a necessidade de gastar tempo ou energia procurando e disputando parceiros sexuais, perpetuando genótipos já comprovadamente bem adaptados àquele nicho.", "C": "Eliminar todas as bactérias que possuem DNA na célula.", "D": "Garantir que os descendentes sejam mais fortes que qualquer predador.", "E": "Fazer com que a espécie viva sem consumir alimento."}, "resposta_correta": "B", "justificativa": "A reprodução assexuada clonal é metabolicamente econômica e de cinética rápida: ela duplica a população em tempo mínimo e não desfaz combinações gênicas vantajosas pré-adaptadas àquele ambiente homogêneo.", "possui_imagem": false},
  {"id": 88, "uid": "CIEN-8-088", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "A Hipótese da Rainha Vermelha e a Coevolução com Parasitas", "dificuldade": "Médio", "enunciado": "A famosa 'Hipótese da Rainha Vermelha' (proposta pelo biólogo Leigh Van Valen) utiliza a frase do livro Alice no País das Maravilhas ('aqui é preciso correr o máximo possível apenas para permanecer no mesmo lugar') para explicar por que a reprodução sexuada é tão vantajosa no reino animal. Sob a ótica dessa teoria, a recombinação sexual contínua é crucial para:", "alternativas": {"A": "Fazer os animais correrem mais rápido que guepardos no cerrado.", "B": "Produzir continuamente combinações genéticas inéditas e diversificadas a cada geração, impedindo que parasitas e patógenos (como vírus e bactérias que evoluem rapidamente) 'decifrem' e aniquilem toda a população com uma mesma chave biológica infecciosa.", "C": "Evitar que as presas sejam enxergadas por predadores à noite.", "D": "Aumentar o peso dos animais para suportar invernos frios.", "E": "Fazer os machos viverem dez vezes mais que as fêmeas."}, "resposta_correta": "B", "justificativa": "A hipótese da Rainha Vermelha sustenta que a corrida armamentista coevolutiva contra patógenos e parasitas de ciclo curto seleciona o sexo: populações clonais idênticas são alvos fáceis para patógenos adaptados; a variabilidade sexual embaralha as defesas imunológicas a cada geração.", "possui_imagem": false},
  {"id": 89, "uid": "CIEN-8-089", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Hermafroditismo Sequencial: Peixes Palhaço", "dificuldade": "Médio", "enunciado": "Nos peixes-palhaço (Amphiprion), que vivem em anêmonas-do-mar, os grupos sociais são formados por uma fêmea dominante grande, um macho reprodutor e machos juvenis menores. Se a fêmea do grupo morrer, o maior macho sofre uma transformação hormonal e anatômica em poucas semanas, mudando de sexo e tornando-se a nova fêmea reprodutora do grupo. Esse tipo de reprodução é denominado:", "alternativas": {"A": "Partenogênese arrenótoca.", "B": "Hermafroditismo sequencial (do tipo protandria, onde o indivíduo é macho primeiro e depois torna-se fêmea).", "C": "Brotamento terminal de brânquias.", "D": "Metamorfose larval de girino.", "E": "Reprodução assexuada por cissiparidade."}, "resposta_correta": "B", "justificativa": "A protandria é uma forma de hermafroditismo sequencial onde o animal amadurece inicialmente como macho funcional e, sob gatilhos sociais ou de tamanho corporal, diferencia gônadas ovarianas e torna-se fêmea reprodutora.", "possui_imagem": false},
  {"id": 90, "uid": "CIEN-8-090", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Polinização Cruzada e Mecanismos Anti-Autopolinização em Plantas", "dificuldade": "Médio", "enunciado": "Muitas espécies de plantas com flores hermafroditas (que possuem estames masculinos e carpelos femininos na mesma flor) desenvolveram mecanismos para impedir a autopolinização, como a maturação dos grãos de pólen em datas diferentes da receptividade do estigma (dicogamia). O objetivo biológico de evitar a autopolinização é:", "alternativas": {"A": "Impedir que a flor produza pétalas coloridas de proteção.", "B": "Favorecer a polinização cruzada com flores de outras plantas vizinhas, promovendo a troca de genes e a variabilidade genética das sementes formadas.", "C": "Fazer com que a flor produza frutos sem nenhuma semente dentro.", "D": "Economizar néctar expulsando todos os insetos e abelhas do jardim.", "E": "Evitar que as raízes da planta absorvam água do solo."}, "resposta_correta": "B", "justificativa": "Mecanismos como dicogamia (protandria/protoginia) e autoincompatibilidade genética forçam o fluxo gênico intercruzado via polinizadores, maximizando a heterozigose e o vigor híbrido nas sementes geradas.", "possui_imagem": false},
  {"id": 91, "uid": "CIEN-8-091", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Cuidado Biparental em Aves Monogâmicas", "dificuldade": "Médio", "enunciado": "Em cerca de 90% das espécies de aves (como pinguins, albatrozes e araras), o cuidado parental é biparental, com machos e fêmeas compartilhando ativamente a construção do ninho, a incubação dos ovos e a alimentação dos filhotes. A causa ecológica predominante para essa cooperação de ambos os pais em aves é:", "alternativas": {"A": "O fato de as aves não terem bico suficiente para se alimentar sozinhas.", "B": "A alta taxa metabólica endotérmica e a vulnerabilidade dos filhotes recém-eclodidos (filhotes altriciais que nascem nus e cegos), que demandam tanta comida e aquecimento contínuo que um único progenitor sozinho não conseguiria criá-los com sucesso.", "C": "A ausência de predadores carnívoros no ambiente aéreo.", "D": "O fato de os machos botarem a metade dos ovos do ninho.", "E": "A obrigação imposta pelo líder do bando de aves migratórias."}, "resposta_correta": "B", "justificativa": "Filhotes altriciais nidícolas exigem aquecimento ininterrupto e suprimento calórico intenso de insetos ou peixes a cada poucas horas; o custo bioenergético excede a capacidade de forrageamento de um único progenitor, selecionando a monogamia social cooperativa.", "possui_imagem": false},
  {"id": 92, "uid": "CIEN-8-092", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Parasitismo de Ninho: O Caso do Chupim e Cuco", "dificuldade": "Médio", "enunciado": "Aves como o chupim (Molothrus bonariensis) no Brasil e o cuco comum na Europa não constroem ninhos nem chocam seus próprios ovos. As fêmeas dessas espécies colocam seus ovos furtivamente nos ninhos de outras aves menores (como o tico-tico), que acabam chocando o ovo e alimentando o filhote invasor como se fosse seu. Essa estratégia reprodutiva é denominada:", "alternativas": {"A": "Predação mútua simbiótica.", "B": "Parasitismo de ninho (ou parasitismo reprodutivo).", "C": "Comensalismo alimentar aéreo.", "D": "Partenogênese cruzada de ninho.", "E": "Mutualismo facultativo cooperativo."}, "resposta_correta": "B", "justificativa": "O parasitismo de ninhada transfere 100% dos custos energéticos de incubação e aprovisionamento de alimento para a espécie hospedeira; filhotes parasitas frequentemente eclodem antes e empurram os ovos e filhotes legítimos para fora do ninho.", "possui_imagem": false},
  {"id": 93, "uid": "CIEN-8-093", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Estolhos e Tubérculos: Reprodução Vegetativa Natural", "dificuldade": "Médio", "enunciado": "Morangueiros produzem caules rasteiros finos chamados estolhos que crescem sobre o solo e emitem raízes e folhas nos nós formando novas mudas. A batata-inglesa produz caules subterrâneos intumescidos cheios de amido (tubérculos) com 'olhos' que brotam na primavera. Essas estruturas representam formas naturais de:", "alternativas": {"A": "Reprodução sexuada com fecundação por morcegos.", "B": "Reprodução assexuada por propagação vegetativa clonal.", "C": "Polinização por vento frio de montanha.", "D": "Esporulação bacteriana da terra.", "E": "Desenvolvimento de frutos carnosos com sementes."}, "resposta_correta": "B", "justificativa": "Estolhos, rizomas, tubérculos e bulbos são adaptações caulinares com gemas meristemáticas que proliferam mitoticamente, propagando a planta assexuadamente e acumulando reservas energéticas para a rebrota.", "possui_imagem": false},
  {"id": 94, "uid": "CIEN-8-094", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Seleção Sexual: Caracteres Epigâmicos e Teoria de Darwin", "dificuldade": "Médio", "enunciado": "Em 1871, Charles Darwin publicou a teoria da Seleção Sexual para explicar características anatômicas extravagantes em machos que pareciam contradizer a seleção natural clássica (como a cauda gigantesca e pesada do pavão, que dificulta o voo e chama a atenção de predadores). Darwin explicou que essas estruturas persistem na população porque:", "alternativas": {"A": "Elas ajudam o pavão a assustar o frio do inverno nas montanhas.", "B": "Embora possam reduzir ligeiramente a sobrevivência individual do macho, aumentam exponencialmente seu sucesso em disputas de acasalamento e na preferência das fêmeas, garantindo que ele deixe mais descendentes com seus genes.", "C": "Elas servem para armazenar água potável durante secas na savana.", "D": "Elas transformam o pavão em uma fêmea quando ele chega à velhice.", "E": "Elas atraem insetos que limpam as penas da ave gratuitamente."}, "resposta_correta": "B", "justificativa": "A seleção sexual opera sobre o sucesso reprodutivo diferencial: ornamentos sexuais secundários hipertrofiados são selecionados se a vantagem obtida no acesso a parceiras reprodutivas superar o custo de sobrevivência imposto pela predação.", "possui_imagem": false},
  {"id": 95, "uid": "CIEN-8-095", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Fecundação Externa e Sincronia Reprodutiva nos Recifes de Corais", "dificuldade": "Médio", "enunciado": "Em grandes barreiras de recifes de corais, como na Austrália e no Caribe, colônias inteiras de centenas de espécies de corais desovam simultaneamente em uma única noite do ano, liberando bilhões de gametas que formam uma 'sopa rosa' no mar. A importância da sincronização temporal exata dessa desova maciça é:", "alternativas": {"A": "Alimentar todos os peixes predadores até que eles morram de indigestão.", "B": "Maximizar as chances de encontro dos gametas da mesma espécie na vastidão do oceano e saturar a capacidade dos peixes predadores, garantindo que milhões de zigotos sobrevivam à predação.", "C": "Aumentar a salinidade da água do mar para evitar o aquecimento global.", "D": "Fazer com que os corais se transformem em peixes nadadores adultos.", "E": "Gelar a superfície do oceano com as células de óvulos."}, "resposta_correta": "B", "justificativa": "A liberação síncrona massiva de gametas (broadcast spawning) coordenada por fases lunares e temperatura da água supera a diluição oceânica e promove a 'saciedade de predadores', assegurando que a taxa de fecundação supere o consumo predatório.", "possui_imagem": false},
  {"id": 96, "uid": "CIEN-8-096", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Filhotes Altriciais vs. Precociais", "dificuldade": "Médio", "enunciado": "Ao comparar o nascimento de diferentes aves e mamíferos, biólogos diferenciam filhotes altriciais (como os filhotes de pombos e ratos, que nascem nus, cegos e totalmente dependentes) de filhotes precociais (como patinhos, pintinhos, potros e bezerros). Os filhotes precociais caracterizam-se por:", "alternativas": {"A": "Passarem dez anos dentro de um ovo de pedra antes de nascerem.", "B": "Nascerem em estágio avançado de desenvolvimento, com olhos abertos, corpo coberto por penugem ou pelos e capacidade de se levantar e caminhar poucas horas após o parto ou eclosão.", "C": "Não precisarem de comida nem de água durante toda a vida.", "D": "Nascerem sabendo voar acima das nuvens imediatamente.", "E": "Serem amamentados exclusivamente pelo pai com leite vegetal."}, "resposta_correta": "B", "justificativa": "Espécies precociais/nidífugas possuem períodos de incubação ou gestação mais longos e investem em recém-nascidos sensorialmente e motoramente maduros, aptos a acompanhar a mãe e fugir de predadores logo após o nascimento.", "possui_imagem": false},
  {"id": 97, "uid": "CIEN-8-097", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Polinização por Vetores Animais: Síndromes Florais", "dificuldade": "Médio", "enunciado": "Flores polinizadas por beija-flores costumam ser tubulares, inodoras e vermelhas ou alaranjadas brilhantes com muito néctar líquido diluído. Flores polinizadas por mariposas noturnas são brancas, abrem à noite e emitem aroma doce penetrante. Essas associações morfológicas e químicas entre plantas e polinizadores são denominadas:", "alternativas": {"A": "Metamorfoses florais de inverno.", "B": "Síndromes de polinização (adaptações coevolutivas entre flores e seus vetores animais específicos).", "C": "Parasitismos vegetais carnívoros.", "D": "Hermafroditismos induzidos por bactérias do solo.", "E": "Esporulações clorofiladas estomáticas."}, "resposta_correta": "B", "justificativa": "Síndromes de polinização refletem convergências coevolutivas onde atributos florais (morfologia da corola, pigmentação, emissão de compostos voláteis e concentração do néctar) são adaptados aos sistemas sensoriais e peças bucais dos polinizadores correspondentes.", "possui_imagem": false},
  {"id": 98, "uid": "CIEN-8-098", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Gêmeos Monozigóticos vs. Dizigóticos: Origem Biológica", "dificuldade": "Médio", "enunciado": "Em mamíferos vivíparos como os seres humanos, podem ocorrer gestações gemelares. A diferença biológica primária entre gêmeos monozigóticos (univitelinos) e gêmeos dizigóticos (bivitelinos ou fraternos) reside em:", "alternativas": {"A": "Os monozigóticos são formados por dois óvulos e um espermatozoide; os dizigóticos por dois espermatozoides e nenhum óvulo.", "B": "Os monozigóticos originam-se da fecundação de um único óvulo por um único espermatozoide cujo zigoto/blastocele se divide em dois embriões (sendo geneticamente idênticos e do mesmo sexo); os dizigóticos originam-se da fecundação independente de dois óvulos distintos por dois espermatozoides diferentes (podendo ter sexos diferentes e genética distinta como irmãos comuns).", "C": "Os monozigóticos têm pais biológicos diferentes e os dizigóticos têm o mesmo pai.", "D": "Os monozigóticos nascem por reprodução assexuada vegetal sem pai.", "E": "Os dizigóticos são clones perfeitos que pensam os mesmos pensamentos."}, "resposta_correta": "B", "justificativa": "Gêmeos monozigóticos derivam da bipartição precoce de um único concepto fertilizado (clones genéticos estritos com genótipo idêntico). Gêmeos dizigóticos derivam de ovulação múltipla concomitante fertilizada por espermatozoides distintos, compartilhando em média 50% de alelos.", "possui_imagem": false},
  {"id": 99, "uid": "CIEN-8-099", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Acasalamento e Custo dos Machos: Canibalismo Sexual", "dificuldade": "Médio", "enunciado": "Em algumas espécies de aranhas (como a viúva-negra) e no louva-a-deus, a fêmea frequentemente devora o macho durante ou logo após a cópula (canibalismo sexual). Sob a perspectiva da biologia evolutiva e do investimento reprodutivo, para o macho esse sacrifício extremo pode ser vantajoso se:", "alternativas": {"A": "Ele odiar seus filhotes e quiser que eles não nasçam.", "B": "Ao servir de refeição altamente nutritiva para a fêmea, ele aumenta significativamente a quantidade e a viabilidade dos ovos fertilizados que carregarão os seus próprios genes, além de prolongar a cópula e garantir a paternidade exclusiva da ninhada.", "C": "O macho for na verdade uma fêmea disfarçada sem espermatozoides.", "D": "Ele conseguir ressuscitar duas semanas depois com asas novas.", "E": "A fêmea for incapaz de digerir proteínas animais."}, "resposta_correta": "B", "justificativa": "Em termos de aptidão inclusiva (fitness), o canibalismo sexual copulatório pelo macho assegura transferência máxima de esperma (prolongando a intromissão), reduz a receptividade da fêmea a machos rivais e doa biomassa calórica direta para o desenvolvimento de seus próprios filhos.", "possui_imagem": false},
  {"id": 100, "uid": "CIEN-8-100", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Vantagens e Desvantagens da Fecundação Externa", "dificuldade": "Médio", "enunciado": "A fecundação externa é uma estratégia bem-sucedida para animais aquáticos como peixes e corais, mas seria totalmente inviável para mamíferos terrestres. A grande desvantagem da fecundação externa é:", "alternativas": {"A": "Os filhotes nascerem sem nenhuma célula viva.", "B": "A enorme perda e desperdício de gametas dispersos pelas correntes marítimas e a alta vulnerabilidade à predação por outros animais aquáticos antes mesmo da fertilização ocorrer, exigindo a produção de milhões de óvulos para que poucos sobrevivam.", "C": "O fato de a água salgada queimar todos os espermatozoides masculinos.", "D": "A impossibilidade de haver machos e fêmeas na mesma lagoa.", "E": "O esgotamento de todo o oxigênio do oceano durante a desova."}, "resposta_correta": "B", "justificativa": "Fatores abióticos (diluição hidrodinâmica, correntes, turbulência) e bióticos (predação pelágica massiva de gametas e larvas) impõem elevadíssimo risco de insucesso na fecundação externa, compensado energeticamente pela emissão de milhões de células germinativas.", "possui_imagem": false},
  {"id": 101, "uid": "CIEN-8-101", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Monogamia vs. Poligamia no Reino Animal", "dificuldade": "Médio", "enunciado": "Sistemas de acasalamento animal são moldados pela distribuição ecológica dos recursos e pelas oportunidades reprodutivas. O sistema no qual um único macho acasala-se com múltiplas fêmeas e defende um território ou harém exclusivo (como nos elefantes-marinhos e leões) é denominado:", "alternativas": {"A": "Poliandria exclusiva.", "B": "Poliginia (uma modalidade de poligamia).", "C": "Monogamia estrita perpétua.", "D": "Assexualidade colonial cooperativa.", "E": "Hermafroditismo recíproco simultâneo."}, "resposta_correta": "B", "justificativa": "Poliginia é a estrutura de acasalamento poligâmica em que machos monopolizam o acesso a múltiplas fêmeas, frequentemente associada a acentuado dimorfismo sexual de tamanho e agressividade agonística entre machos rivais.", "possui_imagem": false},
  {"id": 102, "uid": "CIEN-8-102", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Inseminação Artificial na Pecuária: Vantagens Zootécnicas", "dificuldade": "Médio", "enunciado": "Na pecuária bovina e suína moderna, a reprodução sexuada natural com monta direta foi amplamente substituída pela Inseminação Artificial (IA). O principal benefício zootécnico e genético dessa tecnologia reprodutiva aplicada é:", "alternativas": {"A": "Eliminar o uso de espermatozoides e fazer as vacas terem filhotes assexuados.", "B": "Disseminar rapidamente características genéticas desejáveis de reprodutores de elite (como alta produção de leite, ganho de peso e rusticidade), prevenir a transmissão de doenças venéreas e otimizar o manejo reprodutivo do rebanho.", "C": "Fazer com que a gestação das vacas dure apenas duas semanas.", "D": "Garantir que todos os bezerros nasçam com asas de aves.", "E": "Substituir o leite materno por água mineral nas primeiras horas."}, "resposta_correta": "B", "justificativa": "A inseminação artificial com sêmen congelado e criopreservado permite que um único touro geneticamente superior fertilize milhares de matrizes em diferentes regiões, controlando a endogamia, padronizando a progênie e mitigando zoonoses venéreas.", "possui_imagem": false},
  {"id": 103, "uid": "CIEN-8-103", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Ovo Amniótico e a Emancipação Reprodutiva da Água", "dificuldade": "Médio", "enunciado": "Ao comparar os ovos gelatinosos dos anfíbios com os ovos dos répteis e das aves, nota-se que estes últimos representam um dos maiores saltos evolutivos da história da vida na Terra. A presença do ovo amniótico dotado de casca calcária semipermeável permitiu aos vertebrados:", "alternativas": {"A": "Respirar debaixo da água salgada durante toda a vida adulta.", "B": "Reproduzir-se com sucesso em terra firme e colonizar habitats secos e distantes de corpos d'água, pois a casca retém a água interna enquanto permite as trocas gasosas vitais com o ar.", "C": "Botar ovos que se chocam sozinhos sem necessidade de calor.", "D": "Eliminar todos os predadores da floresta por veneno na casca.", "E": "Fazer com que os filhotes nasçam sem ossos no corpo."}, "resposta_correta": "B", "justificativa": "O ovo amniótico funciona como um sistema de suporte à vida autônomo na terra seca: a casca porosa bloqueia a evaporação hídrica catastrófica mas viabiliza a difusão de O2 e CO2 para as membranas embrionárias corioalantoideas.", "possui_imagem": false},
  {"id": 104, "uid": "CIEN-8-104", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Seleção Sexual e Princípio do Handicap (Desvantagem)", "dificuldade": "Médio", "enunciado": "A cauda extravagante do pavão-macho, os chifres gigantescos e pesados do alce e o canto ruidoso de certas rãs tornam esses animais muito mais visíveis e vulneráveis a predadores. De acordo com a teoria do 'Princípio do Handicap' formulada pelo biólogo Amotz Zahavi, por que as fêmeas preferem acasalar-se justamente com machos que possuem essas características custosas e perigosas?", "alternativas": {"A": "Porque as fêmeas querem que os machos sejam devorados logo após o acasalamento.", "B": "Porque sobreviver na natureza carregando um ornamento pesado ou perigoso atua como um 'sinal honesto' de que aquele macho possui genes superiores de vigor, saúde e resistência imunológica, qualidades valiosas que serão herdadas por seus filhotes.", "C": "Porque as fêmeas não enxergam animais camuflados na floresta.", "D": "Porque machos sem chifres não possuem espermatozoides férteis.", "E": "Porque as fêmeas aprendem esse comportamento assistindo televisão."}, "resposta_correta": "B", "justificativa": "O Princípio do Handicap estipula que sinais sexuais só são confiáveis (honestos) se impuserem um custo biológico genuíno ao seu portador. Um macho capaz de prosperar e escapar de predadores ostentando um ornamento energeticamente custoso prova seu patrimônio genético superior à fêmea selecionadora.", "possui_imagem": false},
  {"id": 105, "uid": "CIEN-8-105", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Propagação por Cultura de Tecidos Vegetais (Micropropagação)", "dificuldade": "Médio", "enunciado": "Em laboratórios de biotecnologia agrícola, cientistas cultivam milhares de mudas idênticas e sadias de cana-de-açúcar, orquídeas e bananeiras a partir de um grupo microscópico de células de meristema apical colocadas em tubos de ensaio com meio de cultura estéril e hormônios vegetais. Essa tecnologia avançada baseia-se na propriedade das células vegetais chamada:", "alternativas": {"A": "Mitose reversa bacteriana.", "B": "Totipotência celular (capacidade de uma célula vegetal diferenciada ou meristemática regenerar uma planta inteira sob estímulo adequado).", "C": "Fecundação in vitro por pólen sintético.", "D": "Partenogênese floral com ovários artificiais.", "E": "Mutação química induzida por adubos nitrogenados."}, "resposta_correta": "B", "justificativa": "A micropropagação vegetal apoia-se na totipotência intrínseca dos tecidos meristemáticos vegetais: sob proporções controladas de auxinas e citocininas em meio nutriente estéril, o explante desdiferencia-se em calo e regenera brotos e raízes clonais livres de vírus e patógenos.", "possui_imagem": false},
  {"id": 106, "uid": "CIEN-8-106", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Custos da Anisogamia e a Razão Sexual de Fisher", "dificuldade": "Difícil", "enunciado": "Em quase todas as espécies de animais com reprodução sexuada, a proporção entre machos e fêmeas ao nascer é rigorosamente próxima de 1:1 (um macho para uma fêmea). O biólogo e estatístico Ronald Fisher explicou esse fenômeno demonstrando que a razão sexual 1:1 é uma Estratégia Evolutivamente Estável (EEE) porque:", "alternativas": {"A": "Os cromossomos sexuais X e Y são atraídos por gravidade magnética.", "B": "Se uma população passar a ter excesso de fêmeas, qualquer casal que produzir machos terá uma vantagem reprodutiva massiva (pois cada macho terá muitas parceiras e deixará mais netos), aumentando a frequência de machos até restaurar o equilíbrio 1:1 por seleção natural dependente de frequência.", "C": "Machos e fêmeas precisam ter a mesma massa corporal para não desequilibrar o planeta.", "D": "As fêmeas matam metade dos ovos masculinos em todas as ninhadas.", "E": "Apenas machos possuem células que realizam divisão meiótica."}, "resposta_correta": "B", "justificativa": "O Princípio de Fisher estabelece que, se o investimento parental em filhos de ambos os sexos for equivalente, a seleção natural dependente de frequência estabiliza a razão sexual primária em 1:1, pois o sexo em minoria usufrui de maior aptidão reprodutiva média per capita.", "possui_imagem": false},
  {"id": 107, "uid": "CIEN-8-107", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Conflito Sexual e Canibalismo em Aranhas", "dificuldade": "Difícil", "enunciado": "Em aranhas tecelãs Nephila, os machos são minúsculos (cerca de 10 vezes menores que a fêmea gigante) e quebram intencionalmente a ponta de seu órgão copulador (êmbolo do pedipalpo) dentro do trato genital da fêmea durante a cópula, deixando o fragmento travado como um 'tampão copulatório'. A função adaptativa desse tampão genital é:", "alternativas": {"A": "Alimentar a fêmea com cálcio durante o desenvolvimento dos ovos.", "B": "Bloquear fisicamente o orifício reprodutor da fêmea (espermateca), impedindo mecanicamente que machos rivais subsequentes consigam copular e fertilizar os ovos com seus próprios espermatozoides (competição espermática).", "C": "Fazer a fêmea parar de tecer teias para o resto da vida.", "D": "Injetar veneno mortal no abdômen da fêmea.", "E": "Permitir que o macho voe como um balão de ar quente."}, "resposta_correta": "B", "justificativa": "Tampões de acoplamento (mating plugs) ou mutilações genitais em artrópodes representam táticas de competição espermática pós-copulatória masculina para prevenir a poliandria imediata e assegurar monopólio da paternidade sobre a espermateca feminina.", "possui_imagem": false},
  {"id": 108, "uid": "CIEN-8-108", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Partenogênese Facultativa em Vertebrados: O Dragão-de-Komodo", "dificuldade": "Difícil", "enunciado": "Fêmeas de dragão-de-komodo (Varanus komodoensis) mantidas em zoológicos em isolamento total de machos durante anos conseguiram colocar ovos férteis viáveis dos quais eclodiram filhotes saudáveis de machos. Esse fenômeno de partenogênese facultativa por duplicação cromossômica (automixia terminal) nos répteis, cujo sistema cromossômico sexual é ZW (fêmeas ZW e machos ZZ), produz exclusivamente filhotes machos (ZZ) porque:", "alternativas": {"A": "O calor do terrário transformou os cromossomos sexuais em hormônio testosterona.", "B": "A fusão do núcleo do óvulo com o segundo corpúsculo polar gera indivíduos homozigotos ZZ (machos viáveis) ou WW (inviáveis, que morrem no ovo antes da eclosão por ausência de genes vitais contidos no cromossomo Z).", "C": "Fêmeas partenogênicas perdem todos os seus cromossomos na primeira semana de isolamento.", "D": "O dragão-de-komodo é um anfíbio que realiza metamorfose de sexo sob estresse.", "E": "As fêmeas produzem espermatozoides funcionais nos ovários na velhice."}, "resposta_correta": "B", "justificativa": "Em répteis com sistema ZW, a automixia por fusão do óvulo haploide com o segundo glóbulo polar ou duplicação endomitótica gera zigotos homozigotos ZZ (machos viáveis) e WW (letalidade embrionária precoce por ausência de loci vitais do cromossomo Z), resultando apenas em prole masculina viável.", "possui_imagem": false},
  {"id": 109, "uid": "CIEN-8-109", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Competição Espermática e Volume Testicular em Primatas", "dificuldade": "Difícil", "enunciado": "Biólogos comparativos observam uma relação marcante entre a anatomia reprodutiva de primatas e seus sistemas sociais de acasalamento: gorilas machos (que vivem em haréns onde um único macho alfa monopoliza fêmeas sem rivais) possuem testículos pequenos, enquanto chimpanzés machos (que vivem em grupos multimacho onde as fêmeas copulam com vários machos no mesmo estro) possuem testículos proporcionalmente gigantescos. Essa diferença anatômica é explicada pela:", "alternativas": {"A": "Falta de água potável na floresta dos chimpanzés.", "B": "Competição espermática pós-copulatória: em espécies promíscuas multimacho, machos que produzem volumes massivos de esperma de alta motilidade têm maior probabilidade de diluir e vencer os espermatozoides de rivais na corrida até o óvulo dentro do trato genital feminino.", "C": "Atividade física dos gorilas que atrofia os órgãos reprodutivos masculinos.", "D": "Alimentação exclusiva de folhas pelos chimpanzés na copa das árvores.", "E": "Presença de penas nos testículos dos macacos machos."}, "resposta_correta": "B", "justificativa": "A competição espermática seleciona investimento testicular diferencial: quando múltiplas cópulas com fêmeas poliândricas ocorrem em janelas de fertilidade concorrentes, a quantidade absoluta e a qualidade motriz dos gametas masculinos atuam como loteria biológica para fertilização do ovócito.", "possui_imagem": false},
  {"id": 110, "uid": "CIEN-8-110", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Cleistogamia e Casmogamia em Plantas", "dificuldade": "Difícil", "enunciado": "Espécies vegetais como a violeta e certas gramíneas produzem dois tipos de flores no mesmo indivíduo: flores casmógamas (abertas, vistosas e polinizadas cruzadamente por insetos) e flores cleistógamas (flores pequenas, fechadas que nunca se abrem e realizam autopolinização obrigatória sob a terra). A vantagem adaptativa de manter a cleistogamia como estratégia mista reside em:", "alternativas": {"A": "Atrair pássaros predadores para o subsolo.", "B": "Garantir a reprodução e produção de sementes com baixíssimo custo energético e sem depender de polinizadores ou clima favorável (seguro reprodutivo), enquanto as flores abertas asseguram variabilidade genética quando há polinizadores disponíveis.", "C": "Eliminar totalmente o uso de clorofila na fotossíntese da planta.", "D": "Fazer as violetas viverem sem luz solar e sem água.", "E": "Fazer a semente germinar dentro do tronco de árvores vizinhas."}, "resposta_correta": "B", "justificativa": "A cleistogamia atua como uma estratégia reprodutiva mista (hedging de risco): se condições ambientais adversas ou escassez de insetos inviabilizarem a polinização cruzada das flores casmógamas, a autopolinização interna fechada nas flores cleistógamas assegura produção garantida de propágulos a custo energético mínimo.", "possui_imagem": false},
  {"id": 111, "uid": "CIEN-8-111", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Ação do Hormônio Prolactina e Comportamento de Choco em Aves", "dificuldade": "Difícil", "enunciado": "Nas aves, a transição da fase de postura de ovos para a fase de incubação contínua (comportamento de choco) é regulada por alterações neuroendócrinas profundas no encéfalo. O hormônio primário responsável por desencadear o comportamento maternal de incubação, desenvolver a 'placa de incubação' vascularizada no peito e inibir novas ovulações é a:", "alternativas": {"A": "Adrenalina.", "B": "Prolactina (secretada pela adenoipófise).", "C": "Insulina pancreática.", "D": "Tiroxina tireoidiana.", "E": "Testosterona testicular."}, "resposta_correta": "B", "justificativa": "Níveis circulantes elevados de prolactina estimulam a perda de penas na região ventral e a hipervascularização do epitélio (placa de choco ou incubação), induzindo a motivação comportamental de permanecer assentada sobre os ovos transferindo calor do sangue diretamente à casca.", "possui_imagem": false},
  {"id": 112, "uid": "CIEN-8-112", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Seleção Sexual Desenfreada de Fisher (Fisherian Runaway)", "dificuldade": "Difícil", "enunciado": "O modelo de 'Seleção Desenfreada de Fisher' (Fisherian Runaway) descreve um processo evolutivo de retroalimentação positiva no qual uma preferência estética da fêmea por certo traço masculino (como caudas longas) e o próprio traço no macho tornam-se geneticamente correlacionados. Esse processo culmina em:", "alternativas": {"A": "A extinção imediata de todas as fêmeas da espécie.", "B": "Um ciclo de coevolução acelerado onde o traço masculino se torna cada vez mais exagerado a cada geração (mesmo tornando-se prejudicial à sobrevivência física), simplesmente porque machos com caudas longas são os mais escolhidos e fêmeas com preferência por caudas longas geram 'filhos atraentes' que herdarão o mesmo sucesso reprodutivo.", "C": "O retorno da espécie à reprodução assexuada por brotamento.", "D": "A transformação dos machos em herbívoros aquáticos sem penas.", "E": "A perda da capacidade dos ovos de chocarem na primavera."}, "resposta_correta": "B", "justificativa": "O runaway fisheriano demonstra que a correlação genética de desequilíbrio de ligação entre os alelos do ornamento masculino e os alelos da preferência da fêmea cria uma pressão seletiva autocatalítica: o traço é selecionado não por conferir viabilidade ecológica, mas pela própria atratividade sexual que confere à progênie masculina ('filhos atraentes').", "possui_imagem": false},
  {"id": 113, "uid": "CIEN-8-113", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Apomixia em Angiospermas: Sementes Assexuadas", "dificuldade": "Difícil", "enunciado": "Em certas plantas de grande interesse agronômico (como o capim-braquiária e espécies de citros), ocorre o fenômeno da apomixia. Na apomixia botânica, a planta produz sementes viáveis dentro de frutos sem que ocorra:", "alternativas": {"A": "A fotossíntese nas folhas verdes.", "B": "A meiose e a fertilização do óvulo por grãos de pólen, gerando sementes que contêm embriões geneticamente idênticos à planta mãe (clones via semente).", "C": "A absorção de água mineral pelas raízes no solo.", "D": "O desenvolvimento de flores ou folhas na primavera.", "E": "A respiração celular nas mitocôndrias da planta."}, "resposta_correta": "B", "justificativa": "A apomixia (agamospermia) é a formação assexuada de sementes sem meiose (aposporia/diplosporia) e sem fecundação (partenogênese do óvulo diploide). A semente formada origina uma progênie clonal perfeita da planta materna, de imenso valor para clonagem comercial de híbridos de alto rendimento.", "possui_imagem": false},
  {"id": 114, "uid": "CIEN-8-114", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Cuidado Parental Aloparental (Helpers at the Nest)", "dificuldade": "Difícil", "enunciado": "Em espécies de aves de vida social complexa (como o carcará, o pica-pau-das-bolotas e certas espécies de corvídeos), indivíduos jovens adultos permanecem no território parental e auxiliam ativamente seus pais a alimentar e defender seus irmãos mais novos da ninhada seguinte, em vez de se reproduzirem eles mesmos. A justificativa biológica para esse comportamento altruísta aloparental fundamenta-se na:", "alternativas": {"A": "Falta de capacidade biológica dos jovens de produzir espermatozoides.", "B": "Teoria da Seleção de Parentesco (Kin Selection) de W. D. Hamilton: ao ajudar a criar irmãos plenos (que compartilham em média 50% de seus próprios genes), o ajudante aumenta sua 'aptidão inclusiva' indireta, especialmente em ambientes onde territórios novos de reprodução são escassos e saturados.", "C": "Ordem imposta por predadores da floresta.", "D": "Fraqueza dos músculos peitorais das aves jovens.", "E": "Ausência de visão em cores nas aves juvenis."}, "resposta_correta": "B", "justificativa": "A Regra de Hamilton (r.B > C) explica o altruísmo cooperativo reprodutivo: quando o custo individual de dispersão é proibitivo (saturação de habitat) e o benefício conferido aos parentes genéticos (irmãos plenos, r = 0,5) for elevado, auxiliar na criação maximiza a transmissão indireta de alelos compartilhados da linhagem.", "possui_imagem": false},
  {"id": 115, "uid": "CIEN-8-115", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Senescência e Teoria do Soma Descartável de Kirkwood", "dificuldade": "Difícil", "enunciado": "A Teoria do 'Soma Descartável' (Disposable Soma Theory), formulada pelo biólogo Thomas Kirkwood, aborda o compromisso energético evolutivo entre reprodução e manutenção corporal (envelhecimento). De acordo com essa teoria, os organismos vivos envelhecem e morrem porque:", "alternativas": {"A": "As células vivas foram programadas para explodir após dez anos de vida.", "B": "A seleção natural prioriza a alocação de energia metabólica na reprodução precoce bem-sucedida e na defesa da linhagem germinativa imortal, investindo apenas a energia estritamente necessária na manutenção e reparo do corpo somático descartável para que ele sobreviva até a idade reprodutiva.", "C": "Os animais respiram oxigênio demais durante a infância.", "D": "A gravidade da Terra gasta a energia das proteínas celulares.", "E": "As mitocôndrias se transformam em bactérias parasitas na velhice."}, "resposta_correta": "B", "justificativa": "Recursos energéticos são finitos: alocar energia em manutenção celular somática perfeita indefinida confere retornos decrescentes diante do risco intrínseco de morte por fatores ecológicos extrínsecos (predação, acidentes, patógenos); o investimento otimizado na linhagem germinativa assegura a transmissão dos genes antes do declínio somático.", "possui_imagem": false},
  {"id": 116, "uid": "CIEN-8-116", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Gynogênese e Dependência Espermática Parasitária", "dificuldade": "Difícil", "enunciado": "Em certas espécies unissexuais de peixes e salamandras formadas apenas por fêmeas partenogênicas (como o peixe Poecilia formosa), a reprodução ocorre por 'ginogênese'. Esse mecanismo reprodutivo singular caracteriza-se por:", "alternativas": {"A": "A fêmea engolir o macho inteiro antes de botar ovos.", "B": "A fêmea necessitar copular com o espermatozoide de um macho de espécie aparente para estimular e ativar a clivagem do óvulo, mas o DNA do espermatozoide é destruído e rejeitado, não participando geneticamente da formação do embrião (que é um clone 100% materno).", "C": "A produção de filhotes que têm metade do corpo de peixe e metade de rã.", "D": "A fecundação direta dos óvulos por bactérias marinhas simbióticas.", "E": "A eliminação de ovos secos que não necessitam de água doce."}, "resposta_correta": "B", "justificativa": "A ginogênese (pseudogamia) é uma forma de reprodução unissexual parasitária: o contato com o espermatozoide heteroespecífico é mecanicamente indispensável para deflagrar a ativação ovocitária e o início das divisões mitóticas, mas o pronúcleo masculino é degradado sem singamia, resultando em prole exclusivamente clonal feminina.", "possui_imagem": false},
  {"id": 117, "uid": "CIEN-8-117", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Assimetria de Investimento Parental de Trivers", "dificuldade": "Difícil", "enunciado": "A teoria do Investimento Parental de Robert Trivers (1972) prevê que, na vasta maioria das espécies animais, as fêmeas são muito mais seletivas na escolha do parceiro (comportamento de escolha criteriosa) e os machos competem agressivamente entre si pelo acesso às fêmeas. A raiz biológica universal dessa assimetria comportamental entre os sexos baseia-se em:", "alternativas": {"A": "As fêmeas serem maiores e mais fortes que os machos em todas as espécies de vertebrados.", "B": "O investimento parental biológico inicial e contínuo da fêmea (produção de óvulos caros e volumosos com vitelo, gestação, produção de ovos e lactação) ser muito maior do que o investimento inicial mínimo do macho (produção de milhões de espermatozoides metabolicamente baratos), tornando as fêmeas um recurso reprodutivo limitante disputado.", "C": "Os machos viverem metade do tempo das fêmeas na natureza.", "D": "As fêmeas possuírem visão noturna que enxerga defeitos genéticos dos machos.", "E": "Os machos não possuírem cromossomos sexuais em suas células somáticas."}, "resposta_correta": "B", "justificativa": "A anisogamia e o investimento pré e pós-natal assimétrico estipulam que o sexo que arca com maior custo parental por descendente (tipicamente as fêmeas em mamíferos) constitui o recurso limitante; o sexo de menor investimento (machos) compete intra-sexualmente pela fertilização desse recurso valioso.", "possui_imagem": false},
  {"id": 118, "uid": "CIEN-8-118", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Inversão de Papéis Sexuais: O Caso do Cavalo-Marinho", "dificuldade": "Difícil", "enunciado": "Nos cavalos-marinhos e peixes-cachimbo (família Syngnathidae), ocorre uma clássica e fascinante 'inversão de papéis sexuais' no reino animal: o macho é quem engravida e carrega os embriões em uma bolsa incubadora no abdômen. Como consequência dessa inversão anatômica de investimento parental, o comportamento desses animais caracteriza-se por:", "alternativas": {"A": "A fêmea morrer imediatamente após botar ovos.", "B": "As fêmeas competirem ativamente entre si pelo acesso aos machos disponíveis, desenvolvendo ornamentos coloridos mais intensos, enquanto os machos exercem a escolha criteriosa das parceiras maiores e mais férteis para preencher sua bolsa incubadora.", "C": "O macho produzir óvulos e a fêmea produzir espermatozoides.", "D": "Os filhotes nascerem como répteis terrestres com pernas.", "E": "A reprodução ser realizada sem cópula ou encontro de gametas."}, "resposta_correta": "B", "justificativa": "A teoria de Trivers prediz com elegância que, quando os machos realizam o maior investimento parental pós-zigótico (gravidez masculina com osmorregulação, oxigenação e nutrição intra-bolsa pelo macho), os papéis comportamentais se invertem: a taxa reprodutiva potencial das fêmeas excede a dos machos, gerando fêmeas que cortejam e machos que selecionam.", "possui_imagem": false},
  {"id": 119, "uid": "CIEN-8-119", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Aneuploidia e Não Disjunção Meiótica na Gametogênese", "dificuldade": "Difícil", "enunciado": "Durante a meiose que produz os gametas na reprodução sexuada, pode ocorrer o erro de 'não disjunção cromossômica', no qual um par de cromossomos homólogos (na Meiose I) ou de cromátides irmãs (na Meiose II) não se separa adequadamente. A consequência citogenética direta da fertilização de um gameta resultante dessa falha é:", "alternativas": {"A": "A formação de um clone assexuado bacteriano.", "B": "A formação de um embrião portador de aneuploidia numérica cromossômica, como a trissomia (ex: Síndrome de Down, trissomia do cromossomo 21) ou monossomia (ex: Síndrome de Turner, monossomia do X).", "C": "A transformação instantânea de todos os órgãos em músculos lisos.", "D": "O nascimento de gêmeos monozigóticos ligados pela cabeça.", "E": "A produção de gametas com três flagelos natatórios."}, "resposta_correta": "B", "justificativa": "A não disjunção meiótica produz gametas n+1 e n-1. A fertilização por um gameta normal (n) resulta em zigotos aneuploides com aberrações numéricas (2n+1 trissomia ou 2n-1 monossomia), desequilibrando a dosagem gênica de centenas de proteínas do desenvolvimento embrionário.", "possui_imagem": false},
  {"id": 120, "uid": "CIEN-8-120", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Estratégia de Desova em Porções vs. Total nos Peixes", "dificuldade": "Difícil", "enunciado": "Na dinâmica reprodutiva de peixes marinhos, fêmeas de desova total liberam todos os seus ovócitos maduros em um único evento anual massivo, enquanto fêmeas de 'desova parcelada' (ou fracionada) liberam lotes sucessivos de ovócitos em intervalos de dias ou semanas ao longo de vários meses. A vantagem adaptativa da desova parcelada em ambientes instáveis é:", "alternativas": {"A": "Fazer o peixe colocar ovos dentro de conchas de tartaruga marinha.", "B": "Reduzir o risco de perda catastrófica total da prole (bet-hedging reprodutivo) diante de flutuações repentinas na temperatura da água, tempestades ou picos sazonais de predadores de larvas, aumentando as chances de que pelo menos alguns lotes encontrem condições ideais de plâncton.", "C": "Permitir que a fêmea engorde sem comer alimentos durante um ano.", "D": "Fazer as larvas nascerem como peixes pulmonados de água doce.", "E": "Impedir que os machos gastem espermatozoides no oceano."}, "resposta_correta": "B", "justificativa": "A desova parcelada distribui a alocação reprodutiva no tempo e espaço (tática de bet-hedging ecológico). Em ecossistemas marinhos onde a abundância de fitoplâncton e correntes oscila imprevisivelmente, fracionar a liberação minimiza a probabilidade de falha total de recrutamento anual da coorte.", "possui_imagem": false},
  {"id": 121, "uid": "CIEN-8-121", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Ovulação Induzida em Mamíferos Carnívoros", "dificuldade": "Difícil", "enunciado": "Diferente de primatas e roedores (que apresentam ovulação espontânea cíclica regular), fêmeas de felinos (como gatas domésticas e onças), camelos e coelhos são 'ovuladoras induzidas'. Nesses animais, a liberação do ovócito pelo ovário só acontece se:", "alternativas": {"A": "A fêmea comer 10 kg de carne crua no café da manhã.", "B": "Ocorrer a estimulação mecânica da cópula pelas espículas queratinizadas presentes no pênis do macho, enviando impulsos nervosos pela medula até o hipotálamo para deflagrar o pico do hormônio LH que induz a ovulação.", "C": "A temperatura do ambiente cair abaixo de zero grau Celsius.", "D": "A fêmea entrar na água doce de uma cachoeira na floresta.", "E": "O macho cantar músicas suaves durante a noite inteira."}, "resposta_correta": "B", "justificativa": "A ovulação induzida reflexa é ativada por mecanorreceptores vaginais estimulados pelos espinhos córneos do pênis peniano felino durante a cópula; os sinais neurais ascendem pelo nervo pudendo até o hipotálamo, liberando uma onda maciça de GnRH e um surto hipofisário de LH que rompe os folículos ovarianos maduros.", "possui_imagem": false},
  {"id": 122, "uid": "CIEN-8-122", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Hermafroditismo Simultâneo e o 'Dilema do Espermatozoide'", "dificuldade": "Difícil", "enunciado": "Em caracóis terrestres e vermes hermafroditas simultâneos, ambos os parceiros possuem óvulos caros e espermatozoides baratos ao mesmo tempo. Durante a cópula, surge um conflito de interesses biológico: cada indivíduo prefere atuar predominantemente como macho (doando espermatozoides baratos para fertilizar os ovos do outro) do que como fêmea (gastando recursos gestando ovos). Para garantir que ambos aceitem atuar nos dois papéis, esses animais utilizam:", "alternativas": {"A": "Ato reflexo incondicionado medular puramente mecânico.", "B": "Comportamentos e adaptações de troca recíproca controlada de gametas (como os 'dardos do amor' de calcário injetados por caracóis que suprimem a destruição de espermatozoides na espermateca do parceiro), assegurando equilíbrio e compromisso reprodutivo mútuo.", "C": "A destruição total de todos os ovócitos antes do acasalamento.", "D": "A divisão do corpo do caracol em duas partes por bipartição.", "E": "A metamorfose em minhocas marinhas após a cópula."}, "resposta_correta": "B", "justificativa": "Em hermafroditas simultâneos, o conflito de papéis sexuais seleciona estratégias de troca estrita de gametas (reciprocidade tit-for-tat) e manipulações químicas: o dardo do amor (love dart) calcário dos caracóis helicídeos injeta muco que contrai o trato genital do receptor, impedindo que a espermateca destrua os espermatozoides recebidos.", "possui_imagem": false},
  {"id": 123, "uid": "CIEN-8-123", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Estratégia de Reprodução Semélpara vs. Iterópara", "dificuldade": "Difícil", "enunciado": "Espécies 'semélparas' (como o salmão do Pacífico, polvos e a planta agave) investem todos os seus recursos fisiológicos acumulados ao longo da vida em um único e colossal evento reprodutivo antes de morrerem. Em contrapartida, espécies 'iteróparas' (como seres humanos, aves e a maioria dos mamíferos):", "alternativas": {"A": "Nunca produzem gametas funcionais durante a vida.", "B": "Apresentam múltiplos episódios reprodutivos repetidos ao longo de sua vida útil adulta, alocando frações moderadas de energia a cada temporada para conservar a integridade somática e sobreviver até a próxima estação de acasalamento.", "C": "Morrem obrigatoriamente logo após o primeiro beijo.", "D": "Produzem apenas clones assexuados por fragmentação.", "E": "São imortais e não envelhecem na natureza."}, "resposta_correta": "B", "justificativa": "A semelparidade (reprodução 'big-bang') é selecionada quando o custo de sobrevivência adulta pós-reprodutiva for proibitivo ou a probabilidade de sucesso reprodutivo subsequente for quase nula. A iteroparidade é adaptativa quando a sobrevida adulta anual for estável, permitindo múltiplos ciclos reprodutivos fracionados.", "possui_imagem": false},
  {"id": 124, "uid": "CIEN-8-124", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Poliembrionia nos Tatus (Dasypus)", "dificuldade": "Difícil", "enunciado": "Nas fêmeas de tatu-galinha (Dasypus novemcinctus), ocorre um fenômeno reprodutivo fascinante conhecido como 'poliembrionia obrigatória': a cada gestação, a fêmea dá à luz invariavelmente uma ninhada de quatro filhotes. A particularidade genética dos quatro filhotes de tatu dessa ninhada é:", "alternativas": {"A": "Todos têm pais biológicos diferentes e cores diferentes.", "B": "Todos são geneticamente idênticos entre si (gêmeos monozigóticos quádruplos de mesmo sexo), originados a partir da fertilização de um único óvulo por um único espermatozoide cujo blastocisto se divide espontaneamente em quatro embriões independentes.", "C": "Três filhotes são machos e um é fêmea obrigatoriamente.", "D": "Os filhotes nascem sem ossos e sem carapaça dérmica.", "E": "Eles nascem por reprodução assexuada de bactérias intestinais."}, "resposta_correta": "B", "justificativa": "A poliembrionia regular do gênero Dasypus é uma adaptação única em mamíferos placentários: a blástula sofre quatro invaginações primordiais distintas antes da nidação, resultando sistematicamente em quatro embriões monocoriônicos clones perfeitos com genótipo idêntico.", "possui_imagem": false},
  {"id": 125, "uid": "CIEN-8-125", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Efeito Trivers-Willard na Alocação Sexual da Prole", "dificuldade": "Difícil", "enunciado": "A influente hipótese de Trivers-Willard (1973) sobre alocação de sexo na prole de mamíferos poligínicos propõe que fêmeas maternas que se encontram em excelentes condições nutricionais e físicas devem enviesar sua reprodução gerando proporcionalmente mais filhotes machos do que fêmeas. A lógica evolutiva dessa teoria sustenta que:", "alternativas": {"A": "Filhotes fêmeas gastam dez vezes mais leite do que filhotes machos.", "B": "Um filho macho forte e robusto criado por uma mãe sadia tem grande probabilidade de tornar-se o macho alfa do bando e copular com dezenas de fêmeas, gerando um número gigantesco de netos para a mãe, enquanto filhas fêmeas têm teto reprodutivo fixo limitado pelo tempo de gestação.", "C": "Os machos protegem a mãe contra a velhice celular.", "D": "Filhotes machos são imunes a todas as bactérias da floresta.", "E": "As fêmeas não conseguem produzir óvulos quando estão bem nutridas."}, "resposta_correta": "B", "justificativa": "O modelo Trivers-Willard fundamenta-se na maior variância reprodutiva dos machos em espécies poligínicas: um macho de alta qualidade física gera retorno reprodutivo exponencial em netos; por outro lado, se a mãe estiver debilitada e desnutrida, ela favorece filhas fêmeas, que reproduzem com segurança mesmo em condições subótimas.", "possui_imagem": false},
  {"id": 126, "uid": "CIEN-8-126", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 17: Tipos de Reprodução e Estratégias Reprodutivas", "tema": "Coevolução Sexual e Corrida Armamentista Antagônica Genital", "dificuldade": "Difícil", "enunciado": "Em aves aquáticas (como patos selvagens), os machos frequentemente tentam copulações forçadas. Ao longo da evolução, as fêmeas desenvolveram vaginas complexas e espiraladas no sentido horário com becos sem saída, enquanto os machos desenvolveram pênis explosivos espiralados no sentido anti-horário. Esse tipo de coevolução morfológica é um clássico exemplo de:", "alternativas": {"A": "Mutualismo pacífico de cooperação biológica.", "B": "Conflito sexual antagônico e corrida armamentista genital, onde as adaptações anatômicas das fêmeas visam exercer a 'escolha críptica' sobre quais espermatozoides fertilizarão seus ovos, contrabalançando a coerção masculina.", "C": "Mimetismo batesiano contra predadores aquáticos.", "D": "Metamorfose incompleta de penas de voo.", "E": "Hermafroditismo sequencial estrito."}, "resposta_correta": "B", "justificativa": "O conflito sexual antagônico (sexually antagonistic coevolution) impulsiona corridas armamentistas morfológicas: barreiras vaginais labirínticas com fundo cego evoluíram para permitir que a fêmea desvie o pênis forçado para sítios não reprodutivos, retendo o controle críptico sobre a fertilização apenas com parceiros cortejados consentidos.", "possui_imagem": false},
  {"id": 127, "uid": "CIEN-8-127", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Puberdade e Hormônios Sexuais", "dificuldade": "Fácil", "enunciado": "A puberdade é o período de transição entre a infância e a idade adulta caracterizado por intensas transformações físicas e biológicas coordenadas por hormônios. O principal hormônio responsável pelo desenvolvimento dos caracteres sexuais secundários masculinos (como engrossamento da voz e crescimento de barba) é a:", "alternativas": {"A": "Progesterona.", "B": "Testosterona.", "C": "Insulina.", "D": "Prolactina.", "E": "Tiroxina."}, "resposta_correta": "B", "justificativa": "A testosterona, produzida primariamente pelas células intersticiais de Leydig nos testículos sob estímulo do LH hipofisário, é o principal andrógeno responsável pelos caracteres sexuais secundários masculinos.", "possui_imagem": true},
  {"id": 128, "uid": "CIEN-8-128", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Caracteres Sexuais Secundários Femininos", "dificuldade": "Fácil", "enunciado": "Nas meninas, a entrada na puberdade estimula os ovários a produzirem estrogênio em maiores quantidades, desencadeando o surgimento de caracteres sexuais secundários femininos, tais como:", "alternativas": {"A": "Engrossamento acentuado da voz com surgimento de pomo-de-adão proeminente.", "B": "Desenvolvimento das mamas (broto mamário), alargamento dos quadris e acúmulo de gordura corporal na região pélvica.", "C": "Produção instantânea de espermatozoides funcionais nos ovários.", "D": "Atrofia dos ossos das pernas com perda permanente da altura.", "E": "Substituição das unhas por garras queratinizadas."}, "resposta_correta": "B", "justificativa": "O estrogênio atua nos receptores dos tecidos-alvo promovendo proliferação do tecido glandular mamário, remodelação ginoide da bacia pélvica e deposição característica de tecido adiposo subcutâneo.", "possui_imagem": true},
  {"id": 129, "uid": "CIEN-8-129", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Sistema Reprodutor Masculino: Testículos e Escroto", "dificuldade": "Fácil", "enunciado": "No sistema reprodutor masculino, os testículos ficam alojados no interior de uma bolsa externa de pele fora da cavidade abdominal, chamada escroto (ou saco escrotal). A localização externa dos testículos é fundamental para a espermatogênese porque:", "alternativas": {"A": "Permite que os testículos fiquem expostos à luz do sol para realizar fotossíntese.", "B": "Mantém os testículos em uma temperatura cerca de 2 ºC a 3 ºC mais baixa do que a temperatura interna do abdômen, condição térmica necessária para a produção adequada de espermatozoides viáveis.", "C": "Impede que o sangue circule nos órgãos sexuais masculinos.", "D": "Protege o pênis contra o calor do verão nas praias.", "E": "Facilita a digestão dos alimentos gordurosos."}, "resposta_correta": "B", "justificativa": "A espermatogênese humana requer temperaturas entre 34 ºC e 35 ºC. O saco escrotal atua como termorregulador fisiológico (com ação dos músculos cremáster e dartos) mantendo as gônadas ligeiramente abaixo da temperatura central de 37 ºC.", "possui_imagem": true},
  {"id": 130, "uid": "CIEN-8-130", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Sistema Reprodutor Masculino: Epidídimo", "dificuldade": "Fácil", "enunciado": "Após serem produzidos nos túbulos seminíferos dos testículos, os espermatozoides recém-formados são encaminhados para uma estrutura alongada enovelada situada sobre cada testículo, onde completam sua maturação e adquirem motilidade flagelar para nadar. Essa estrutura é o:", "alternativas": {"A": "Ureter.", "B": "Epidídimo.", "C": "Próstata.", "D": "Corpo cavernoso.", "E": "Ducto ejaculatório."}, "resposta_correta": "B", "justificativa": "O epidídimo é o órgão tubular enovelado onde os espermatozoides permanecem armazenados temporariamente, sofrendo maturação bioquímica da membrana e capacitação do batimento flagelar.", "possui_imagem": true},
  {"id": 131, "uid": "CIEN-8-131", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Sistema Reprodutor Feminino: Tubas Uterinas e Fecundação", "dificuldade": "Fácil", "enunciado": "No sistema reprodutor feminino, os dois ductos musculares com cílios microscópicos que conectam os ovários ao útero são as tubas uterinas (antigas trompas de Falópio). A tuba uterina desempenha o papel vital de ser o local onde:", "alternativas": {"A": "Ocorre a digestão das proteínas do sangue da menstruação.", "B": "Ocorre normalmente o encontro entre o espermatozoide e o ovócito (a fecundação).", "C": "Os espermatozoides são fabricados pelo corpo feminino.", "D": "O bebê permanece durante os nove meses inteiros da gestação.", "E": "A urina é filtrada antes de ir para a bexiga."}, "resposta_correta": "B", "justificativa": "A fecundação humana ocorre fisiologicamente na porção ampular (terço distal) das tubas uterinas; em seguida, o epitélio ciliado e as contrações musculares tubárias conduzem o zigoto clivado rumo à cavidade uterina.", "possui_imagem": true},
  {"id": 132, "uid": "CIEN-8-132", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Sistema Reprodutor Feminino: O Útero", "dificuldade": "Fácil", "enunciado": "O útero é um órgão oco em forma de pera invertida dotado de paredes musculares espessas. A camada interna vascularizada que reveste a cavidade uterina, onde o embrião se implanta para iniciar a gestação e que descama na menstruação caso não haja gravidez, é o:", "alternativas": {"A": "Miométrio.", "B": "Endométrio.", "C": "Clitóris.", "D": "Colo escleral.", "E": "Epidídimo feminino."}, "resposta_correta": "B", "justificativa": "O endométrio é a mucosa interna uterina altamente vascularizada que sofre hipertrofia glandular cíclica sob influxo hormonal para recepcionar o blastocisto na nidação; na ausência de concepto, descama no fluxo menstrual.", "possui_imagem": true},
  {"id": 133, "uid": "CIEN-8-133", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Ciclo Menstrual: A Menstruação", "dificuldade": "Fácil", "enunciado": "A menstruação, que marca o primeiro dia de um novo ciclo menstrual da mulher, consiste na:", "alternativas": {"A": "Produção de novos óvulos pelo útero.", "B": "Descamação e eliminação da camada superficial do endométrio com sangue pela vagina, decorrente da queda nos níveis dos hormônios estrogênio e progesterona.", "C": "Quebra do fêmur provocada pelo calor corporal.", "D": "Expulsão da placenta madura sem ter havido gravidez.", "E": "Transformação de urina em líquido amniótico."}, "resposta_correta": "B", "justificativa": "Quando não ocorre fecundação, o corpo lúteo atrofia-se, causando queda abrupta nos níveis plasmáticos de progesterona e estrogênio. Sem o suporte hormonal, as arteríolas espiraladas do endométrio colapsam, provocando a descamação hemorrágica menstrual.", "possui_imagem": true},
  {"id": 134, "uid": "CIEN-8-134", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "A Ovulação no Ciclo Menstrual", "dificuldade": "Fácil", "enunciado": "Em um ciclo menstrual típico de 28 dias, o momento em que o folículo ovariano maduro se rompe e libera o ovócito (óvulo) em direção à tuba uterina é a ovulação. Em média, a ovulação ocorre aproximadamente no:", "alternativas": {"A": "1º dia do ciclo (início da menstruação).", "B": "14º dia do ciclo (aproximadamente na metade do ciclo).", "C": "28º dia do ciclo (final do ciclo).", "D": "40º dia do ciclo.", "E": "Último dia da semana de inverno."}, "resposta_correta": "B", "justificativa": "Em um ciclo eumenorreico regular padrão de 28 dias, o pico secretor pré-ovulatório de hormônio luteinizante (LH) deflagra o rompimento folicular e a ovulação por volta do 14º dia (contado a partir do primeiro dia da menstruação).", "possui_imagem": true},
  {"id": 135, "uid": "CIEN-8-135", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Métodos Contraceptivos: Preservativo (Camisinha)", "dificuldade": "Fácil", "enunciado": "Entre todos os métodos anticoncepcionais existentes (pílulas, DIU, injeções, laqueadura), a camisinha masculina e a feminina são os únicos métodos que possuem a dupla função de:", "alternativas": {"A": "Evitar a gravidez e, simultaneamente, proteger contra a transmissão de Infecções Sexualmente Transmissíveis (ISTs).", "B": "Acelerar a puberdade e curar a cólica menstrual.", "C": "Substituir os hormônios da tireoide em adolescentes.", "D": "Tornar os espermatozoides imunes a antibióticos.", "E": "Garantir 100% de nascimento de gêmeos monozigóticos."}, "resposta_correta": "A", "justificativa": "Preservativos de látex ou poliuretano atuam como barreira física impermeável direta, sendo os únicos métodos que bloqueiam a troca de fluidos genitais e o contato com patógenos de ISTs (HIV, HPV, sífilis, clamídia) durante a relação sexual.", "possui_imagem": true},
  {"id": 136, "uid": "CIEN-8-136", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "A Pílula Anticoncepcional Combinada", "dificuldade": "Fácil", "enunciado": "A pílula anticoncepcional oral de uso diário contém hormônios sintéticos semelhantes ao estrogênio e à progesterona. O mecanismo de ação principal pelo qual a pílula impede a gravidez é:", "alternativas": {"A": "Destruir os espermatozoides com ácido sulfúrico na vagina.", "B": "Inibir a secreção dos hormônios hipofisários FSH e LH por feedback negativo, impedindo o amadurecimento dos folículos e a ocorrência da ovulação.", "C": "Bloquear a entrada de ar nos pulmões da mulher.", "D": "Fazer a mulher menstruar todos os dias do mês.", "E": "Impedir que os ovários produzam sangue arterial."}, "resposta_correta": "B", "justificativa": "A manutenção de níveis circulantes contínuos de progestagênio e estrogênio exerce retroalimentação negativa sobre o eixo hipotálamo-hipófise, suprimindo o FSH e o pico de LH indispensável para o rompimento do folículo e a ovulação.", "possui_imagem": true},
  {"id": 137, "uid": "CIEN-8-137", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Métodos Contraceptivos Cirúrgicos Definitivos", "dificuldade": "Fácil", "enunciado": "A laqueadura tubária na mulher e a vasectomia no homem são métodos contraceptivos cirúrgicos considerados definitivos. Na vasectomia masculina, o procedimento cirúrgico consiste em:", "alternativas": {"A": "Remover completamente os dois testículos e o pênis do homem.", "B": "Seccionar e amarrar os ductos deferentes, impedindo que os espermatozoides produzidos nos testículos se juntem ao líquido seminal na ejaculação.", "C": "Cortar os nervos que controlam a ereção peniana.", "D": "Substituir os espermatozoides por bactérias inofensivas.", "E": "Remover a bexiga urinária do abdômen."}, "resposta_correta": "B", "justificativa": "A vasectomia é um procedimento cirúrgico ambulatorial simples que secciona e cauteriza os ductos deferentes; o homem continua com produção normal de testosterona, ereção e ejaculação de líquido seminal (próstata/vesículas), mas o sêmen é estéril (livre de espermatozoides).", "possui_imagem": true},
  {"id": 138, "uid": "CIEN-8-138", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Infecções Sexualmente Transmissíveis (ISTs): Conceito", "dificuldade": "Fácil", "enunciado": "As Infecções Sexualmente Transmissíveis (ISTs) são causadas por vírus, bactérias e outros microrganismos. A principal via de contágio e disseminação dessas infecções é:", "alternativas": {"A": "Pelo contato com maçanetas de portas e assentos de ônibus.", "B": "Pelo contato sexual desprotegido (oral, vaginal ou anal) sem o uso de preservativo com uma pessoa infectada.", "C": "Pela picada de pernilongos comuns no verão.", "D": "Pelo compartilhamento de copos de água limpa na escola.", "E": "Pelo ar respirado em salas de aula ventiladas."}, "resposta_correta": "B", "justificativa": "ISTs transmitem-se predominantemente pelo contato desprotegido com mucosas e secreções genitais infectadas durante atos sexuais sem preservativo, além de transmissão vertical (mãe-filho) e compartilhamento de seringas.", "possui_imagem": true},
  {"id": 139, "uid": "CIEN-8-139", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "HIV e AIDS: Diferença Conceitual", "dificuldade": "Fácil", "enunciado": "É fundamental do ponto de vista médico e social diferenciar o vírus HIV da doença AIDS. A relação correta entre eles é:", "alternativas": {"A": "HIV é uma bactéria da pele e AIDS é o remédio que a cura.", "B": "O HIV é o vírus causador da infecção; a AIDS é a síndrome de imunodeficiência adquirida que se desenvolve quando o vírus destrói as células de defesa do corpo e o paciente fica vulnerável a infecções oportunistas.", "C": "Todas as pessoas que pegam o vírus HIV desenvolvem AIDS em menos de 24 horas.", "D": "O HIV transmite-se apenas por picada de abelhas carnívoras.", "E": "HIV e AIDS são doenças exclusivas de idosos com mais de 90 anos."}, "resposta_correta": "B", "justificativa": "O HIV (Vírus da Imunodeficiência Humana) é o agente etiológico. Uma pessoa vivendo com HIV (soropositiva) em tratamento antirretroviral adequado mantém carga viral indetectável e não desenvolve a fase clínica avançada da AIDS (Síndrome da Imunodeficiência Adquirida).", "possui_imagem": true},
  {"id": 140, "uid": "CIEN-8-140", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Célula-Alvo do Vírus HIV", "dificuldade": "Fácil", "enunciado": "O vírus HIV ataca e destrói seletivamente um tipo específico de célula de defesa do sistema imunológico humano, comprometendo gravemente a capacidade do organismo de combater infecções. Essa célula-alvo é o:", "alternativas": {"A": "Glóbulo vermelho (hemácia).", "B": "Linfócito T auxiliar (T-CD4).", "C": "Plaqueta sanguínea.", "D": "Neurônio sensitivo do tato.", "E": "Célula ciliada da orelha interna."}, "resposta_correta": "B", "justificativa": "O envelope do HIV possui a glicoproteína gp120, com tropismo específico para o receptor CD4 de superfície dos linfócitos T auxiliares (T-CD4), orquestradores centrais da resposta imunológica adaptativa humana.", "possui_imagem": true},
  {"id": 141, "uid": "CIEN-8-141", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "O HPV e a Prevenção do Câncer", "dificuldade": "Fácil", "enunciado": "O Papilomavírus Humano (HPV) é uma IST muito frequente que pode provocar verrugas genitais e está associada ao surgimento de câncer de colo de útero em mulheres. Uma das medidas de prevenção mais eficazes e gratuitas disponíveis no SUS para adolescentes de 9 a 14 anos contra o HPV é a:", "alternativas": {"A": "Cirurgia de retirada do apêndice.", "B": "Vacinação contra o HPV.", "C": "Ingestão diária de vitamina C em comprimidos.", "D": "Uso de óculos escuros com filtro ultravioleta.", "E": "Limpeza da pele com água oxigenada pura."}, "resposta_correta": "B", "justificativa": "A vacina quadrivalente recombinante contra o HPV ofertada no Programa Nacional de Imunizações (PNI) induz produção de anticorpos protetores contra os subtipos 6, 11 (verrugas) e os subtipos de alto risco oncogênico 16 e 18 (responsáveis por ~70% dos casos de câncer cervical).", "possui_imagem": false},
  {"id": 142, "uid": "CIEN-8-142", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Sífilis: Cancro Duro", "dificuldade": "Fácil", "enunciado": "A sífilis é uma IST causada pela bactéria Treponema pallidum. Em sua fase inicial (sífilis primária), o primeiro sintoma clássico que costuma aparecer na região genital ou na boca é:", "alternativas": {"A": "Uma ferida única, geralmente indolor e com bordas duras (cancro duro), que surge no local da infecção e desaparece espontaneamente após algumas semanas mesmo sem tratamento.", "B": "Tosse com febre alta e falta de ar instantânea.", "C": "Crescimento de dentes pontiagudos na gengiva.", "D": "Perda imediata de todos os cabelos da cabeça.", "E": "Sangramento nos olhos sob a luz do sol."}, "resposta_correta": "A", "justificativa": "O cancro duro é a lesão primária patognomônica da sífilis: úlcera rica em treponemas, indolor e de base endurecida que cicatriza sozinha, dando a falsa impressão de cura enquanto a bactéria dissemina-se sistemicamente pela corrente sanguínea.", "possui_imagem": false},
  {"id": 143, "uid": "CIEN-8-143", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Tratamento Eficaz da Sífilis", "dificuldade": "Fácil", "enunciado": "Por ser causada por uma bactéria, a sífilis tem cura quando diagnosticada precocemente. O medicamento de escolha amplamente utilizado na rede pública de saúde para o tratamento definitivo da sífilis é o antibiótico:", "alternativas": {"A": "Penicilina benzatina (benzetacil).", "B": "Insulina regular injetável.", "C": "Xarope calmante para tosse seca.", "D": "Pomada de iodo pura para cortes superficiais.", "E": "Vitamina D em gotas oleosas."}, "resposta_correta": "A", "justificativa": "A penicilina benzatina injetável é o fármaco de primeira linha para erradicação do Treponema pallidum em todas as fases clínicas da sífilis, prevenindo a progressão para quadros terciários e a transmissão vertical congênita.", "possui_imagem": false},
  {"id": 144, "uid": "CIEN-8-144", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Nidação: A Implantação do Embrião", "dificuldade": "Fácil", "enunciado": "Após a fecundação na tuba uterina, o zigoto inicia divisões celulares sucessivas enquanto viaja em direção ao útero. Cerca de 6 a 7 dias após a fertilização, o embrião (em estágio de blastocisto) fixa-se na parede vascularizada do endométrio. Esse evento biológico de fixação no útero é chamado de:", "alternativas": {"A": "Ovulação espontânea.", "B": "Nidação (ou implantação embrionária).", "C": "Menarca puberal.", "D": "Espermatogênese primária.", "E": "Ejaculação retrógrada."}, "resposta_correta": "B", "justificativa": "Nidação é a fixação e invasão fisiológica do blastocisto na mucosa endometrial uterina, marcando o início formal da gestação e da formação dos tecidos placentários embrionários.", "possui_imagem": false},
  {"id": 145, "uid": "CIEN-8-145", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Placenta e Cordão Umbilical", "dificuldade": "Fácil", "enunciado": "Durante a gravidez, o embrião e o feto humano desenvolvem-se protegidos no interior do útero materno. O órgão esponjoso temporário responsável por realizar a nutrição, respiração e excreção do feto através de trocas com o sangue da mãe é a:", "alternativas": {"A": "Bolsa do escroto.", "B": "Placenta, conectada ao feto pelo cordão umbilical.", "C": "Próstata materna dilatada.", "D": "Vesícula seminal embrionária.", "E": "Tuba uterina direita."}, "resposta_correta": "B", "justificativa": "A placenta hemocorial realiza as trocas vitais materno-fetais por difusão de oxigênio e nutrientes da mãe para o feto e eliminação de CO2 e ureia do feto para a circulação materna através dos vasos do cordão umbilical.", "possui_imagem": false},
  {"id": 146, "uid": "CIEN-8-146", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Dimensões da Sexualidade Humana", "dificuldade": "Fácil", "enunciado": "A Organização Mundial da Saúde (OMS) define a sexualidade humana como um aspecto central do ser humano ao longo de toda a vida. A sexualidade engloba:", "alternativas": {"A": "Exclusivamente a função biológica de reprodução para gerar filhos.", "B": "Uma integração multidimensional de fatores biológicos, psicológicos, afetivos, sociais, culturais, éticos, valores de respeito e busca pelo bem-estar e prazer consentido.", "C": "Apenas regras proibitivas impostas pela medicina hospitalar.", "D": "Uma doença física que precisa ser tratada com cirurgias na infância.", "E": "Comportamentos puramente mecânicos desprovidos de sentimentos humanos."}, "resposta_correta": "B", "justificativa": "A sexualidade transcende o ato puramente reprodutivo biológico: envolve identidade, afetividade, comunicação interpessoal, consentimento, dignidade, saúde emocional e direitos reprodutivos.", "possui_imagem": false},
  {"id": 147, "uid": "CIEN-8-147", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Consentimento e Autonomia Corporal", "dificuldade": "Fácil", "enunciado": "Em qualquer relacionamento afetivo ou ato interpessoal, o princípio ético e jurídico do 'consentimento' significa que:", "alternativas": {"A": "Uma pessoa pode decidir pelo corpo da outra sem consultá-la.", "B": "Qualquer toque ou prática íntima só pode ocorrer com a concordância livre, consciente, lúcida e espontânea de ambas as partes, sendo o 'não' um limite absoluto que deve ser rigorosamente respeitado.", "C": "O consentimento só é válido se assinado em cartório com duas testemunhas.", "D": "Homens têm o direito de forçar mulheres a aceitarem suas vontades.", "E": "Amigos podem invadir a privacidade corporal de colegas sem autorização."}, "resposta_correta": "B", "justificativa": "O consentimento é um pilar ético inegociável da autonomia corporal e dignidade humana: toda pessoa possui soberania absoluta sobre seu próprio corpo e qualquer ato não consentido configura violência sexual e violação de direitos fundamentais.", "possui_imagem": false},
  {"id": 148, "uid": "CIEN-8-148", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Feedback Hormonal no Ciclo Menstrual: Fases e Picos", "dificuldade": "Médio", "enunciado": "Durante a primeira metade do ciclo menstrual (fase folicular), o folículo ovariano em crescimento sob estímulo do FSH secreta quantidades crescentes de estrogênio. Ao atingir um limiar elevado antes da ovulação, esse estrogênio dispara um efeito de feedback positivo que provoca:", "alternativas": {"A": "A queda imediata de todos os hormônios da mulher e o início da menopausa.", "B": "Um pico súbito e massivo na secreção do Hormônio Luteinizante (LH) pela hipófise, que desencadeia a ruptura do folículo maduro e a ovulação em cerca de 24 a 36 horas.", "C": "A destruição total do endométrio com sangramento hemorrágico imediato.", "D": "A paralisação temporária dos batimentos cardíacos da mulher.", "E": "A transformação do útero em um órgão de osso duro."}, "resposta_correta": "B", "justificativa": "Ao final da fase folicular, concentrações elevadas e sustentadas de estradiol exercem retroalimentação positiva no eixo hipotálamo-hipofisário, deflagrando o pico pré-ovulatório de LH que ativa enzimas proteolíticas da teca e rompe o folículo de Graaf.", "possui_imagem": false},
  {"id": 149, "uid": "CIEN-8-149", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Função do Corpo Lúteo e da Progesterona", "dificuldade": "Médio", "enunciado": "Após a ovulação, as células remanescentes do folículo rompido no ovário transformam-se em uma estrutura glandular temporária amarelada chamada corpo lúteo (ou corpo amarelo). A principal função endócrina do corpo lúteo na segunda metade do ciclo é:", "alternativas": {"A": "Produzir insulina para diminuir o açúcar no sangue da mulher.", "B": "Secretar altas taxas de progesterona (e estrogênio), mantendo o endométrio espesso, ricamente vascularizado e com glândulas secretoras ativas, preparando o útero para a eventual nidação do embrião.", "C": "Destruir todos os espermatozoides que entrarem no colo do útero.", "D": "Produzir leite nas mamas antes mesmo da fecundação acontecer.", "E": "Fazer a mulher ovular uma segunda vez no dia seguinte."}, "resposta_correta": "B", "justificativa": "O corpo lúteo atua como glândula endócrina na fase secretora pós-ovulatória: secreta progesterona em grande escala, convertendo o endométrio proliferado em endométrio secretor rico em glicogênio e inibindo novas ovulações via feedback negativo no LH/FSH.", "possui_imagem": false},
  {"id": 150, "uid": "CIEN-8-150", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "O Hormônio hCG e o Teste de Gravidez", "dificuldade": "Médio", "enunciado": "Testes de gravidez de farmácia (urina) e laboratoriais (sangue) detectam a presença do hormônio Gonadotrofina Coriônica Humana (hCG). Esse hormônio passa a ser produzido pelo trofoblasto do embrião logo após a nidação. O papel biológico crucial do hCG nas primeiras semanas de gravidez é:", "alternativas": {"A": "Fazer o coração do feto começar a bater na primeira hora.", "B": "Manter o corpo lúteo do ovário ativo e funcionando, impedindo que ele regrida e garantindo a continuidade da secreção de progesterona para não haver menstruação nem perda embrionária.", "C": "Impedir que a mãe sinta enjoo matinal durante a gravidez.", "D": "Substituir os pulmões da mãe no fornecimento de oxigênio ao embrião.", "E": "Fazer o feto nascer com dentes de leite já formados."}, "resposta_correta": "B", "justificativa": "O hCG compartilha homologia estrutural com o LH e liga-se aos receptores de LH do corpo lúteo, resgatando-o da atrofia apoptótica (luteólise). O corpo lúteo gravídico mantém a síntese de progesterona até que a placenta assuma a esteroidogênese no final do primeiro trimestre.", "possui_imagem": false},
  {"id": 151, "uid": "CIEN-8-151", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Glândulas Anexas Masculinas: Vesículas Seminais e Próstata", "dificuldade": "Médio", "enunciado": "O líquido seminal (esperma) não é composto apenas por espermatozoides: mais de 90% do volume ejaculado é produzido pelas glândulas anexas do sistema genital masculino. As vesículas seminais e a próstata contribuem para o sêmen secretando, respectivamente:", "alternativas": {"A": "Urina ácida e água com sal mineral.", "B": "Líquido rico em frutose (açúcar nutritivo que fornece energia mecânica aos espermatozoides) e líquido alcalino leitoso (que neutraliza a acidez natural da vagina, garantindo a sobrevida dos espermatozoides).", "C": "Hormônios da tireoide e enzimas digestivas gástricas puras.", "D": "Bile do fígado e sangue arterial oxigenado.", "E": "Lágrimas com queratina para lubrificação peniana."}, "resposta_correta": "B", "justificativa": "As vesículas seminais secretam ~60% do sêmen (rico em frutose, prostaglandinas e fibrinogênio); a próstata secreta ~30% de fluido alcalino leitoso com citrato e enzimas que tamponam o pH ácido vaginal (~4,0 a 4,5), garantindo a viabilidade dos espermatozoides.", "possui_imagem": false},
  {"id": 152, "uid": "CIEN-8-152", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Gravidez Ectópica", "dificuldade": "Médio", "enunciado": "Em condições fisiológicas anormais, o embrião fertilizado pode se fixar e iniciar a nidação fora da cavidade do útero, mais frequentemente na parede estreita de uma das tubas uterinas (gravidez ectópica tubária). Essa condição clínica é considerada uma emergência médica grave porque:", "alternativas": {"A": "A tuba uterina se transforma em um estômago que digere o embrião.", "B": "A tuba uterina não possui capacidade elástica de expansão como o útero; o crescimento do embrião pode romper a parede da tuba, causando hemorragia interna abdominal maciça com risco de morte para a mulher se não operada com urgência.", "C": "O embrião vira um gêmeo monozigótico quádruplo em 48 horas.", "D": "A mulher perde a visão devido à pressão da tuba.", "E": "Os espermatozoides continuam fecundando a tuba todos os dias."}, "resposta_correta": "B", "justificativa": "Gestações tubárias ocorrem frequentemente por estenoses ou danos nos cílios da tuba (sequelas de salpingites por clamídia/gonorreia). Como a parede muscular tubária é fina, o trofoblasto invade vasos maternos profundos, culminando em ruptura tubária e hemoperitônio agudo com choque hipovolêmico.", "possui_imagem": false},
  {"id": 153, "uid": "CIEN-8-153", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "A Pílula do Dia Seguinte (Anticoncepção de Emergência)", "dificuldade": "Médio", "enunciado": "A pílula do dia seguinte (levonorgestrel em dose concentrada) é um método contraceptivo de emergência que deve ser utilizado apenas em situações excepcionais (como falha ou rompimento da camisinha ou violência sexual). Sobre o mecanismo e uso dessa medicação, é cientificamente correto afirmar que:", "alternativas": {"A": "Ela é uma pílula abortiva que interrompe uma gestação já implantada.", "B": "Ela atua atrasando ou inibindo a ocorrência da ovulação e alterando o muco cervical antes que a fecundação aconteça; ela NÃO provoca aborto caso a nidação já tenha ocorrido e não deve ser usada como método de rotina devido a sua alta carga hormonal.", "C": "Ela protege contra todas as Infecções Sexualmente Transmissíveis (ISTs).", "D": "Ela deve ser tomada diariamente antes de todas as refeições.", "E": "Ela cura a sífilis e o vírus da AIDS em menos de 12 horas."}, "resposta_correta": "B", "justificativa": "A anticoncepção de emergência (levonorgestrel) não é abortiva: atua suprimindo ou postergando o pico pré-ovulatório de LH se ingerida antes da ovulação e espessando o muco; não impede a nidação nem interrompe gravidez clínica já estabelecida.", "possui_imagem": false},
  {"id": 154, "uid": "CIEN-8-154", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Dispositivo Intrauterino (DIU): Cobre vs. Hormonal", "dificuldade": "Médio", "enunciado": "O DIU é uma pequena peça flexível em formato de 'T' inserida por um médico ginecologista no interior da cavidade uterina. Os dois tipos mais comuns de DIU (DIU de cobre e DIU hormonal de levonorgestrel) exercem seus efeitos contraceptivos respectivamente por:", "alternativas": {"A": "Queimar os ovários com calor e congelar o colo do útero.", "B": "O DIU de cobre libera íons de cobre que têm ação espermicida e provocam uma reação inflamatória estéril no endométrio hostil aos espermatozoides; o DIU hormonal libera doses contínuas de progesterona que afinam o endométrio e espessam o muco cervical impedindo a passagem dos espermatozoides.", "C": "Retirar todos os óvulos do corpo feminino através de um fio.", "D": "Bloquear a entrada de sangue nas artérias do coração.", "E": "Impedir que a mulher sinta dor durante a menstruação."}, "resposta_correta": "B", "justificativa": "O DIU de cobre libera microquantidades de íons Cu2+ com toxicidade citolítica sobre espermatozoides e ativação de macrófagos endometriais; o DIU liberador de levonorgestrel (SIU-LNG) atrofia o epitélio endometrial e induz muco cervical viscoso impenetrável.", "possui_imagem": false},
  {"id": 155, "uid": "CIEN-8-155", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Método da Tabelinha (Ogino-Knaus) e Falhas", "dificuldade": "Médio", "enunciado": "O método comportamental da 'tabelinha' consiste em calcular os dias do período fértil da mulher a partir do histórico de ciclos anteriores e evitar relações sexuais desprotegidas durante esses dias. O motivo pelo qual a tabelinha apresenta altas taxas de falha em adolescentes é:", "alternativas": {"A": "Os espermatozoides conseguem voar pelo ar até o útero da menina.", "B": "O ciclo menstrual de jovens adolescentes é frequentemente irregular devido à imaturidade do eixo hormonal hipotálamo-hipófise-ovários, de modo que a ovulação pode oscilar imprevisivelmente e espermatozoides sobrevivem até 3 a 5 dias no trato genital feminino.", "C": "A tabelinha só funciona se o casal fizer jejum completo de água.", "D": "As meninas nunca ovulam antes dos vinte anos de idade.", "E": "A tabelinha transforma todos os óvulos em gêmeos bivitelinos."}, "resposta_correta": "B", "justificativa": "Na adolescência e menarca recente, ciclos anovulatórios e fases foliculares de comprimento errático são extremamente comuns. Como espermatozoides sobrevivem viáveis nas criptas cervicais por até 5 dias aguardando a ovulação, previsões matemáticas de calendário têm índice de Pearl inaceitavelmente alto.", "possui_imagem": false},
  {"id": 156, "uid": "CIEN-8-156", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Janela Imunológica nos Testes de HIV", "dificuldade": "Médio", "enunciado": "Uma pessoa que teve uma relação sexual desprotegida com parceiro de sorologia desconhecida realiza um teste rápido de HIV no posto de saúde no dia seguinte ao ocorrido e o resultado dá 'negativo'. O profissional de saúde informa que o resultado negativo não descarta a infecção recente e agenda um novo teste para 30 dias depois. Essa recomendação deve-se ao conceito de:", "alternativas": {"A": "Imunidade natural perpétua de 24 horas.", "B": "Janela imunológica: o intervalo de tempo entre o momento do contágio pelo vírus e a produção de anticorpos pelo organismo em quantidade suficiente para serem detectados pelo teste diagnóstico.", "C": "Tempo necessário para o vírus se transformar em bactéria de garganta.", "D": "Efeito colateral do uso de preservativos no dia do teste.", "E": "Falta de reagentes de qualidade nos laboratórios municipais."}, "resposta_correta": "B", "justificativa": "A janela imunológica diagnóstica é o intervalo entre a inoculação viral e a soroconversão detectável por ensaios de anticorpos (testes rápidos de 3ª ou 4ª geração com detecção do antígeno p24 e anticorpos anti-HIV em ~15 a 30 dias). Testagens imediatas no dia seguinte fornecem resultado falso-negativo.", "possui_imagem": false},
  {"id": 157, "uid": "CIEN-8-157", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Profilaxia Pré-Exposição (PrEP) e Pós-Exposição (PEP)", "dificuldade": "Médio", "enunciado": "O Sistema Único de Saúde (SUS) disponibiliza gratuitamente duas estratégias farmacológicas de alta eficácia na prevenção da infecção pelo vírus HIV: a PEP e a PrEP. A diferença de indicação entre a PEP e a PrEP é:", "alternativas": {"A": "A PEP é tomada antes do sexo e a PrEP é uma cirurgia definitiva.", "B": "A PEP (Pós-Exposição) é um tratamento de urgência com antirretrovirais iniciado em até 72 horas após uma situação de risco e mantido por 28 dias; a PrEP (Pré-Exposição) consiste no uso contínuo preventivo de medicamentos antes de exposições ao vírus por pessoas em maior vulnerabilidade.", "C": "A PEP cura a AIDS terminal e a PrEP é uma vacina de dose única.", "D": "Ambas são pomadas para passar na pele antes de dormir.", "E": "A PrEP é indicada apenas para pessoas que já têm diagnóstico de AIDS."}, "resposta_correta": "B", "justificativa": "A PEP (Profilaxia Pós-Exposição) é um esquema antirretroviral de emergência de 28 dias iniciado idealmente nas primeiras 2 horas e no máximo até 72 h pós-contato; a PrEP (Profilaxia Pré-Exposição) envolve uso profilático oral diário (ou sob demanda) de tenofovir/entricitabina para prevenir a replicação do HIV em mucosas.", "possui_imagem": false},
  {"id": 158, "uid": "CIEN-8-158", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Câncer de Colo de Útero e o Exame Papanicolau", "dificuldade": "Médio", "enunciado": "O exame preventivo de Papanicolau (citopatológico cervical) deve ser realizado periodicamente por mulheres sexualmente ativas. A grande importância preventiva desse exame de rastreamento é:", "alternativas": {"A": "Curar infecções bacterianas do estômago.", "B": "Coletar células da descamação do colo do útero para identificar alterações celulares pré-cancerosas (lesões precursoras causadas pela infecção crônica por subtipos oncogênicos do HPV) antes que elas evoluam para um câncer invasivo, permitindo tratamento precoce e cura.", "C": "Verificar se a mulher está grávida de gêmeos univitelinos.", "D": "Medir a pressão arterial e a quantidade de glicose no sangue da mulher.", "E": "Testar a audição do feto durante a gravidez."}, "resposta_correta": "B", "justificativa": "O rastreamento citopatológico de Papanicolau detecta atipias epiteliais escamosas e displasias intraepiteliais cervicais (NIC I, II e III) associadas à persistência de HPV oncogênico, viabilizando conizações curativas ambulatoriais anos antes da progressão para carcinoma invasivo de colo uterino.", "possui_imagem": false},
  {"id": 159, "uid": "CIEN-8-159", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Gonorreia e Clamídia: Riscos de Infertilidade", "dificuldade": "Médio", "enunciado": "A gonorreia (causada pela bactéria Neisseria gonorrhoeae) e a infecção por clamídia (Chlamydia trachomatis) são ISTs bacterianas que causam corrimento uretral ou vaginal purulento e ardor miccional. Quando não são diagnosticadas e tratadas adequadamente com antibióticos, essas infecções podem ascender pelo trato genital feminino e causar Doença Inflamatória Pélvica (DIP), que frequentemente acarreta:", "alternativas": {"A": "Crescimento de pelos grossos na planta dos pés.", "B": "Obstrução cicatricial irreversível das tubas uterinas por aderências e fibrose, resultando em infertilidade permanente e elevado risco de gravidez ectópica futura.", "C": "Perda permanente da audição em ambos os ouvidos.", "D": "Aumento do tamanho do coração até estourar a caixa torácica.", "E": "Transformação das bactérias em vírus de gripe."}, "resposta_correta": "B", "justificativa": "A infecção ascendente bacteriana coloniza o endométrio e as tubas uterinas, desencadeando salpingite e Doença Inflamatória Pélvica (DIP); a cicatrização fibrosa obstrui o lúmen tubário ou destrói o epitélio ciliar, bloqueando a migração do ovócito e causando infertilidade tubária ou gravidez ectópica.", "possui_imagem": false},
  {"id": 160, "uid": "CIEN-8-160", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Fisiologia da Ereção Peniana e o Óxido Nítrico", "dificuldade": "Médio", "enunciado": "A ereção peniana é um evento neurovascular complexo desencadeado por estímulos sexuais físicos ou psicogênicos. Durante a excitação, terminações nervosas parassimpáticas e o endotélio vascular liberam óxido nítrico (NO), que promove:", "alternativas": {"A": "A contração violenta das artérias impedindo a entrada de sangue no pênis.", "B": "O relaxamento da musculatura lisa das artérias cavernosas e das trabéculas dos corpos cavernosos, permitindo que grande volume de sangue arterial sob pressão preencha os espaços vasculares, comprimindo as veias de drenagem periféricas e mantendo a rigidez peniana.", "C": "A destruição dos espermatozoides armazenados no epidídimo.", "D": "O congelamento do tecido esponjoso por reações endotérmicas.", "E": "A produção instantânea de urina na bexiga."}, "resposta_correta": "B", "justificativa": "A liberação de NO ativa a guanilato ciclase e eleva o GMP cíclico (GMPc) na musculatura lisa dos corpos cavernosos, deflagrando vasodilatação arterial massiva. A expansão tecidual comprime o plexo venoso subtubular contra a túnica albugínea rígida (mecanismo veno-oclusivo), sustentando a turgência erétil.", "possui_imagem": false},
  {"id": 161, "uid": "CIEN-8-161", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Herpes Genital: Latência Viral nos Gânglios Nervosos", "dificuldade": "Médio", "enunciado": "O herpes genital (causado principalmente pelo vírus Herpes Simplex tipo 2 - HSV-2) é caracterizado pelo surgimento de pequenas vesículas dolorosas agrupadas na pele ou mucosas genitais que se rompem formando úlceras rasas. O motivo pelo qual o herpes genital não possui cura definitiva e apresenta recidivas periódicas é:", "alternativas": {"A": "O vírus se transformar em uma bactéria que não responde a antibióticos.", "B": "Após o surto inicial, o vírus migra através de axônios sensoriais e estabelece latência vitalícia no corpo celular de neurônios dos gânglios nervosos da medula sacral, reativando-se periodicamente em momentos de estresse físico, imunodepressão ou febre.", "C": "A pessoa reinfectar-se bebendo água de piscina pública.", "D": "As vesículas produzirem ovos que eclodem a cada lua cheia.", "E": "O remédio antiviral matar os glóbulos brancos da pessoa."}, "resposta_correta": "B", "justificativa": "O HSV estabelece latência episomal no núcleo dos neurônios dos gânglios sensoriais das raízes dorsais sacrais (S2-S4). O sistema imune não elimina o genoma viral abrigado no neurônio; sob estímulos desencadeantes (queda de imunidade, estresse), o vírus replica-se e viaja por transporte axonal anterógrado até a pele.", "possui_imagem": false},
  {"id": 162, "uid": "CIEN-8-162", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Circulação Fetal: O Forame Oval e o Ducto Arterioso", "dificuldade": "Médio", "enunciado": "Durante a vida intrauterina, os pulmões do feto estão colapsados e preenchidos por líquido amniótico, não realizando trocas gasosas respiratórias. O sistema circulatório fetal apresenta dois desvios vasculares (shunts) temporários que desviam o sangue oxigenado que veio da placenta para o corpo sem passar pelos pulmões colapsados: o Forame Oval (entre os dois átrios) e o:", "alternativas": {"A": "Cordão de mielina espinhal.", "B": "Ducto Arterioso (canal arterial, que conecta a artéria pulmonar diretamente à aorta).", "C": "Ureter secundário renal.", "D": "Canal deferente umbilical.", "E": "Opérculo arterial embrionário."}, "resposta_correta": "B", "justificativa": "O forame oval desvia sangue do átrio direito para o átrio esquerdo, e o ducto arterioso (ductus arteriosus) conecta o tronco pulmonar à aorta descendente, contornando a alta resistência vascular dos leitos pulmonares colapsados; ao primeiro choro pós-parto, a expansão pulmonar inverte as pressões e fecha funcionalmente esses shunts.", "possui_imagem": false},
  {"id": 163, "uid": "CIEN-8-163", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Hepatite B e Transmissão Sexual", "dificuldade": "Médio", "enunciado": "O vírus da Hepatite B (HBV) é uma IST de alta transmissibilidade (cerca de 50 a 100 vezes mais infeccioso que o HIV por contato sanguíneo ou sexual desprotegido) que ataca as células do fígado (hepatócitos). A gravidade da infecção crônica por Hepatite B reside no risco de evolução para:", "alternativas": {"A": "Paralisia muscular nos dedos dos pés.", "B": "Cirrose hepática irreversível com insuficiência do fígado e câncer primário de fígado (carcinoma hepatocelular).", "C": "Queda permanente dos dentes de leite em adultos.", "D": "Perda do sentido do paladar para alimentos doces.", "E": "Inflamação dos ossos da coluna vertebral."}, "resposta_correta": "B", "justificativa": "A infecção crônica por HBV induz inflamação necrosante contínua com fibrogênese progressiva, culminando em cirrose hepática descompensada e alta incidência de carcinoma hepatocelular, prevenível por imunização precoce com as três doses da vacina recombinante contra Hepatite B.", "possui_imagem": false},
  {"id": 164, "uid": "CIEN-8-164", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "A Barreira Hematotesticular", "dificuldade": "Médio", "enunciado": "No interior dos testículos humanos, as células de Sertoli dos túbulos seminíferos são unidas entre si por fortes junções de oclusão contínuas, formando a chamada 'Barreira Hematotesticular'. A função biológica essencial dessa barreira imunológica é:", "alternativas": {"A": "Impedir que a urina entre dentro dos testículos durante o sono.", "B": "Isolar os espermatozoides em desenvolvimento do sistema imunológico da própria pessoa, impedindo que os linfócitos e anticorpos reconheçam as novas proteínas dos espermatozoides (surgidas na meiose puberal) como corpos estranhos e iniciem um ataque autoimune causador de infertilidade.", "C": "Manter os testículos aquecidos a mais de 45 graus Celsius.", "D": "Transformar espermatozoides velhos em hormônio insulina.", "E": "Permitir que o sangue venoso saia diretamente pela uretra."}, "resposta_correta": "B", "justificativa": "Como a meiose e a espermiogênese ocorrem apenas a partir da puberdade (muito após a seleção tímica de tolerância clonal no feto), os antígenos de superfície dos espermatozoides haploides são estranhos ao sistema imune; a barreira hematotesticular confere privilégio imunológico indispensável.", "possui_imagem": false},
  {"id": 165, "uid": "CIEN-8-165", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Coito Interrompido e Suas Altas Taxas de Falha", "dificuldade": "Médio", "enunciado": "O método comportamental do 'coito interrompido' consiste em retirar o pênis da vagina momentos antes da ejaculação. Além de exigir extremo autocontrole e não proteger em nada contra ISTs, o coito interrompido é altamente ineficaz para evitar a gravidez porque:", "alternativas": {"A": "A mulher ovula obrigatoriamente logo após o ato sexual.", "B": "O fluido pré-ejaculatório transparente liberado pelas glândulas bulbouretrais durante a excitação antes do clímax pode carregar espermatozoides viáveis remanescentes de ejaculações prévias presentes na uretra, capazes de fertilizar o óvulo.", "C": "Os espermatozoides conseguem se locomover através do ar da sala.", "D": "O pênis absorve hormônios da vagina que causam gravidez à distância.", "E": "A mulher engravida pelo contato da pele com o suor masculino."}, "resposta_correta": "B", "justificativa": "O fluido pré-ejaculatório lubrificante secretado pelas glândulas de Cowper pode carrear espermatozoides viáveis presentes no trajeto uretral de ejaculações recentes; somado a erros frequentes de timing na retirada, o coito interrompido apresenta taxa de falha típica de até 22% ao ano.", "possui_imagem": false},
  {"id": 166, "uid": "CIEN-8-166", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Clitóris: Estrutura Anatômica e Função", "dificuldade": "Médio", "enunciado": "Diferente da maioria dos outros órgãos do corpo humano que acumulam funções mistas (como o pênis, que atua na micção urinária e na reprodução), o clitóris feminino é uma estrutura anatômica ímpar porque:", "alternativas": {"A": "É o órgão responsável por armazenar os óvulos antes da fecundação.", "B": "Possui como função biológica exclusiva o prazer sexual feminino, apresentando uma glande externa visível com milhares de terminações nervosas sensoriais e uma vasta estrutura interna com corpos cavernosos e bulbos vestibulares eréteis que abraçam a vagina.", "C": "Atua filtrando a urina que sai dos rins durante a corrida.", "D": "É o local onde ocorre o parto de bebês prematuros.", "E": "Produz hormônios da tireoide que regulam o crescimento das unhas."}, "resposta_correta": "B", "justificativa": "O clitóris é um complexo órgão erétil homólogo ao pênis embrionário, cuja glande externa altamente sensível conecta-se a uma volumosa arquitetura interna de corpos cavernosos e bulbos clitorianos que circundam a uretra e vagina, dedicado exclusivamente ao estímulo e prazer sexual.", "possui_imagem": false},
  {"id": 167, "uid": "CIEN-8-167", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Sífilis Congênita: Riscos e Prevenção no Pré-Natal", "dificuldade": "Médio", "enunciado": "A sífilis congênita ocorre quando a bactéria Treponema pallidum presente no sangue de uma gestante não tratada atravessa a barreira placentária e infecta o feto em desenvolvimento. As consequências devastadoras dessa infecção fetal incluem abortamento, natimorto e malformações ósseas e neurológicas graves (como dentes de Hutchinson e surdez). Para erradicar a sífilis congênita, a medida médica protocolar obrigatória é:", "alternativas": {"A": "Proibir mulheres grávidas de tomarem vacinas de infância.", "B": "A realização de testes sorológicos rápidos (VDRL/TR) no início do pré-natal, no terceiro trimestre e no momento do parto, com tratamento imediato e completo da gestante e de seu parceiro com penicilina benzatina caso o teste seja reagente.", "C": "Fazer parto cesárea em 100% das gestantes sem exames de sangue.", "D": "Dar mamadeira de leite com antibiótico ao bebê nos primeiros dez minutos.", "E": "Isolar a mãe em quarentena sem contato com a família."}, "resposta_correta": "B", "justificativa": "A triagem pré-natal universal no 1º e 3º trimestres e no parto com VDRL ou teste treponêmico rápido permite a identificação precoce da sífilis gestacional assintomática e a instituição oportuna de penicilinoterapia benzatínica com documentação de cura sorológica, prevenindo a transmissão vertical transplacentária.", "possui_imagem": false},
  {"id": 168, "uid": "CIEN-8-168", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Microbiota Vaginal e Bacilos de Döderlein", "dificuldade": "Médio", "enunciado": "A cavidade vaginal de uma mulher adulta em idade fértil é colonizada por uma microbiota bacteriana saudável dominada por lactobacilos (conhecidos classicamente como bacilos de Döderlein). A presença desses microrganismos benéficos protege a vagina contra infecções e fungos oportunistas (como a candidíase) porque eles:", "alternativas": {"A": "Queimam as células epiteliais da vagina com fogo atômico.", "B": "Consomem glicogênio secretado pelas células vaginais sob estímulo do estrogênio e produzem ácido lático, mantendo o pH vaginal ácido (em torno de 3,8 a 4,5), ambiente químico adverso à proliferação de bactérias patogênicas invasoras.", "C": "Produzem espermatozoides que fertilizam os óvulos no útero.", "D": "Fazem a mulher parar de produzir muco cervical no calor.", "E": "Transformam o sangue da menstruação em água potável."}, "resposta_correta": "B", "justificativa": "Os lactobacilos da microbiota comensal metabolizam o glicogênio celular em ácido lático e peróxido de hidrogênio (H2O2), mantendo o microambiente vaginal em pH ácido ótimo (3,8 - 4,5), barreira bioquímica natural que impede a colonização por bactérias anaeróbias patogênicas (vaginose) e proliferação de Candida albicans.", "possui_imagem": false},
  {"id": 169, "uid": "CIEN-8-169", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Reação Acrossômica e Bloqueio da Poliespermia na Fecundação", "dificuldade": "Difícil", "enunciado": "No momento da fertilização na tuba uterina, o espermatozoide colide com a zona pelúcida do ovócito e libera enzimas de sua vesícula acrossômica (como a hialuronidase e a acrossina). Assim que o primeiro espermatozoide funde sua membrana com o ovócito, o zigoto deve impedir obrigatoriamente a entrada de outros espermatozoides (bloqueio da poliespermia). Os dois mecanismos que impedem a poliespermia são:", "alternativas": {"A": "A quebra mecânica dos flagelos de todos os outros espermatozoides pelo útero.", "B": "O bloqueio rápido por despolarização elétrica imediata da membrana do ovócito (influxo de íons) seguido pelo bloqueio lento (reação cortical com exocitose de grânulos corticais que endurecem a zona pelúcida e clivam os receptores ZP3), impedindo que mais espermatozoides penetrem.", "C": "A morte de todos os espermatozoides por choque térmico de 50 graus.", "D": "A absorção do ovócito pelo ovário da mãe para escondê-lo.", "E": "O fechamento do colo do útero por um tampão de osso calcário."}, "resposta_correta": "B", "justificativa": "A poliespermia (letal em humanos por gerar zigotos triploides inviáveis) é prevenida por dois mecanismos: 1) Bloqueio elétrico rápido por despolarização da membrana do ovócito (-70 mV para +20 mV); 2) Bloqueio mecânico lento deflagrado por onda de Ca2+ intracelular, provocando exocitose de enzimas corticais que inativam ZP3 e endurecem a zona pelúcida (reação zonal).", "possui_imagem": false},
  {"id": 170, "uid": "CIEN-8-170", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Eixo Hipotálamo-Hipófise-Gonadal e Pulsos de GnRH", "dificuldade": "Difícil", "enunciado": "O controle hormonal de toda a fertilidade e gametogênese humana é exercido pelo eixo Hipotálamo-Hipófise-Gonadal (HHG). O hormônio liberador de gonadotrofinas (GnRH) é secretado por neurônios do hipotálamo em pulsos periódicos sincronizados na circulação porta-hipofisária. A relevância fisiológica da liberação pulsátil (e não contínua) do GnRH é:", "alternativas": {"A": "Evitar que os neurônios do cérebro durmam durante o dia.", "B": "Impedir a dessensibilização (down-regulation) dos receptores de GnRH na adenoipófise, assegurando a síntese e liberação sustentada de FSH e LH pelas células gonadotróficas (a infusão contínua não pulsátil de GnRH desliga completamente a secreção de FSH e LH, sendo utilizada em medicamentos de castração química terapêutica).", "C": "Garantir que a pessoa só ovule durante a lua cheia.", "D": "Aumentar a velocidade com que o sangue chega aos rins.", "E": "Impedir que a testosterona se transforme em glicose no fígado."}, "resposta_correta": "B", "justificativa": "A secreção de GnRH exige frequência e amplitude pulsátil fisiológica precisa (um pulso a cada 60-90 minutos). Estímulos contínuos saturam os receptores gonadotróficos, induzindo sua internalização e parada completa da transcrição de FSH e LH (princípio farmacológico dos análogos de GnRH de depósito em oncologia e puberdade precoce).", "possui_imagem": false},
  {"id": 171, "uid": "CIEN-8-171", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Espermatogênese vs. Ovulogênese: Cinética e Assimetria Celular", "dificuldade": "Difícil", "enunciado": "Na comparação meiótica entre a gametogênese masculina e a feminina na espécie humana, existem diferenças citológicas e temporais profundas. Enquanto a espermatogênese inicia-se na puberdade, ocorre continuamente ao longo da vida e produz quatro espermatozoides funcionais iguais a partir de cada espermatócito I, a ovulogênese caracteriza-se por:", "alternativas": {"A": "Produzir 100 óvulos gigantes a cada divisão celular da menopausa.", "B": "Iniciar-se ainda na vida intrauterina do feto feminino (onde as células ficam estagnadas no prófase I da meiose), retomar divisões cíclicas na puberdade e gerar divisões citoplasmáticas extremamente assimétricas, resultando em um único ovócito volumoso funcional viável e três corpúsculos polares degenerativos desprovidos de citoplasma.", "C": "Ocorrer exclusivamente no fígado sem intervenção dos ovários.", "D": "Terminar aos cinco anos de idade antes da infância.", "E": "Produzir gametas masculinos nas meninas que praticam esportes."}, "resposta_correta": "B", "justificativa": "A ovulogênese feminina tem início pré-natal com meiose bloqueada no diploteno da prófase I até a puberdade; a citocinese meiótica é marcantemente desigual para preservar todas as reservas vitelínicas e organelas citoplasmáticas em um único ovócito funcional haploide, descartando núcleos excedentários em corpúsculos polares.", "possui_imagem": false},
  {"id": 172, "uid": "CIEN-8-172", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Ciclo Viral do HIV e Terapia Antirretroviral (TARV)", "dificuldade": "Difícil", "enunciado": "O vírus HIV é um retrovírus cujo genoma é composto por duas fitas simples de RNA associadas a enzimas específicas. A Terapia Antirretroviral (TARV) moderna combina medicamentos que bloqueiam diferentes etapas do ciclo replicativo viral. A enzima exclusiva do HIV que converte o seu RNA viral em uma fita dupla de DNA proviral no citoplasma do linfócito hospedeiro, alvo de fármacos inibidores nucleosídeos (como o AZT e tenofovir), é a:", "alternativas": {"A": "DNA polimerase mitocondrial.", "B": "Transcriptase Reversa.", "C": "Amilase salivar humana.", "D": "Insulina desoxirribonucleica.", "E": "RNAse gástrica ácida."}, "resposta_correta": "B", "justificativa": "A transcriptase reversa (RT) do HIV sintetiza uma cópia de cDNA a partir do molde de RNA genômico viral, violando o dogma central clássico. Inibidores da transcriptase reversa (ITRN e ITRNN) bloqueiam essa retrotranscrição precoce, impedindo a integração do DNA viral ao genoma do hospedeiro mediada pela integrase.", "possui_imagem": false},
  {"id": 173, "uid": "CIEN-8-173", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Patogênese do HPV e Proteínas Oncogênicas E6 e E7", "dificuldade": "Difícil", "enunciado": "Subtipos de alto risco oncogênico do HPV (principalmente HPV-16 e HPV-18) integram seu DNA ao genoma das células basais do epitélio cervical humano, expressando as oncoproteínas virais E6 e E7. O mecanismo molecular pelo qual essas proteínas induzem a transformação maligna e a progressão para câncer de colo uterino é:", "alternativas": {"A": "Aumentar a produção de queratina nos ossos da bacia.", "B": "A proteína E6 liga-se à proteína supressora de tumor p53 e promove sua degradação proteossomal rápida, enquanto a proteína E7 inativa a proteína do retinoblastoma (pRb), anulando os pontos de checagem do ciclo celular e permitindo a proliferação descontrolada de células com mutações no DNA.", "C": "Destruir a membrana de gordura dos glóbulos vermelhos.", "D": "Transformar as células uterinas em neurônios sensitivos motores.", "E": "Bloquear a entrada de sangue na artéria femoral."}, "resposta_correta": "B", "justificativa": "Os genes supressores de tumor TP53 (o 'guardião do genoma', indutor de apoptose) e RB1 (regulador do ponto de checagem G1/S do ciclo celular) são os alvos das oncoproteínas virais E6 e E7 do HPV de alto risco; a inativação concomitante de p53 e pRb desregula a proliferação e bloqueia o reparo de danos no DNA celular.", "possui_imagem": false},
  {"id": 174, "uid": "CIEN-8-174", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Mecanismo da Menopausa e Esgotamento Folicular", "dificuldade": "Difícil", "enunciado": "O climatério e a menopausa definitiva marcam o término da fase reprodutiva da mulher, ocorrendo habitualmente entre os 45 e 55 anos. A causa endócrina primária da menopausa é:", "alternativas": {"A": "O envelhecimento dos ossos da coluna vertebral.", "B": "O esgotamento quase total da reserva de folículos ovarianos presentes desde o nascimento por atresia e ovulações acumuladas; com a ausência de folículos responsivos nos ovários, a síntese de estrogênio e inibina despenca, fazendo com que os níveis hipofisários de FSH e LH subam acentuadamente por perda de feedback negativo.", "C": "A paralisação da glândula tireoide devido ao estresse da vida adulta.", "D": "A substituição do útero por tecido adiposo de reserva.", "E": "O congelamento das tubas uterinas por falta de circulação."}, "resposta_correta": "B", "justificativa": "Diferente dos homens que produzem espermatozoides contínuos por células-tronco germinativas (espermatogônias), mulheres nascem com reserva oocitária finita (~1 a 2 milhões de folículos primordiais ao nascer). Na menopausa, a senescência folicular zera a produção de estradiol e inibina B; sem freio de feedback negativo, os níveis de FSH sérico disparam para patamares superiores a 40 mUI/mL.", "possui_imagem": false},
  {"id": 175, "uid": "CIEN-8-175", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Morfologia e Fisiologia do Espermatozoide Maduro", "dificuldade": "Difícil", "enunciado": "O espermatozoide humano maduro é uma célula terminal altamente condensada e especializada na locomoção e penetração ovocitária. Em sua peça intermediária concentram-se dezenas de mitocôndrias dispostas em espiral ao redor do axonema flagelar. A função bioquímica essencial dessa bainha mitocondrial na peça intermediária é:", "alternativas": {"A": "Armazenar DNA genético extra de reserva para o embrião.", "B": "Sintetizar grandes quantidades de ATP através da fosforilação oxidativa aeróbica para alimentar as proteínas motoras de dineína do axonema, sustentando o batimento ondulatório contínuo do flagelo até atingir a tuba uterina.", "C": "Dissolver a casca de queratina do pênis durante a ejaculação.", "D": "Produzir testosterona líquida para alimentar a próstata.", "E": "Substituir o núcleo celular caso este sofra mutações no caminho."}, "resposta_correta": "B", "justificativa": "O axonema flagelar do espermatozoide possui estrutura microtubular 9+2 com braços moleculares de dineína ATPase que deslizam microtúbulos adjacentes. A hidrólise contínua de ATP gerado pela cadeia respiratória das mitocôndrias helicoidais da peça intermediária supre a força mecânica de natação contra o fluxo ciliar tubário.", "possui_imagem": false},
  {"id": 176, "uid": "CIEN-8-176", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Imunologia da Gestação: O Paradoxo do Aloenxerto Fetal", "dificuldade": "Difícil", "enunciado": "Do ponto de vista imunológico, o embrião humano implantado no útero é um 'aloenxerto semialogênico' (carrega 50% de antígenos e genes de origem paterna estranhos ao sistema imunológico da mãe). Em condições normais, o útero não rejeita o embrião como um corpo estranho graças a adaptações imunológicas locais no trofoblasto, tais como:", "alternativas": {"A": "A destruição total de todos os glóbulos brancos do corpo da mãe.", "B": "A ausência de moléculas clássicas do complexo de histocompatibilidade HLA-A e HLA-B na superfície do sinciciotrofoblasto invasor e a expressão de moléculas atípicas não clássicas como HLA-G, que inibem ativamente o ataque citotóxico de células Natural Killer (células NK uterinas) e linfócitos T maternos.", "C": "O fato de o feto não possuir sangue até o nono mês de gravidez.", "D": "A produção de veneno bacteriano pelo endométrio que mata os linfócitos.", "E": "A presença de uma carapaça de osso isolante entre a mãe e o bebê."}, "resposta_correta": "B", "justificativa": "A tolerância materno-fetal decorre de mecanismos imunorreguladores ativos da decídua: trofoblastos extravilosos não expressam antígenos polimórficos clássicos HLA de classe I (HLA-A/B), mas expressam moléculas imunomoduladoras (HLA-G e HLA-E) que se ligam a receptores inibitórios (KIR) de células NK deciduais e induzem expansão de linfócitos T reguladores (Treg).", "possui_imagem": false},
  {"id": 177, "uid": "CIEN-8-177", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Endometriose e Fisiopatologia da Dor e Infertilidade", "dificuldade": "Difícil", "enunciado": "A endometriose é uma condição ginecológica inflamatória crônica que acomete milhões de mulheres em idade reprodutiva, caracterizada pela presença e proliferação de tecido endometrial fora da cavidade uterina (como nos ovários, tubas uterinas e peritônio pélvico). Sob a influência dos hormônios do ciclo menstrual, esses focos ectópicos de endométrio sangram ciclicamente, provocando:", "alternativas": {"A": "Crescimento de dentes no interior do intestino.", "B": "Inflamação crônica severa, dor pélvica intensa (dismenorreia incapacitante, dor na relação sexual - dispareunia) e formação de aderências cicatriciais densas que distorcem a anatomia pélvica e causam infertilidade mecânica e imunológica.", "C": "A cura instantânea de todas as infecções sexualmente transmissíveis.", "D": "A perda da capacidade do coração de bater no inverno.", "E": "Transformação dos ovários em tecido muscular esquelético."}, "resposta_correta": "B", "justificativa": "Focos ectópicos de estroma e glândulas endometriais respondem ciclicamente a estrogênios e progestagênios com micro-hemorragias locais; a liberação contínua de mediadores inflamatórios (prostaglandinas, citocinas) gera neurogênese e dor neuropática crônica, além de aderências fibróticas que bloqueiam a motilidade fímbrico-tubária.", "possui_imagem": false},
  {"id": 178, "uid": "CIEN-8-178", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Sífilis Terciária: Neurossífilis e Gomas Luéticas", "dificuldade": "Difícil", "enunciado": "Quando uma pessoa infectada pela bactéria da sífilis (Treponema pallidum) não recebe tratamento com antibióticos, a infecção pode evoluir silenciosamente ao longo de 10 a 30 anos para a fase terciária da doença. As manifestações clínicas graves características da sífilis terciária tardia incluem:", "alternativas": {"A": "Resfriado comum e tosse alérgica passageira.", "B": "Neurossífilis (demência progressiva, paralisia geral e perda de reflexos espinhais / tabes dorsalis), aneurismas da aorta ascendente e lesões destrutivas granulomatosas deformantes em ossos e pele chamadas gomas sifilíticas.", "C": "Produção excessiva de insulina e ganho de massa muscular espontâneo.", "D": "Transformação do sangue venoso em água do mar pura.", "E": "Crescimento de penas nas articulações dos membros."}, "resposta_correta": "B", "justificativa": "A sífilis terciária tardia envolve lesões inflamatórias granulomatosas destrutivas mediadas por hipersensibilidade tardia (gomas sifilíticas em pele e osso), endarterite obliterante dos vasa vasorum com aneurisma sacular de aorta e invasão do sistema nervoso central com desmielinização dos cordões posteriores da medula (tabes dorsalis) e paralisia progressiva.", "possui_imagem": false},
  {"id": 179, "uid": "CIEN-8-179", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Ação Antivirais Inibidores de Protease no Tratamento do HIV", "dificuldade": "Difícil", "enunciado": "Nos coquetéis modernos de antirretrovirais utilizados no SUS para o tratamento de pessoas vivendo com HIV, uma classe farmacológica fundamental é a dos 'Inibidores de Protease' (como o ritonavir e darunavir). A enzima viral protease desempenha o papel essencial de:", "alternativas": {"A": "Quebrar os açúcares da glicose para alimentar os vírus no sangue.", "B": "Clivar cadeias polipeptídicas precursoras virais (poliproteínas Gag e Gag-Pol) em proteínas estruturais e funcionais individuais menores no interior dos novos vírions recém-brotados, etapa indispensável para a maturação e infectividade dos novos vírus gerados.", "C": "Transformar o vírus HIV em uma bactéria sensível a penicilina.", "D": "Remover as proteínas do sangue da pessoa para desidratar o corpo.", "E": "Impedir que a pessoa durma para que o vírus não se reproduza."}, "resposta_correta": "B", "justificativa": "A protease retroviral cliva as poliproteínas precursoras recém-sintetizadas no vírion imaturo após a gemulação; a inibição competitiva da enzima protease resulta na produção de partículas virais imaturas e defeituosas incapazes de infectar novas células hospedeiras.", "possui_imagem": false},
  {"id": 180, "uid": "CIEN-8-180", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Bloqueio Hipofisário por Anticoncepcionais de Progestagênio Puro", "dificuldade": "Difícil", "enunciado": "Métodos contraceptivos como o implante subdérmico de etonogestrel e a injeção trimestral de acetato de medroxiprogesterona contêm apenas derivados de progesterona (sem estrogênio). O mecanismo fisiológico com que esses métodos atingem índices de eficácia contraceptiva superiores a 99% baseia-se em:", "alternativas": {"A": "Neutralizar quimicamente os espermatozoides através de veneno muscular.", "B": "Suprimir de forma robusta e contínua o pico pré-ovulatório de LH (bloqueando a ovulação na maioria dos ciclos), induzir atrofia persistente do endométrio hostil à implantação e espessar intensamente o muco cervical uterino, tornando-o uma barreira gelatinosa impenetrável aos espermatozoides.", "C": "Remover os ovários cirurgicamente através de magnetismo.", "D": "Fazer a mulher ovular apenas espermatozoides masculinos.", "E": "Impedir que a mulher beba água durante o período da gravidez."}, "resposta_correta": "B", "justificativa": "Progestagênios de alta potência bloqueiam o surto de LH hipofisário por ação central, atrofiam a decídua endometrial impedindo nidação e induzem alteração profunda nas glicoproteínas do muco cervical (efeito gestagênico), tornando-o viscoso, ácido e impermeável aos espermatozoides.", "possui_imagem": false},
  {"id": 181, "uid": "CIEN-8-181", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Clamídia Assintomática e Transmissão Silenciosa", "dificuldade": "Difícil", "enunciado": "Estudos epidemiológicos do Ministério da Saúde alertam que a infecção por Chlamydia trachomatis é a IST bacteriana mais disseminada no mundo entre jovens de 15 a 24 anos, com a particularidade de ser assintomática em mais de 70% a 80% das mulheres e em 50% dos homens infectados. O perigo epidemiológico dessa ausência de sintomas clínicos evidentes é:", "alternativas": {"A": "A bactéria não causar nenhum tipo de dano a longo prazo ao corpo humano.", "B": "A pessoa infectada atua como portadora assintomática e dissemina a bactéria inadvertidamente para parceiros sexuais desprotegidos, enquanto a infecção silenciosa progride cronicamente causando salpingite subclínica e infertilidade tubária sem que a mulher perceba.", "C": "A bactéria ser destruída espontaneamente pelo ar em 24 horas.", "D": "Os homens deixarem de produzir pelos corporais.", "E": "A clamídia transformar-se em vírus da gripe comum."}, "resposta_correta": "B", "justificativa": "A ausência de sinais clínicos agudos (como dor evidente ou corrimento abundante) retarda a busca por assistência médica; a persistência intracelular do microrganismo desencadeia resposta inflamatória fibrosante silenciosa nas vias genitais superiores, sendo a principal causa evitável de infertilidade tubária secundária no mundo.", "possui_imagem": false},
  {"id": 182, "uid": "CIEN-8-182", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Ação da Ocitocina e Prolactina no Parto e na Lactação", "dificuldade": "Difícil", "enunciado": "No final da gravidez e durante o puerpério da mulher, dois hormônios hipofisários exercem papéis complementares e sincronizados no parto e na amamentação: a ocitocina (produzida no hipotálamo e liberada pela neuroipófise) e a prolactina (secretada pela adenoipófise). Suas respectivas funções fisiológicas primárias são:", "alternativas": {"A": "A prolactina produz leite no estômago e a ocitocina diminui a respiração materna.", "B": "A ocitocina estimula as contrações rítmicas vigorosas do miométrio uterino durante o trabalho de parto e a ejeção ativa do leite pelas células mioepiteliais mamárias; a prolactina atua na síntese e produção biológica contínua do leite pelas células alveolares da glândula mamária.", "C": "A ocitocina impede a gravidez e a prolactina induz a ovulação imediata.", "D": "Ambos os hormônios atuam exclusivamente no desenvolvimento dos dentes do feto.", "E": "A ocitocina resfria as mamas e a prolactina queima gordura no fígado."}, "resposta_correta": "B", "justificativa": "A prolactina é o hormônio lactogênico por excelência (promove transcrição gênica de caseínas e lactose nas células alveolares mamárias). A ocitocina atua como hormônio ejetor e uterotônico: dispara o reflexo neuroendócrino de ejeção láctea contraindo mioepitélio sob estímulo de sucção do mamilo e comanda as contrações expulsivas uterinas do parto (reflexo de Ferguson).", "possui_imagem": false},
  {"id": 183, "uid": "CIEN-8-183", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Diagnóstico Molecular e Carga Viral no HIV", "dificuldade": "Difícil", "enunciado": "No acompanhamento clínico de pessoas vivendo com HIV, a eficácia do tratamento antirretroviral é monitorada pelo exame de 'Carga Viral plasmática' por biologia molecular (RT-PCR quantitativo). Quando o exame atesta que a carga viral do paciente está 'Indetectável' (menos de 50 cópias de RNA/mL de sangue) de forma sustentada por mais de seis meses, a comunidade científica e a OMS estabelecem o consenso médico 'I = I' (Indetectável = Intransmissível). Esse princípio científico afirma categoricamente que:", "alternativas": {"A": "O paciente está 100% curado e nunca mais precisará tomar medicamentos na vida.", "B": "A pessoa com carga viral indetectável em uso correto da TARV não transmite o vírus HIV por via sexual para nenhuma outra pessoa, rompendo a cadeia epidemiológica de transmissão.", "C": "O vírus HIV transformou-se em uma bactéria de pele inofensiva.", "D": "O paciente tornou-se imune a todas as outras doenças do mundo.", "E": "O vírus foi completamente eliminado de todos os tecidos do corpo humano."}, "resposta_correta": "B", "justificativa": "O consenso científico global 'I = I' (Indetectável = Intransmissível), ratificado pela OMS e CDC, comprova por ensaios clínicos robustos (Partner 1 e 2) que a supressão virológica mantida pela TARV reduz a concentração viral nos fluidos genitais a níveis tão insignificantes que a transmissão sexual torna-se nula.", "possui_imagem": false},
  {"id": 184, "uid": "CIEN-8-184", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Fisiopatologia da Pré-Eclâmpsia e Invasão Trofoblástica", "dificuldade": "Difícil", "enunciado": "A pré-eclâmpsia é uma complicação obstétrica grave e potencialmente fatal caracterizada por hipertensão arterial e proteinúria a partir da 20ª semana de gestação. A causa etiológica primária dessa síndrome reside em uma falha precoce na formação placentária, que consiste em:", "alternativas": {"A": "A mãe beber água gelada demais durante o primeiro mês.", "B": "A invasão incompleta e deficiente das artérias espiraladas uterinas pelo trofoblasto embrionário, fazendo com que os vasos maternos permaneçam estreitos e com alta resistência, gerando hipóxia e isquemia placentária crônica com liberação massiva de fatores antiangiogênicos tóxicos para a circulação materna.", "C": "A quebra mecânica dos ossos do feto dentro do útero.", "D": "O feto produzir veneno de serpente no interior da placenta.", "E": "A ausência total de vasos sanguíneos no cordão umbilical."}, "resposta_correta": "B", "justificativa": "A pré-eclâmpsia decorre do remodelamento defeituoso da vasculatura uteroplacentária: a segunda onda de invasão endovascular pelo citotrofoblasto falha em transformar as artérias espiraladas musculares em condutos de baixa resistência; a hipoperfusão placentária crônica induz liberação de sFlt-1 e disfunção endotelial sistêmica materna.", "possui_imagem": false},
  {"id": 185, "uid": "CIEN-8-185", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Ação Antivirais Inibidores de Integrase (Dolutegravir)", "dificuldade": "Difícil", "enunciado": "No esquema de primeira linha preconizado pelo Ministério da Saúde do Brasil para o tratamento do HIV, utiliza-se amplamente o antirretroviral Dolutegravir (DTG). O Dolutegravir pertence à classe dos Inibidores da Integrase (INSTI), cujo mecanismo farmacológico consiste em:", "alternativas": {"A": "Quebrar as proteínas da casca externa dos glóbulos brancos.", "B": "Impedir a ação da enzima integrase do HIV, bloqueando a etapa catalítica em que o DNA viral recém-sintetizado se insere e se integra fisicamente ao cromossomo do DNA nuclear da célula hospedeira humana, inviabilizando a produção de novos vírus.", "C": "Neutralizar o oxigênio da corrente sanguínea do paciente.", "D": "Transformar o sangue do paciente em álcool gel protetor.", "E": "Substituir todos os linfócitos T por neurônios motores."}, "resposta_correta": "B", "justificativa": "A integrase do HIV catalisa a clivagem 3'-terminal e transferência de fita que insere o genoma viral transcrito no DNA genômico do linfócito T-CD4. Fármacos inibidores da integrase (como dolutegravir) quelam os cátions divalentes de magnésio no sítio ativo da enzima, abortando a integração cromossômica com altíssima barreira genética.", "possui_imagem": false},
  {"id": 186, "uid": "CIEN-8-186", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Infertilidade por Fator Masculino: Varicocele", "dificuldade": "Difícil", "enunciado": "A varicocele (dilatação varicosa anormal das veias do plexo pampiniforme que drenam os testículos) é a principal causa reversível de infertilidade masculina tratável cirurgicamente. A presença de varizes testiculares prejudica a contagem e motilidade dos espermatozoides (oligoastenozoospermia) porque:", "alternativas": {"A": "As veias dilatadas cortam o pênis por dentro durante a ereção.", "B": "O represamento e estase de sangue venoso aquecido ao redor dos testículos eleva cronicamente a temperatura escrotal (anulando a refrigeração fisiológica) e causa acúmulo de metabólitos e estresse oxidativo que danificam o DNA dos espermatozoides nos túbulos seminíferos.", "C": "As veias dilatadas engolem os espermatozoides como peixes predadores.", "D": "A varicocele transforma os testículos em ossos de cartilagem sólida.", "E": "A dilatação das veias impede que o homem produza urina nos rins."}, "resposta_correta": "B", "justificativa": "O plexo venoso pampiniforme atua normalmente como trocador de calor contracorrente para resfriar a artéria testicular. Na varicocele, o refluxo e incompetência valvular elevam a temperatura intratesticular e geram hipóxia tecidual crônica e espécies reativas de oxigênio (ROS), induzindo apoptose de espermatócitos e fragmentação do DNA espermático.", "possui_imagem": false},
  {"id": 187, "uid": "CIEN-8-187", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Imunidade Passiva Transplacentária de Anticorpos IgG", "dificuldade": "Difícil", "enunciado": "Durante o terceiro trimestre da gravidez, ocorre uma maciça transferência ativa de anticorpos maternos da classe Imunoglobulina G (IgG) da corrente sanguínea da mãe para a circulação fetal através da placenta. Esse transporte imunológico específico é mediado por receptores Fc neonatais (FcRn) e confere ao bebê recém-nascido:", "alternativas": {"A": "Imunidade passiva temporária vital que protege o recém-nascido contra uma variedade de vírus e bactérias durante os primeiros meses de vida, enquanto seu próprio sistema imunológico ainda é imaturo.", "B": "Cura imediata contra todas as doenças genéticas hereditárias.", "C": "Incompatibilidade sanguínea perpétua com o leite materno.", "D": "Eliminação de todos os ossos do corpo da criança.", "E": "A capacidade de respirar debaixo d'água no primeiro ano."}, "resposta_correta": "A", "justificativa": "A IgG é a única classe de imunoglobulina humana capaz de transpor a barreira placentária sinciciotrofoblástica via transcitose mediada pelo receptor FcRn, conferindo repertório humoral protetor transferido passivamente da mãe para proteger o neonato contra infecções nos primeiros 6 meses pós-parto.", "possui_imagem": false},
  {"id": 188, "uid": "CIEN-8-188", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 18: Reprodução Humana, Sexualidade e Prevenção de ISTs", "tema": "Autonomia, Consentimento e o Estatuto da Criança e do Adolescente (ECA)", "dificuldade": "Difícil", "enunciado": "No ordenamento jurídico brasileiro (Estatuto da Criança e do Adolescente - ECA e Código Penal), a legislação estabelece que atos sexuais envolvendo menores de 14 anos configuram crime incondicionado de Estupro de Vulnerável, independentemente de haver consentimento aparente da vítima ou autorização de familiares. O fundamento ético e biológico protetor dessa legislação baseia-se no princípio de que:", "alternativas": {"A": "Crianças e adolescentes menores de 14 anos ainda não possuem maturidade biológica, emocional, cognitiva e psíquica plenamente desenvolvida para discernir com autonomia e expressar consentimento sexual genuíno e livre de assimetria de poder ou coerção de adultos.", "B": "O corpo humano não possui neurônios em funcionamento antes dos 18 anos.", "C": "Apenas juízes de direito têm permissão para namorar na juventude.", "D": "A lei visa proibir o casamento de pessoas idosas no país.", "E": "O ECA foi criado apenas para proibir as escolas de ensinarem ciências."}, "resposta_correta": "A", "justificativa": "O instituto jurídico da vulnerabilidade absoluta pré-adolescente (<14 anos) reconhece a assimetria incontornável de desenvolvimento neurobiológico e psicossocial: a imaturidade do córtex pré-frontal e a fragilidade emocional impedem o consentimento informado pleno, impondo dever estatal absoluto de proteção integral contra abuso e exploração sexual.", "possui_imagem": false},
  {"id": 189, "uid": "CIEN-8-189", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Diferença entre Tempo e Clima", "dificuldade": "Fácil", "enunciado": "É muito comum as pessoas usarem as palavras 'tempo' e 'clima' como se fossem a mesma coisa. No entanto, em meteorologia, a diferença correta entre esses dois conceitos é:", "alternativas": {"A": "Tempo é o clima que acontece apenas no verão; clima é o que acontece no inverno.", "B": "Tempo é o estado passageiro e momentâneo da atmosfera em um determinado dia e local (ex: 'hoje está chovendo e frio em São Paulo'); clima é o padrão médio das condições atmosféricas observado ao longo de muitos anos (pelo menos 30 anos) em uma região.", "C": "Tempo refere-se exclusivamente à temperatura da água do mar; clima refere-se à altitude das montanhas.", "D": "Tempo é medido em quilômetros por hora e clima é medido em graus Celsius.", "E": "Tempo é previsto por satélites e clima nunca pode ser estudado pela ciência."}, "resposta_correta": "B", "justificativa": "O tempo meteorológico reflete o estado instantâneo da troposfera (dinâmico e mutável em horas); o clima é a caracterização estatística das médias e extremos meteorológicos ao longo de séries históricas de no mínimo 30 anos (normal climatológica).", "possui_imagem": true},
  {"id": 190, "uid": "CIEN-8-190", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Instrumentos Meteorológicos: Pluviômetro", "dificuldade": "Fácil", "enunciado": "Quando os telejornais informam que 'choveu 50 milímetros (mm) na cidade durante a madrugada', o instrumento meteorológico utilizado para medir essa quantidade de chuva acumulada é o:", "alternativas": {"A": "Termômetro.", "B": "Pluviômetro.", "C": "Anemômetro.", "D": "Barômetro.", "E": "Higrômetro."}, "resposta_correta": "B", "justificativa": "O pluviômetro é o aparelho em forma de funil coletor calibrado que mede a lâmina de água precipitada por unidade de área (1 mm de chuva equivale a 1 litro de água por metro quadrado de superfície plana).", "possui_imagem": true},
  {"id": 191, "uid": "CIEN-8-191", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Instrumentos Meteorológicos: Barômetro", "dificuldade": "Fácil", "enunciado": "Em uma estação meteorológica, o instrumento utilizado para medir a pressão exercida pelo peso da camada de ar da atmosfera sobre a superfície da Terra é o:", "alternativas": {"A": "Anemômetro.", "B": "Barômetro.", "C": "Pluviômetro.", "D": "Higrômetro.", "E": "Catavento."}, "resposta_correta": "B", "justificativa": "O barômetro (como o barômetro de mercúrio de Torricelli ou o aneroide de cápsula metálica) mede a pressão atmosférica, habitualmente expressa em hectopascais (hPa) ou milímetros de mercúrio (mmHg).", "possui_imagem": true},
  {"id": 192, "uid": "CIEN-8-192", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Instrumentos Meteorológicos: Anemômetro e Biruta", "dificuldade": "Fácil", "enunciado": "Para medir a velocidade do vento em quilômetros por hora e identificar a direção de onde o vento está soprando (Norte, Sul, Leste, Oeste), os meteorologistas utilizam, respectivamente:", "alternativas": {"A": "O barômetro e o pluviômetro.", "B": "O anemômetro (de conchas giratórias) e a biruta (ou catavento).", "C": "O termômetro e o higrômetro.", "D": "O sonar e o microscópio.", "E": "O sismógrafo e o gnômon."}, "resposta_correta": "B", "justificativa": "O anemômetro (com conchas hemisféricas giratórias) mede a velocidade cinemática do vento; a biruta (cone de tecido em aeroportos) e o catavento apontam a direção azimutal de proveniência da massa de ar.", "possui_imagem": true},
  {"id": 193, "uid": "CIEN-8-193", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Instrumentos Meteorológicos: Higrômetro", "dificuldade": "Fácil", "enunciado": "Em dias de inverno com ar muito seco no Brasil central, a Defesa Civil emite alertas quando a umidade relativa do ar cai para níveis críticos abaixo de 20% ou 30%. O instrumento que mede a umidade do ar é o:", "alternativas": {"A": "Pluviômetro.", "B": "Higrômetro (ou psicrômetro).", "C": "Anemômetro.", "D": "Barômetro de mercúrio.", "E": "Telescópio meteorológico."}, "resposta_correta": "B", "justificativa": "O higrômetro afere o teor de vapor d'água presente no ar atmosférico em relação à capacidade máxima de saturação na mesma temperatura, expressando a umidade relativa percentual (% UR).", "possui_imagem": true},
  {"id": 194, "uid": "CIEN-8-194", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Pressão Atmosférica e o Tempo: Alta vs. Baixa Pressão", "dificuldade": "Fácil", "enunciado": "Ao acompanhar mapas meteorológicos, observam-se centros de Alta Pressão (A) e centros de Baixa Pressão (B). De forma geral, centros de baixa pressão atmosférica estão associados a:", "alternativas": {"A": "Tempo firme, céu totalmente azul e ausência absoluta de nuvens.", "B": "Subida de ar quente e úmido que se resfria, formando nuvens densas, instabilidade e probabilidade de chuvas e tempestades.", "C": "Congelamento imediato de toda a água da cidade.", "D": "Parada definitiva de todos os ventos da região.", "E": "Secas severas de deserto com sol forte."}, "resposta_correta": "B", "justificativa": "Centros de baixa pressão (ciclones) provocam convergência e ascensão de ar; ao subir, o ar expande-se e resfria, condensando o vapor d'água em nuvens de chuva. Áreas de alta pressão (anticiclones) apresentam ar descendente subsidente, inibindo nuvens e trazendo tempo estável e seco.", "possui_imagem": true},
  {"id": 195, "uid": "CIEN-8-195", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Fatores Climáticos: Latitude e Temperatura", "dificuldade": "Fácil", "enunciado": "De maneira geral, quanto mais nos afastamos da Linha do Equador em direção aos polos terrestres (isto é, quanto maior a latitude geográfica), a temperatura média anual tende a:", "alternativas": {"A": "Aumentar continuamente, tornando os polos os locais mais quentes da Terra.", "B": "Diminuir progressivamente, pois os raios solares incidem com maior inclinação (oblíquos) e espalham sua energia por uma área maior de superfície.", "C": "Permanecer rigorosamente a mesma em todos os continentes.", "D": "Dobrar de valor a cada quilômetro viajado.", "E": "Chegar a 100 ºC em todos os invernos."}, "resposta_correta": "B", "justificativa": "A esfericidade da Terra dita a variação latitudinal de insolação: no equador (baixas latitudes), raios incidem quase perpendiculares concentrando energia; em altas latitudes polares, raios oblíquos e espessas colunas atmosféricas reduzem drasticamente o calor recebido.", "possui_imagem": true},
  {"id": 196, "uid": "CIEN-8-196", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Fatores Climáticos: Altitude e Temperatura", "dificuldade": "Fácil", "enunciado": "Ao subir uma serra ou viajar para cidades de grande altitude como Campos do Jordão (SP) ou La Paz (Bolívia), percebe-se que a temperatura do ar é consideravelmente mais fria do que no litoral ao nível do mar. Isso acontece porque, em altitudes mais elevadas:", "alternativas": {"A": "A gravidade é muito forte e esmaga as moléculas de calor.", "B": "A atmosfera é mais rarefeita (menor pressão e menor densidade de gases), retendo menos calor irradiado pelo solo (gradiente térmico vertical decrescente).", "C": "O Sol fica mais longe da Terra nas montanhas.", "D": "As montanhas são feitas de gelo marinho puro.", "E": "O vento apaga o fogo do Sol nas altitudes elevadas."}, "resposta_correta": "B", "justificativa": "A troposfera é aquecida de baixo para cima pelo calor irradiado pela superfície terrestre (radiação infravermelha telúrica). Em maior altitude, o ar é rarefeito (menor pressão parcial de gases de efeito estufa), diminuindo a retenção térmica (~0,6 ºC a menos a cada 100 m de subida).", "possui_imagem": true},
  {"id": 197, "uid": "CIEN-8-197", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Maritimidade e Continentalidade: Amplitude Térmica", "dificuldade": "Fácil", "enunciado": "A água do mar demora muito mais tempo para esquentar e para esfriar do que o solo seco de rochas e areia (alto calor específico da água). Por essa razão, cidades litorâneas influenciadas pela 'maritimidade' apresentam:", "alternativas": {"A": "Invernos com temperaturas de -50 ºC e verões de 80 ºC todos os anos.", "B": "Menor amplitude térmica (pequena variação de temperatura entre o dia e a noite e entre o verão e o inverno) em comparação com cidades no interior dos continentes.", "C": "Falta total de vento durante todo o ano.", "D": "Ausência de chuvas em todas as estações.", "E": "Clima idêntico ao do centro de desertos rochosos."}, "resposta_correta": "B", "justificativa": "O elevado calor específico da água (1 cal/g.ºC contra ~0,2 cal/g.ºC das rochas) atua como um regulador térmico natural em regiões sob influência da maritimidade, amortecendo picos térmicos diurnos e sazonais e gerando baixas amplitudes térmicas.", "possui_imagem": true},
  {"id": 198, "uid": "CIEN-8-198", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Satélites Meteorológicos", "dificuldade": "Fácil", "enunciado": "As imagens em movimento de nuvens e frentes frias exibidas na televisão nos boletins de previsão do tempo são obtidas por satélites meteorológicos posicionados no espaço. A grande vantagem do uso de satélites na meteorologia é:", "alternativas": {"A": "Modificar o clima e fazer chover onde os agricultores pedem.", "B": "Monitorar em tempo real a formação de tempestades, ciclones, massas de ar e queimadas em escala planetária contínua, permitindo emitir alertas com antecedência.", "C": "Destruir nuvens de tempestade com raios laser espaciais.", "D": "Medir a temperatura de cada árvore da floresta individualmente.", "E": "Prever o tempo com precisão absoluta para os próximos dez anos."}, "resposta_correta": "B", "justificativa": "Satélites meteorológicos em órbitas geoestacionárias (como o GOES) e polares captam imagens em canais do espectro visível, infravermelho térmico e vapor d'água a cada poucos minutos, rastreando a ciclogênese e evolução de sistemas convectivos globais.", "possui_imagem": true},
  {"id": 199, "uid": "CIEN-8-199", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "O Radar Meteorológico", "dificuldade": "Fácil", "enunciado": "Diferente dos satélites que olham a Terra do espaço de cima para baixo, os radares meteorológicos instalados no solo emitem pulsos de micro-ondas que atingem as nuvens ao redor. O radar meteorológico permite identificar com alta precisão:", "alternativas": {"A": "A quantidade de peixes que nadam nos rios sob a chuva.", "B": "A localização exata, a intensidade da precipitação e o deslocamento de tempestades de chuva forte, granizo e vendavais em um raio de até centenas de quilômetros ao redor da estação.", "C": "A cor das roupas que as pessoas usam nas ruas.", "D": "A profundidade do centro da Terra sob o radar.", "E": "A velocidade de rotação da Lua ao redor do Sol."}, "resposta_correta": "B", "justificativa": "O radar meteorológico emite ondas eletromagnéticas que são retroespalhadas por hidrometeoros (gotas de chuva, granizo, neve); medindo a refletividade e o deslocamento Doppler, ele quantifica taxas de chuva e velocidade radial de vendavais em curtíssimo prazo (nowcasting).", "possui_imagem": true},
  {"id": 200, "uid": "CIEN-8-200", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Conceito de Massa de Ar", "dificuldade": "Fácil", "enunciado": "Em meteorologia, uma 'massa de ar' é uma imensa porção da atmosfera com milhares de quilômetros de extensão horizontal que apresenta características relativamente homogêneas de:", "alternativas": {"A": "Salinidade e cor de fumaça.", "B": "Temperatura e umidade adquiridas da região sobre a qual ela se formou.", "C": "Velocidade constante de 1.000 km/h pelo solo.", "D": "Camadas de solo fértil em suspensão.", "E": "Gases de nitrogênio congelados."}, "resposta_correta": "B", "justificativa": "Massas de ar adquirem propriedades físicas térmicas e higrométricas uniformes ao permanecerem estacionadas sobre vastas superfícies homogêneas (regiões de fonte, como oceanos tropicais ou planícies polares), deslocando-se posteriormente pela circulação geral da atmosfera.", "possui_imagem": true},
  {"id": 201, "uid": "CIEN-8-201", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "A Massa Polar Atlântica (mPa) no Brasil", "dificuldade": "Fácil", "enunciado": "Quando uma frente fria avança pelo território brasileiro durante o outono e o inverno, ela é impulsionada pela entrada da Massa Polar Atlântica (mPa). As características climáticas típicas dessa massa de ar ao atingir o Sul e o Sudeste são:", "alternativas": {"A": "Calor tórrido de 45 ºC e tempo completamente seco sem nuvens.", "B": "Queda acentuada da temperatura (frio), aumento da nebulosidade com chuvas e risco de geadas nas serras e friagem na Amazônia ocidental.", "C": "Ventos quentes do deserto que evaporam todos os rios.", "D": "Ausência total de vento e céu cor de ouro.", "E": "Aumento repentino da pressão atmosférica para dez atmosferas."}, "resposta_correta": "B", "justificativa": "A Massa Polar Atlântica (mPa) origina-se nas altas latitudes do Atlântico Sul: é fria e úmida em sua gênese; ao avançar pelo continente, sua borda frontal colide com massas tropicais gerando frentes frias com chuvas seguidas por ar frio e seco anticiclônico com geadas.", "possui_imagem": true},
  {"id": 202, "uid": "CIEN-8-202", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Os 'Rios Voadores' da Amazônia", "dificuldade": "Fácil", "enunciado": "A Floresta Amazônica desempenha um papel vital no regime de chuvas de grande parte da América do Sul através dos chamados 'rios voadores'. Esse fenômeno consiste em:", "alternativas": {"A": "Cachoeiras de água líquida que caem do céu direto no mar.", "B": "Imensos fluxos aéreos de vapor de água produzidos pela evapotranspiração massiva das árvores da floresta, que são transportados pelos ventos alísios até o Centro-Oeste, Sudeste e Sul do Brasil, alimentando as chuvas que abastecem represas e a agricultura.", "C": "Rios com peixes voadores que voam entre os galhos da mata.", "D": "Nuvens de fumaça tóxica geradas por vulcões da cordilheira.", "E": "Tempestades de poeira amarela que viajam pelo litoral."}, "resposta_correta": "B", "justificativa": "A densa cobertura florestal amazônica bombeia diariamente bilhões de litros de água para a atmosfera através da evapotranspiração vegetal; esses rios voadores de vapor viajam canalizados pela barreira dos Andes até o Centro-Sul brasileiro, nutrindo bacias hídricas vitais.", "possui_imagem": true},
  {"id": 203, "uid": "CIEN-8-203", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "O Fenômeno El Niño: O Que É", "dificuldade": "Fácil", "enunciado": "O El Niño é um fenômeno climático oceânico-atmosférico de grande escala caracterizado por:", "alternativas": {"A": "O congelamento total do Oceano Atlântico Norte no verão.", "B": "O aquecimento anormal e prolongado das águas superficiais do Oceano Pacífico Equatorial, alterando os padrões de vento e circulação atmosférica em todo o planeta.", "C": "A queda da temperatura do sol em dias de eclipse lunar.", "D": "A erupção simultânea de 50 vulcões submarinos no Brasil.", "E": "A secagem completa do Rio Amazonas em menos de um mês."}, "resposta_correta": "B", "justificativa": "O El Niño (fase quente do ENOS) consiste na anomalia térmica positiva das águas do Pacífico Centro-Leste Equatorial, associada ao enfraquecimento dos ventos alísios, desestabilizando padrões pluviométricos e de temperatura em escala global.", "possui_imagem": false},
  {"id": 204, "uid": "CIEN-8-204", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Impactos do El Niño no Clima do Brasil", "dificuldade": "Fácil", "enunciado": "Durante eventos clássicos de El Niño, o Brasil costuma registrar impactos meteorológicos típicos e contrastantes em diferentes regiões, caracterizados por:", "alternativas": {"A": "Secas severas no Sul e enchentes gigantescas no Nordeste.", "B": "Aumento expressivo das chuvas e risco de enchentes severas na Região Sul, acompanhado por secas prolongadas e altas temperaturas nas Regiões Norte e Nordeste.", "C": "Neve contínua na cidade de Salvador durante o verão.", "D": "Clima rigorosamente igual e uniforme em todos os 26 estados.", "E": "Ausência de ventos em todo o litoral brasileiro."}, "resposta_correta": "B", "justificativa": "O El Niño altera o padrão de circulação de Walker e a corrente de jato subtropical: bloqueia sistemas frontais sobre o Sul do Brasil (causando precipitações torrenciais persistentes) e intensifica a subsidência de ar seco sobre o Norte e semiárido Nordestino (secas e queimadas).", "possui_imagem": false},
  {"id": 205, "uid": "CIEN-8-205", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "O Fenômeno La Niña: O Que É", "dificuldade": "Fácil", "enunciado": "A La Niña representa a fase oposta do fenômeno El Niño. Ela é caracterizada por:", "alternativas": {"A": "O aquecimento de todos os oceanos do mundo em 10 graus Celsius.", "B": "O resfriamento anormal das águas superficiais do Oceano Pacífico Equatorial e a intensificação dos ventos alísios.", "C": "A paralisação das marés de água salgada no litoral da Bahia.", "D": "A transformação de água doce em petróleo puro no subsolo.", "E": "Tempestades de neve semanais na Floresta Amazônica."}, "resposta_correta": "B", "justificativa": "A La Niña (fase fria do ENOS) caracteriza-se por anomalias térmicas negativas (águas superficiais mais frias que a média histórica) no Pacífico Equatorial, com fortalecimento dos ventos alísios que empurram águas quentes para a Oceania e forçam ressurgência fria no leste.", "possui_imagem": false},
  {"id": 206, "uid": "CIEN-8-206", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Chuva Convectiva (Chuva de Verão)", "dificuldade": "Fácil", "enunciado": "Aquelas típicas 'pancadas de chuva de verão' que ocorrem no final da tarde em cidades brasileiras — com nuvens escuras de grande desenvolvimento vertical (Cumulonimbus), raios, trovões e chuva forte de curta duração — são classificadas como:", "alternativas": {"A": "Chuvas orográficas de serra.", "B": "Chuvas convectivas (ou de convecção térmica).", "C": "Chuvas frontais de inverno polar.", "D": "Chuvas cósmicas lunares.", "E": "Chuvas vulcânicas de cinzas."}, "resposta_correta": "B", "justificativa": "Chuvas convectivas decorrem do intenso aquecimento do solo e do ar em dias quentes; o ar aquecido ascende velozmente em fortes correntes convectivas térmicas, condensa-se e forma nuvens Cumulonimbus com temporais vespertinos localizados.", "possui_imagem": false},
  {"id": 207, "uid": "CIEN-8-207", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Chuva Orográfica (Chuva de Relevo)", "dificuldade": "Fácil", "enunciado": "Quando uma massa de ar úmido vinda do oceano encontra uma barreira de montanhas (como a Serra do Mar no litoral de São Paulo e Rio de Janeiro), ela é forçada a subir a encosta, resfria-se e condensa-se, provocando chuvas torrenciais na encosta voltada para o mar. Esse tipo de chuva é denominado:", "alternativas": {"A": "Chuva de convecção de verão.", "B": "Chuva orográfica (ou chuva de relevo).", "C": "Chuva ácida de poluição pura.", "D": "Chuva de granizo sem nuvens.", "E": "Chuva de meteoros atmosféricos."}, "resposta_correta": "B", "justificativa": "A chuva orográfica ocorre quando uma barreira topográfica (escarpa de serra) força a ascensão adiabática mecânica de massas de ar úmido; no lado de barlavento, a condensação satura o ar gerando chuvas intensas.", "possui_imagem": false},
  {"id": 208, "uid": "CIEN-8-208", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Geada e Ponto de Orvalho", "dificuldade": "Fácil", "enunciado": "Em madrugadas limpas e sem vento de inverno no Sul e Sudeste do Brasil, a temperatura junto ao solo cai abaixo de 0 ºC, fazendo o vapor de água do ar sublimar diretamente sobre a vegetação formando cristais de gelo esbranquiçados. Esse fenômeno é a:", "alternativas": {"A": "Granizo de tempestade de verão.", "B": "Geada (geada branca).", "C": "Chuva orográfica noturna.", "D": "Névoa seca poluente.", "E": "Inversão térmica do asfalto."}, "resposta_correta": "B", "justificativa": "A geada branca ocorre quando o ar úmido próximo ao solo atinge a temperatura do ponto de orvalho abaixo de zero grau Celsius (ponto de congelamento), depositando cristais de gelo diretamente sobre folhas e gramíneas por desublimação.", "possui_imagem": false},
  {"id": 209, "uid": "CIEN-8-209", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Modelos Numéricos de Previsão em Supercomputadores", "dificuldade": "Médio", "enunciado": "A meteorologia moderna utiliza supercomputadores de altíssimo desempenho (como os operados pelo CPTEC/INPE no Brasil) para rodar modelos matemáticos numéricos de previsão do tempo. Esses supercomputadores funcionam resolvendo equações que descrevem:", "alternativas": {"A": "A astrologia e o movimento de signos zodiacais no céu.", "B": "Leis da física clássica (conservação de massa, leis do movimento de Newton para fluidos e termodinâmica de transferência de calor) aplicadas a uma grade tridimensional que divide a atmosfera de todo o planeta em milhares de blocos matemáticos.", "C": "O comportamento de formigas e pássaros em florestas tropicais.", "D": "A taxa de crescimento de plantas ornamentais em estufas urbanas.", "E": "O preço do petróleo na bolsa de valores internacional."}, "resposta_correta": "B", "justificativa": "A previsão numérica de tempo (NWP) resolve as equações primitivas da hidrodinâmica geofísica (Navier-Stokes para fluidos rotacionais, equação hidrostática, equação da continuidade e conservação de energia) projetadas em malhas de latitude, longitude e altitude planetárias.", "possui_imagem": false},
  {"id": 210, "uid": "CIEN-8-210", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Barlavento vs. Sotavento e Sombra de Chuva", "dificuldade": "Médio", "enunciado": "Ao analisar uma cadeia de montanhas costeira atingida por ventos oceânicos úmidos, nota-se que o lado voltado para o vento e para o mar (barlavento) é extremamente úmido e coberto por florestas exuberantes, enquanto o lado oposto protegido da montanha (sotavento) é seco e árido (fenômeno de 'sombra de chuva'). A aridez do lado de sotavento ocorre porque:", "alternativas": {"A": "A montanha impede que a luz do sol chegue ao outro lado durante o dia.", "B": "Após subir e descarregar sua umidade na encosta de barlavento, a massa de ar desce pelo lado de sotavento, sofrendo compressão adiabática e aquecimento, tornando-se extremamente seca e impedindo a formação de nuvens de chuva.", "C": "O solo de sotavento é feito de rochas venenosas que sugam água do ar.", "D": "Os animais da floresta bebem toda a chuva no topo da montanha.", "E": "A gravidade no sotavento empurra as nuvens para o espaço sideral."}, "resposta_correta": "B", "justificativa": "O efeito Föhn/sombra de chuva: ao transpor a cumeeira da montanha desprovido de umidade, o ar descende adiabaticamente pela vertente de sotavento, sofrendo compressão que eleva sua temperatura em ~1 ºC a cada 100 m e reduz sua umidade relativa, gerando climas semiáridos locais.", "possui_imagem": false},
  {"id": 211, "uid": "CIEN-8-211", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "A Massa Tropical Atlântica (mTa) e a Massa Equatorial Continental (mEc)", "dificuldade": "Médio", "enunciado": "O clima brasileiro é moldado pelo avanço e recuo de massas de ar com origens contrastantes. Enquanto a Massa Tropical Atlântica (mTa) é quente e úmida e atua fortemente na faixa litorânea oriental, a Massa Equatorial Continental (mEc), formada sobre a Bacia Amazônica, apresenta uma característica ímpar em relação à maioria das massas continentais do mundo, que é:", "alternativas": {"A": "Ser extremamente fria e seca como a massa do Polo Sul.", "B": "Ser quente e MUITO ÚMIDA, devido à colossal evapotranspiração contínua gerada pela densa Floresta Amazônica e sua vasta rede hidrográfica.", "C": "Ser formada exclusivamente por cinzas de queimadas agrícolas.", "D": "Atuar apenas durante a madrugada nos estados do Sul.", "E": "Não possuir oxigênio nem vapor de água em sua composição."}, "resposta_correta": "B", "justificativa": "Diferente de massas continentais típicas do planeta (que costumam ser áridas, como sobre o Saara), a mEc amazônica é hiperúmida e quente (pseudomarítima) sustentada pelo bombeamento transpiratório da copa florestal, gerando instabilidade convectiva no verão de todo o Brasil.", "possui_imagem": false},
  {"id": 212, "uid": "CIEN-8-212", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Efeito Coriolis e a Circulação dos Ventos", "dificuldade": "Médio", "enunciado": "O ar atmosférico sempre tende a se mover de zonas de alta pressão para zonas de baixa pressão gerando os ventos. No entanto, os ventos não viajam em linha reta perpendicular sobre os mapas: eles sofrem desvio aparente para a direita no Hemisfério Norte e para a esquerda no Hemisfério Sul. Essa deflexão inercial em um referencial em rotação é causada pelo:", "alternativas": {"A": "Efeito Joule dos fios elétricos urbanos.", "B": "Efeito Coriolis, provocado pelo movimento contínuo de rotação da Terra em torno de seu próprio eixo.", "C": "Efeito estufa polar reverso.", "D": "Magnetismo do centro do núcleo de ferro sólido.", "E": "Atrito das árvores com o vento oceânico."}, "resposta_correta": "B", "justificativa": "A força aparente de Coriolis decorre da rotação planetária: massas de ar em movimento conservam seu momento angular; no Hemisfério Sul, a aceleração desvia trajetórias à esquerda do vetor velocidade, fazendo ciclones girarem no sentido horário e anticiclones no sentido anti-horário.", "possui_imagem": false},
  {"id": 213, "uid": "CIEN-8-213", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Ciclones, Tufões e Furacões: A Mesma Física", "dificuldade": "Médio", "enunciado": "Noticiários internacionais usam os termos 'furacão' no Oceano Atlântico Norte e Caribe, 'tufão' no Oceano Pacífico Ocidental (Ásia) e 'ciclone tropical' no Oceano Índico e Pacífico Sul. Do ponto de vista da física e da meteorologia, esses três fenômenos são:", "alternativas": {"A": "Doenças infecciosas causadas por bactérias de tempestade.", "B": "Rigorosamente o mesmo tipo de fenômeno atmosférico (um ciclone tropical intenso com ventos superiores a 119 km/h alimentado pelo calor e vapor de águas oceânicas quentes), mudando apenas a denominação regional de acordo com a bacia oceânica onde se formam.", "C": "Terremotos submarinos que ocorrem sem nuvens e sem vento.", "D": "Nuvens de fumaça geradas pela colisão de meteoros espaciais.", "E": "Eventos puramente fictícios criados para filmes de cinema."}, "resposta_correta": "B", "justificativa": "Furacão, tufão e ciclone tropical são designações geográficas sinônimas para sistemas ciclônicos de núcleo quente de baixa pressão barométrica alimentados por calor latente liberado pela condensação de vapor de águas oceânicas tropicais com temperatura ≥ 26,5 ºC.", "possui_imagem": false},
  {"id": 214, "uid": "CIEN-8-214", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Por que Furacões Tropicais são Raros no Atlântico Sul Brasileiro?", "dificuldade": "Médio", "enunciado": "Enquanto o Caribe e o Golfo do México sofrem anualmente com dezenas de furacões devastadores, o litoral do Brasil (Atlântico Sul) é historicamente quase isento de furacões tropicais intensos (com a rara exceção do Furacão Catarina em 2004). Os fatores meteorológicos que inibem a formação de furacões no Atlântico Sul são:", "alternativas": {"A": "A presença de montanhas de ferro na costa brasileira que atraem os ventos.", "B": "A forte tesoura de vento vertical (cisalhamento de vento) na troposfera, temperaturas oceânicas médias ligeiramente abaixo do limiar ótimo e a ausência de perturbações precursoras ativas (como a Zona de Convergência Intertropical que se posiciona ao norte).", "C": "A água do mar brasileiro ser doce e impedir tempestades.", "D": "A proibição do uso de sismógrafos no litoral de Santa Catarina.", "E": "O fato de a rotação da Terra parar quando passa pelo Brasil."}, "resposta_correta": "B", "justificativa": "O alto cisalhamento vertical do vento (vertical wind shear) no Atlântico Sul desorganiza e dissipa a estrutura simétrica vertical de convecção profunda necessária para ciclogênese tropical; somam-se a isso temperaturas superficiais do mar (TSM) menos persistentes acima de 27 ºC.", "possui_imagem": false},
  {"id": 215, "uid": "CIEN-8-215", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Inversão Térmica: Causas e Danos à Saúde", "dificuldade": "Médio", "enunciado": "Durante madrugadas frias de outono e inverno em metrópoles como São Paulo, Santiago e Teerã, a perda rápida de calor pelo solo gera o fenômeno da inversão térmica. O grande problema de saúde pública acarretado pela inversão térmica reside no fato de que:", "alternativas": {"A": "O chão esquenta tanto que derrete os pneus dos ônibus urbanos.", "B": "A camada de ar frio aprisionada no solo fica bloqueada por uma camada de ar mais quente acima dela, impedindo as correntes de convecção verticais e concentrando gases tóxicos e material particulado na altura da respiração da população, disparando crises respiratórias.", "C": "As pessoas perdem a capacidade de ouvir sons com o frio.", "D": "O oxigênio atmosférico se transforma em gás carbônico em minutos.", "E": "A água da chuva vira gasolina pura que queima os telhados."}, "resposta_correta": "B", "justificativa": "A quebra do gradiente adiabático normal da troposfera (ar frio mais denso estacionado sob ar quente mais leve) elimina a turbulência e as correntes ascendentes de dispersão; poluentes veiculares (CO, NOx, PM2.5) acumulam-se em níveis críticos rente ao solo, agravando asma e bronquites.", "possui_imagem": false},
  {"id": 216, "uid": "CIEN-8-216", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Corrente Marítima de Humboldt e o Deserto do Atacama", "dificuldade": "Médio", "enunciado": "O Deserto do Atacama, no norte do Chile, é considerado o deserto não polar mais árido do planeta, com regiões onde nunca se registrou chuva em séculos. A existência desse deserto hiperárido no litoral do Oceano Pacífico é explicada pela ação conjunta de dois fatores geográficos:", "alternativas": {"A": "O calor de vulcões que ferve a chuva antes de tocar o solo e a falta de sal no mar.", "B": "A fria Corrente Marítima de Humboldt (que resfria o ar rente ao mar e inibe a evaporação e convecção de chuvas) somada à barreira física monumental da Cordilheira dos Andes a leste (que bloqueia toda a umidade vinda da Amazônia pelo efeito de sombra de chuva).", "C": "A proximidade com o Polo Norte e o vento solar estelar contínuo.", "D": "O fato de o Atacama ficar a 10.000 metros de altitude abaixo do mar.", "E": "A rotação da Terra girar no sentido anti-horário apenas no Chile."}, "resposta_correta": "B", "justificativa": "A fria Corrente oceânica de Humboldt estabiliza termicamente a camada inferior de ar (inversão térmica marinha perene com neblinas costeiras/camanchaca sem chuvas), enquanto a muralha orográfica dos Andes barra completamente o transporte de umidade amazônica de leste.", "possui_imagem": false},
  {"id": 217, "uid": "CIEN-8-217", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Zona de Convergência do Atlântico Sul (ZCAS)", "dificuldade": "Médio", "enunciado": "No verão brasileiro, a previsão do tempo frequentemente destaca a atuação da 'Zona de Convergência do Atlântico Sul' (ZCAS). A ZCAS é um importante padrão meteorológico de grande escala que se caracteriza por:", "alternativas": {"A": "Uma onda de frio polar com geadas no estado do Maranhão.", "B": "Uma faixa persistente e alongada de nebulosidade e chuvas contínuas orientada no sentido noroeste-sudeste (da Amazônia até o Sudeste e Atlântico), que pode durar dias provocando chuvas torrenciais, cheias de rios e deslizamentos de encostas.", "C": "A parada completa da evaporação na Floresta Amazônica por meses.", "D": "A formação de tufões tropicais em Brasília e Goiás.", "E": "Um período de seca de 60 dias sem nenhuma nuvem no Rio de Janeiro."}, "resposta_correta": "B", "justificativa": "A ZCAS é a principal feição meteorológica de escala sinótica do verão sul-americano: um canal persistente de fluxo de umidade (low-level jet) acoplado à circulação amazônica e sistemas frontais no oceano, gerando episódios severos de chuva contínua no Sudeste e Centro-Oeste.", "possui_imagem": false},
  {"id": 218, "uid": "CIEN-8-218", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Nevoeiro e Neblina: Diferença para Nuvens Comuns", "dificuldade": "Médio", "enunciado": "Ao dirigir por rodovias de serra pela manhã, motoristas frequentemente enfrentam trechos com visibilidade horizontal reduzida a menos de 1.000 metros devido a nevoeiro ou neblina espessa. Do ponto de vista da física da atmosfera, um nevoeiro é tecnicamente:", "alternativas": {"A": "Fumaça tóxica liberada pelo asfalto quente da rodovia.", "B": "Uma nuvem do tipo estrato formada em contato direto com a superfície do solo quando o ar úmido é resfriado até atingir seu ponto de saturação (ponto de orvalho), condensando o vapor em gotículas de água líquida microscópicas em suspensão no ar.", "C": "Gás oxigênio congelado caindo do topo da estratosfera.", "D": "Vapor de água superaquecido que queima a pele ao caminhar.", "E": "Pó de calcário soprado de mineradoras distantes."}, "resposta_correta": "B", "justificativa": "Nevoeiro é essencialmente uma nuvem cuja base toca o solo. Resfriamento radiativo noturno ou advecção de ar úmido sobre solo frio eleva a umidade relativa a 100%, induzindo nucleação e condensação do vapor sobre núcleos de condensação higroscópicos.", "possui_imagem": false},
  {"id": 219, "uid": "CIEN-8-219", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Ondas de Calor e Domos de Calor (Heat Domes)", "dificuldade": "Médio", "enunciado": "Em anos recentes, diversas partes do mundo (como a Europa, os Estados Unidos e o Centro-Sul do Brasil) têm sofrido com 'ondas de calor' extremas e recordes de temperatura causados por 'domos de calor'. Esse padrão meteorológico extremo instala-se quando:", "alternativas": {"A": "O Sol se aproxima fisicamente 1 milhão de quilômetros da Terra.", "B": "Um sistema de alta pressão atmosférica estagnado e persistente bloqueia a circulação e aprisiona o ar quente sobre uma região, comprimindo-o adiabaticamente para baixo e impedindo a entrada de frentes frias e a formação de chuvas amenizadoras por semanas.", "C": "Vulcões entram em erupção embaixo de todas as capitais do país.", "D": "A atmosfera perde toda a camada de ozônio em poucas horas.", "E": "A gravidade da Terra aumenta e atrai os raios de luz solar."}, "resposta_correta": "B", "justificativa": "Um domo de calor (heat dome) decorre de um bloqueio atmosférico em ômega de alta pressão troposférica: a subsidência contínua comprime e aquece adiabaticamente a massa de ar seco; céus claros sem nuvens maximizam a insolação diurna acumulada sem alívio noturno.", "possui_imagem": false},
  {"id": 220, "uid": "CIEN-8-220", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Albedo e Aquecimento da Superfície", "dificuldade": "Médio", "enunciado": "O termo físico 'albedo' representa a fração da radiação solar incidente que é refletida diretamente de volta para o espaço por uma determinada superfície sem ser absorvida na forma de calor. Superfícies de neve fresca e gelo polar possuem altíssimo albedo (cerca de 80% a 90% de reflexão), enquanto o asfalto escuro de cidades e a água do oceano possuem baixíssimo albedo (menos de 10% a 15%). Isso significa que as cidades com muito asfalto e concreto:", "alternativas": {"A": "Refletem quase toda a luz do sol e são mais frias que as florestas.", "B": "Absorvem a maior parte da energia solar incidente na forma de calor, contribuindo diretamente para o aquecimento acentuado da superfície e formação das 'ilhas de calor urbanas'.", "C": "Ficam no escuro completo durante os meses de verão.", "D": "Transformam a luz do sol em gelo marinho durante o dia.", "E": "Têm o mesmo clima de geleiras polares no meio da tarde."}, "resposta_correta": "B", "justificativa": "O albedo mede a refletividade da superfície (0 a 1). Superfícies escuras com baixo albedo absorvem mais de 85% dos fótons solares, convertendo-os em calor sensível e emitindo radiação infravermelha de onda longa à noite, intensificando as ilhas de calor urbanas.", "possui_imagem": false},
  {"id": 221, "uid": "CIEN-8-221", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Monções Asiáticas: Inversão Sazonal de Ventos", "dificuldade": "Médio", "enunciado": "O clima do Sul e Sudeste da Ásia (especialmente da Índia) é dominado pelo regime de monções. As monções de verão trazem meses ininterruptos de chuvas torrenciais inundando lavouras de arroz, enquanto as monções de inverno trazem seca severa. A causa motriz da alternância das monções é:", "alternativas": {"A": "A queima de carvão por fazendeiros indianos a cada seis meses.", "B": "O contraste térmico sazonal extremo entre o gigantesco continente asiático e o Oceano Índico: no verão o continente aquece muito mais rápido que o mar, gerando um imenso centro de baixa pressão que atrai ventos oceânicos hiperúmidos; no inverno o continente esfria e os ventos secos sopram da terra para o mar.", "C": "A atração gravitacional da Lua que muda de lado a cada solstício.", "D": "A colisão da Índia com a Europa que fecha o mar temporariamente.", "E": "A passagem de cometas perto da atmosfera terrestre."}, "resposta_correta": "B", "justificativa": "O sistema de monções é uma circulação de brisa gigante sazonal: no verão, o platô tibetano e o continente asiático aquecem-se, criando uma depressão térmica continental que suga ar oceânico saturado do Índico (Monção de Verão chuvosa); no inverno a circulação inverte-se (Monção de Inverno fria e seca).", "possui_imagem": false},
  {"id": 222, "uid": "CIEN-8-222", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "A Camada da Atmosfera Onde Ocorre o Clima: A Troposfera", "dificuldade": "Médio", "enunciado": "A atmosfera da Terra possui várias camadas sobrepostas (troposfera, estratosfera, mesosfera, termosfera e exosfera). Praticamente todos os fenômenos meteorológicos que vivenciamos diariamente (nuvens, chuvas, ventos, frentes frias, furacões e tempestades) ocorrem exclusivamente na camada mais baixa e densa da atmosfera, chamada:", "alternativas": {"A": "Termosfera superior com auroras boreais.", "B": "Troposfera (que vai da superfície até cerca de 12 a 16 km de altitude).", "C": "Mesosfera onde queimam os meteoros espaciais.", "D": "Exosfera onde orbitam os satélites geoestacionários.", "E": "Camada de ozônio pura sem gases respiráveis."}, "resposta_correta": "B", "justificativa": "A troposfera concentra cerca de 75% a 80% de toda a massa gasosa da atmosfera e quase 99% de todo o vapor de água planetário; é a única camada com convecção térmica turbulenta intensa e onde operam todos os ciclos hidrológicos do clima.", "possui_imagem": false},
  {"id": 223, "uid": "CIEN-8-223", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Efeito da Poluição por Queimadas: Material Particulado", "dificuldade": "Médio", "enunciado": "Durante a estação seca na Amazônia e no Pantanal, grandes queimadas florestais geram plumas de fumaça densa que cobrem estados inteiros do Brasil. Além de causar problemas respiratórios graves, o excesso de fuligem microscópica (aerossóis) no ar altera a microfísica das nuvens e:", "alternativas": {"A": "Faz chover dez vezes mais em todas as cidades da Amazônia.", "B": "Pode suprimir e inibir a formação de chuvas no curto prazo, pois divide o vapor de água entre uma quantidade excessiva de núcleos de condensação, gerando milhões de gotículas de água minúsculas demais para coalescer e crescer em gotas pesadas que caiam como chuva.", "C": "Transforma a água da chuva em leite de vaca doce.", "D": "Resfria a floresta a ponto de criar gelo nas árvores.", "E": "Faz com que o sol pare de emitir radiação luminosa."}, "resposta_correta": "B", "justificativa": "A fumaça florestal injeta altíssimas concentrações de núcleos de condensação de nuvens (CCN). O vapor d'água reparte-se em miríades de microgotículas com raio < 10 μm, incapazes de colidir e coalescer por gravidade, inibindo chuvas quentes e prolongando a estiagem.", "possui_imagem": false},
  {"id": 224, "uid": "CIEN-8-224", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Convecção Forçada vs. Livre e Granizo", "dificuldade": "Médio", "enunciado": "O granizo (pedras de gelo que caem durante tempestades severas de verão) forma-se no interior de nuvens Cumulonimbus de grande porte. A formação de pedras de granizo pesadas exige uma condição meteorológica extrema no interior da nuvem, que é:", "alternativas": {"A": "A presença de vento calmo e suave sem nenhuma movimentação de ar.", "B": "Correntes de vento ascendentes convectivas violentas (uplifts de mais de 100 km/h) que sustentam as pedras de gelo em suspensão no topo congelante da nuvem (onde a temperatura é inferior a -40 ºC), permitindo que camadas sucessivas de água líquida super-resfriada congelem ao redor do grão até que o peso vença a sustentação do vento e o granizo despenque.", "C": "A queima de carvão mineral dentro da nuvem a baixa altitude.", "D": "A passagem de aviões supersônicos que quebram o vapor d'água.", "E": "O resfriamento instantâneo do solo da cidade por geladeiras."}, "resposta_correta": "B", "justificativa": "Supercélulas e nuvens Cumulonimbus de topo penetrativo (superando 12 a 15 km de altitude) contêm correntes ascendentes de convecção violenta que sustentam embriões de gelo na zona de água super-resfriada; ciclos de ascensão e queda depositam camadas de gelo concêntricas até a queda do granizo.", "possui_imagem": false},
  {"id": 225, "uid": "CIEN-8-225", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Secura do Polígono das Secas no Nordeste: Fatores Dinâmicos", "dificuldade": "Médio", "enunciado": "O semiárido brasileiro (região do Polígono das Secas no Sertão nordestino) apresenta baixos índices pluviométricos anuais e longos períodos de estiagem. Entre os fatores de circulação geral que explicam a aridez dinâmica relativa dessa região tropical, destaca-se:", "alternativas": {"A": "O Sertão ficar a 5.000 metros de altitude abaixo do nível do mar.", "B": "A atuação de movimentos descendentes de ar (subsidência atmosférica) em grande escala associados à circulação de Hadley e Walker e à barreira orográfica do Planalto da Borborema (que retém parte da umidade litorânea no leste), inibindo a formação de nuvens de chuva convectiva no interior.", "C": "A ausência total de sol e calor no Nordeste durante o ano.", "D": "A queima contínua de petróleo natural no subsolo do sertão.", "E": "O fato de a água do mar do litoral nordestino ser doce."}, "resposta_correta": "B", "justificativa": "O semiárido nordestino sofre influência de mecanismos de subsidência de ar em grande escala (células de Hadley/Walker) que aquecem adiabaticamente a coluna troposférica e dissipam nuvens, potencializado pela orografia da Borborema que retém a umidade dos alísios de leste na Zona da Mata.", "possui_imagem": false},
  {"id": 226, "uid": "CIEN-8-226", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Sensação Térmica e Vento: O Efeito Wind Chill", "dificuldade": "Médio", "enunciado": "Em dias frios de inverno com termômetros marcando 10 ºC, se houver ventos fortes soprando a 50 km/h, uma pessoa na rua relata sentir um frio muito mais intenso do que se o ar estivesse calmo (sensação térmica inferior a 4 ºC). O efeito físico que explica essa sensação térmica reduzida pelo vento é:", "alternativas": {"A": "O vento diminuir a gravidade do corpo humano.", "B": "A convecção forçada acelerada pelo vento, que remove velozmente a fina camada de ar aquecido e parado que o calor do corpo humano mantém naturalmente ao redor da pele como isolante, aumentando drasticamente a taxa de perda de calor corporal para o ambiente.", "C": "O vento transformar o sangue das veias em gelo de nitrogênio.", "D": "O termômetro de mercúrio parar de funcionar quando bate vento.", "E": "A pessoa esquecer que está usando casaco de lã."}, "resposta_correta": "B", "justificativa": "O corpo humano aquece continuamente uma camada de ar estagnada rente à epiderme (camada limite térmica). O fluxo veloz de ar remove essa barreira por convecção forçada turbulenta e acelera a evaporação de umidade cutânea, maximizando o fluxo de calor retirado da derme (wind chill).", "possui_imagem": false},
  {"id": 227, "uid": "CIEN-8-227", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "O Papel do Ozônio Estratosférico: Filtro UV", "dificuldade": "Médio", "enunciado": "Na estratosfera terrestre (entre 20 e 35 km de altitude) encontra-se a Camada de Ozônio (O3). A função vital insubstituível dessa camada de gás para a vida animal e vegetal na superfície da Terra é:", "alternativas": {"A": "Fazer chover água mineral pura em todos os continentes.", "B": "Absorver a maior parte da radiação ultravioleta biologicamente nociva e cancerígena emitida pelo Sol (especialmente os raios UV-C e a maior parte do UV-B), protegendo o DNA das células vivas contra mutações e danos letais.", "C": "Fornecer oxigênio gasoso para os astronautas no espaço.", "D": "Resfriar o ar para que os aviões consigam voar na estratosfera.", "E": "Produzir vento que empurra as placas tectônicas da Terra."}, "resposta_correta": "B", "justificativa": "O ciclo fotoquímico de Chapman na estratosfera sintetiza e dissocia ozônio (O3) por fotólise contínua da radiação ultravioleta solar; essa absorção ressonante filtra 99% da radiação UV-C e a fração mais energética de UV-B, viabilizando a vida fora dos oceanos profundos.", "possui_imagem": false},
  {"id": 228, "uid": "CIEN-8-228", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Eventos Climáticos Extremos e o IPCC", "dificuldade": "Médio", "enunciado": "Os relatórios científicos do Painel Intergovernamental sobre Mudanças Climáticas (IPCC) da ONU apontam que o aquecimento global antropogênico não se limita a aumentar a temperatura média do planeta em 1 ºC ou 2 ºC, mas altera o regime dinâmico da atmosfera provocando:", "alternativas": {"A": "A extinção imediata de todos os peixes de água doce em 24 horas.", "B": "Aumento na frequência, intensidade, duração e abrangência geográfica de eventos meteorológicos extremos, como ondas de calor sem precedentes, secas severas prolongadas, tempestades de chuva torrencial e inundações catastróficas.", "C": "O desaparecimento total do inverno em todos os países do mundo.", "D": "A transformação das nuvens em combustível fóssil inflamável.", "E": "O congelamento do núcleo interno de ferro da Terra."}, "resposta_correta": "B", "justificativa": "A termodinâmica do aquecimento atmosférico segue a equação de Clausius-Clapeyron: a cada 1 ºC de aumento na temperatura global, a atmosfera retém ~7% mais vapor d'água; essa maior entalpia disponível desestabiliza a dinâmica dos jatos, ampliando a amplitude e persistência de desastres hidrometeorológicos extremos.", "possui_imagem": false},
  {"id": 229, "uid": "CIEN-8-229", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Brisa Marítima e Brisa Terrestre: Convecção Costeira", "dificuldade": "Médio", "enunciado": "Em cidades litorâneas, sopra durante o dia um vento agradável que vem do mar em direção à praia (brisa marítima); durante a noite, a direção do vento inverte-se, soprando da terra em direção ao mar (brisa terrestre). Essa alternância diária de ventos locais ocorre porque:", "alternativas": {"A": "O mar se transforma em terra firme durante a noite escura.", "B": "Durante o dia o continente aquece mais rápido que o oceano, criando baixa pressão na terra que atrai o ar fresco sobre o mar (brisa marítima); à noite a terra esfria muito mais rápido que a água do mar, invertendo o gradiente de pressão e fazendo o ar soprar da terra fria para o mar mais quente (brisa terrestre).", "C": "A gravidade da Lua puxa o vento para a praia de manhã e para o mar à noite.", "D": "Navios ancorados no porto ligam ventiladores gigantescos à tarde.", "E": "As ondas do mar empurram o vento apenas quando há turistas na praia."}, "resposta_correta": "B", "justificativa": "O contraste térmico diurno/noturno gerado pela diferença de calor específico entre terra e água dita a circulação celular local: dia com terra mais quente -> baixa pressão continental -> brisa marítima; noite com mar mais aquecido que o continente resfriado -> baixa pressão oceânica -> brisa terrestre.", "possui_imagem": true},
  {"id": 230, "uid": "CIEN-8-230", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Equação Hipsométrica e Variação Barométrica com a Altitude", "dificuldade": "Difícil", "enunciado": "A queda da pressão atmosférica com a altitude não é linear, mas segue um decaimento exponencial governado pela equação barométrica: P(z) = P0 . e^(-z / H), onde H é a escala de altura atmosférica (cerca de 7,5 a 8 km na troposfera). A consequência biofísica dessa relação exponencial para um alpinista escalando o Monte Everest (altitude z ≈ 8.848 metros) é:", "alternativas": {"A": "A pressão do ar cair para zero absoluto no cume do Everest.", "B": "A pressão atmosférica e a pressão parcial de oxigênio caírem para cerca de um terço (1/3) do valor ao nível do mar (cerca de 310 hPa contra 1.013 hPa no litoral), exigindo aclimatação prolongada ou uso de oxigênio suplementar para evitar hipóxia cerebral e edema pulmonar de altitude.", "C": "A temperatura do ar subir para 80 ºC acima de 8.000 metros.", "D": "O sangue do alpinista congelar instantaneamente dentro do coração.", "E": "O alpinista perder a gravidade e flutuar no espaço sideral."}, "resposta_correta": "B", "justificativa": "Como a atmosfera é compressível sob seu próprio peso, a densidade e pressão caem exponencialmente com a altitude. A 8.848 m, a pressão atmosférica é ~314 hPa (menos de um terço de 1 atm); com fração de O2 constante em 21%, a pO2 alveolar despenca de ~100 mmHg para menos de 30 mmHg sem oxigênio engarrafado.", "possui_imagem": false},
  {"id": 231, "uid": "CIEN-8-231", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Vento Geostrófico e Equilíbrio de Forças na Troposfera Superior", "dificuldade": "Difícil", "enunciado": "Na alta troposfera (onde o atrito com a superfície do solo é desprezível), os ventos em grande escala não sopram em direção direta aos centros de baixa pressão, mas fluem paralelamente às linhas de mesma pressão (isóbaras). Esse escoamento teórico e real é denominado 'Vento Geostrófico', que resulta do equilíbrio físico exato entre duas forças horizontais opostas:", "alternativas": {"A": "A força de empuxo da água e o atrito dos prédios urbanos.", "B": "A força de gradiente de pressão horizontal (que empurra o ar da alta para a baixa pressão) e a força inercial de Coriolis (que desvia a trajetória do ar em movimento devido à rotação da Terra).", "C": "A atração gravitacional da Lua e a força centrífuga do equador.", "D": "A radiação infravermelha do solo e o vento solar estelar.", "E": "A pressão osmótica das nuvens e o campo magnético polar."}, "resposta_correta": "B", "justificativa": "O equilíbrio geostrófico ocorre quando a força de gradiente de pressão horizontal (-1/ρ ∇P) é exatamente balanceada pela aceleração de Coriolis (2 Ω v sen φ). Esse equilíbrio dita a direção dos ventos sinóticos em altitude soprando paralelos às isóbaras (ventos zonais de oeste nos médios paralelos).", "possui_imagem": false},
  {"id": 232, "uid": "CIEN-8-232", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Processos Adiabáticos Secos vs. Úmidos na Atmosfera", "dificuldade": "Difícil", "enunciado": "Quando uma parcela de ar atmosférico não saturado (sem condensação) é forçada a subir na atmosfera, ela expande-se sob menor pressão e resfria-se a uma taxa constante conhecida como Gradiente Adiabático Seco (cerca de 10 ºC por km / 1 ºC a cada 100 m). No entanto, assim que a parcela atinge a saturação (100% UR) e o vapor começa a condensar-se em nuvens, a taxa de resfriamento da parcela em ascensão cai para o Gradiente Adiabático Úmido (cerca de 5 ºC a 6 ºC por km). Essa redução na taxa de resfriamento ocorre porque:", "alternativas": {"A": "A nuvem absorve luz solar extra no topo do céu.", "B": "A mudança de fase do vapor de água para água líquida durante a condensação libera imensas quantidades de calor latente de condensação no interior da parcela de ar, aquecendo-a parcialmente e contrabalançando a perda térmica por expansão mecânica.", "C": "As gotas de chuva entram em combustão lenta com o oxigênio.", "D": "O vento pára de soprar assim que as nuvens se formam.", "E": "A pressão atmosférica para de diminuir acima da base da nuvem."}, "resposta_correta": "B", "justificativa": "A termodinâmica da condensação libera o calor latente de vaporização (Lv ≈ 2,5 x 10^6 J/kg). Essa entalpia interna adicionada ao sistema em expansão compensa parcialmente o trabalho realizado pela parcela contra o meio ambiente, reduzindo o gradiente adiabático saturado (Γs ≈ 5-6 ºC/km) em relação ao seco (Γd = 9,8 ºC/km).", "possui_imagem": false},
  {"id": 233, "uid": "CIEN-8-233", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "A Teoria da Ciclogênese e Frentes Oclusas", "dificuldade": "Difícil", "enunciado": "Em latitudes médias e subtropicais (como no Sul do Brasil, Argentina e Uruguai), ciclones extratropicais formam-se a partir de descontinuidades baroclínicas ao longo de frentes polares. Durante o ciclo de vida maduro de um ciclone extratropical, quando a frente fria (mais veloz e densa) alcança e cavalga completamente a frente quente (mais lenta), suspendendo todo o setor de ar quente acima da superfície do solo, forma-se uma feição frontal chamada:", "alternativas": {"A": "Frente de brisa marítima pura.", "B": "Frente oclusa (ou oclusão frontal).", "C": "Frente estacionária desértica.", "D": "Frente convectiva de erupção vulcânica.", "E": "Frente de vácuo estratosférico."}, "resposta_correta": "B", "justificativa": "No modelo conceitual norueguês de ciclones baroclínicos de Bjerknes, a frente fria de cunha íngreme viaja mais rápido que a frente quente; a junção das duas massas frias aprisiona o ar quente em altitude (oclusão), marcando o início da fase de dissipação e enfraquecimento do ciclone.", "possui_imagem": false},
  {"id": 234, "uid": "CIEN-8-234", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Oscilação Madden-Julian (MJO) e Ondas Tropicais", "dificuldade": "Difícil", "enunciado": "A Oscilação de Madden-Julian (MJO) é o principal modo de variabilidade intra-sazonal na troposfera tropical do planeta, caracterizada por um pulso recorrente de convecção anômala profunda e chuvas que se desloca para o leste ao longo do Equador em um ciclo que dura cerca de 30 a 60 dias. Para a agricultura e previsão do tempo no Brasil, monitorar a fase da MJO é crucial porque:", "alternativas": {"A": "A MJO indica o dia exato em que vai nevar na praia de Copacabana.", "B": "A propagação das ondas planetárias da MJO modula diretamente os períodos de estiagem ou de chuvas intensas associados à Zona de Convergência do Atlântico Sul (ZCAS) e a formação de ciclones, permitindo previsões meteorológicas de médio alcance com semanas de antecedência.", "C": "A MJO altera a velocidade com que a Terra gira em torno do Sol.", "D": "A oscilação é causada por terremotos submarinos no Caribe.", "E": "A MJO desliga todas as redes elétricas inteligentes da Europa."}, "resposta_correta": "B", "justificativa": "A Oscilação Madden-Julian (MJO) acopla convecção baroclínica tropical e teleconexões por ondas de Rossby; dependendo de sua fase de passagem (fases 1 a 8), ela pode amplificar intensamente os canais de umidade da ZCAS e disparar chuvas torrenciais no Sudeste/Centro-Oeste do Brasil ou impor bloqueios atmosféricos de veranico seco.", "possui_imagem": false},
  {"id": 235, "uid": "CIEN-8-235", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Vórtices Ciclônicos de Altos Níveis (VCAN) no Nordeste", "dificuldade": "Difícil", "enunciado": "No verão do Nordeste brasileiro, um dos sistemas meteorológicos mais importantes e complexos que atua na alta troposfera (em torno de 12 km de altitude / 200 hPa) é o Vórtice Ciclônico de Altos Níveis (VCAN). O impacto meteorológico característico de um VCAN no tempo da região divide-se em:", "alternativas": {"A": "Chuva de granizo homogênea em 100% de todo o território nordestino.", "B": "Tempo firme, seco e sem nuvens em seu centro (onde ocorre subsidência forçada de ar que dissipa a nebulosidade) e bandas de tempestades convectivas severas concentradas na sua borda periférica (onde há forte divergência em altitude e levantamento de ar).", "C": "Seca completa em todo o oceano e cheias no centro do deserto.", "D": "Ventos congelantes que transformam as praias em geleiras.", "E": "Aumento da pressão atmosférica no fundo de cavernas de calcário."}, "resposta_correta": "B", "justificativa": "VCANs exibem estrutura circulatória assimétrica marcante: na periferia do vórtice em 200 hPa há forte divergência de massa associada a difluência que induz convecção profunda e tempestades; no centro e quadrante oeste do vórtice ocorre subsidência fria intensa que dissipa nuvens, gerando tempo ensolarado seco.", "possui_imagem": false},
  {"id": 236, "uid": "CIEN-8-236", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "A Corrente de Jato em Baixos Níveis (JBN) e os Rios Voadores", "dificuldade": "Difícil", "enunciado": "A transferência de imensas massas de vapor de água da Amazônia em direção às bacias hidrográficas do Prata e do Sudeste brasileiro é conduzida por um fluxo de vento acelerado que sopra a cerca de 1.500 metros de altitude rente à encosta leste dos Andes, conhecido como 'Jato de Baixos Níveis' (JBN / Low-Level Jet). A física orográfica que canaliza esse jato de ar úmido decorre de:", "alternativas": {"A": "A Floresta Amazônica empurrar o vento com ventiladores naturais gigantescos.", "B": "A barreira contínua e imponente da Cordilheira dos Andes (com altitude média de mais de 4.000 metros), que bloqueia mecanicamente o avanço para oeste dos ventos alísios tropicais que sopram do oceano, defletindo o fluxo de ar para o sul ao longo da calha continental como em um gigantesco duto aerodinâmico natural.", "C": "O calor de minas de ouro que atrai o ar por gravidade quântica.", "D": "A água do Rio Amazonas ferver e empurrar o ar como uma máquina a vapor.", "E": "A atração gravitacional do Polo Sul sobre as moléculas de chuva."}, "resposta_correta": "B", "justificativa": "Os ventos alísios equatoriais de leste transportam umidade oceânica através da bacia amazônica enriquecendo-se por evapotranspiração; ao colidirem com o paredão topográfico impenetrável da Cordilheira dos Andes, a conservação de vorticidade potencial canaliza e acelera o fluxo meridional para o sul na forma de Jato de Baixos Níveis (LLJ).", "possui_imagem": false},
  {"id": 237, "uid": "CIEN-8-237", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Dipolo do Oceano Atlântico Tropical e Secas no Semiárido", "dificuldade": "Difícil", "enunciado": "Além do El Niño no Pacífico, o regime de chuvas da quadra chuvosa do semiárido setentrional do Nordeste brasileiro (Ceará, Piauí, Rio Grande do Norte) é fortemente governado pelo 'Dipolo do Atlântico Tropical'. Quando o Atlântico Tropical Norte está anomalamente mais quente que o Atlântico Tropical Sul (Dipolo Positivo com gradiente térmico voltado para o norte):", "alternativas": {"A": "Ocorre enchente histórica em todas as cidades do sertão cearense.", "B": "A Zona de Convergência Intertropical (ZCIT) é puxada e deslocada para o norte de sua posição climatológica média, não conseguindo descer sobre o semiárido brasileiro e provocando secas severas e frustração de safras agrícolas no Nordeste.", "C": "O Oceano Atlântico congela completamente na costa de Fortaleza.", "D": "O Nordeste vivencia temperaturas de zero grau Celsius no verão.", "E": "Os rios voadores da Amazônia mudam de rumo e vão para o Polo Norte."}, "resposta_correta": "B", "justificativa": "O Dipolo de Anomalias de Temperatura da Superfície do Mar (TSM) no Atlântico Tropical governa a posição latitudinal meridiana da ZCIT. Águas mais quentes no Atlântico Norte atraem a banda convectiva ascendente da ZCIT para latitudes boreais, impedindo sua migração sazonal para o sul do Equador e gerando secas severas no Polígono das Secas.", "possui_imagem": false},
  {"id": 238, "uid": "CIEN-8-238", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Radiação de Onda Curta vs. Onda Longa no Balanço de Energia", "dificuldade": "Difícil", "enunciado": "O balanço radiativo da Terra é governado pelas leis fundamentais da radiação térmica (Lei de Stefan-Boltzmann e Lei de Wien). A distinção física exata entre a radiação que entra no planeta e a radiação que a Terra devolve para o espaço é:", "alternativas": {"A": "A radiação do Sol é fria e a da Terra é fervendo.", "B": "A radiação solar provém de um corpo a cerca de 5.800 Kelvin, sendo predominantemente radiação de onda curta (luz visível, ultravioleta e infravermelho próximo); a radiação terrestre é emitida pela superfície a cerca de 288 Kelvin (15 ºC), sendo exclusivamente radiação de onda longa (infravermelho termal), a qual é absorvida pelos gases de efeito estufa da atmosfera.", "C": "Ambas são ondas de rádio com a mesma frequência e energia.", "D": "O Sol emite apenas raios gama e a Terra emite apenas micro-ondas.", "E": "A Terra não emite nenhuma radiação para o espaço sideral."}, "resposta_correta": "B", "justificativa": "Pela Lei do Deslocamento de Wien (λ_max . T = constante), corpos em alta temperatura emitem picos em comprimentos de onda curtos (Sol a ~5.778 K emite luz visível centrada em ~0,5 μm); a Terra em baixa temperatura (~288 K) emite radiação de onda longa centrada em ~10 μm, faixa espectral absorvida eficientemente por H2O, CO2 e CH4 na atmosfera.", "possui_imagem": false},
  {"id": 239, "uid": "CIEN-8-239", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Ressurgência Marinha e Clima Costeiro em Cabo Frio (RJ)", "dificuldade": "Difícil", "enunciado": "Na região costeira de Cabo Frio e Arraial do Cabo, no litoral do Rio de Janeiro, ocorre o clássico fenômeno oceanográfico da 'ressurgência costeira'. Ventos persistentes de quadrante nordeste empurram as águas superficiais quentes para longe da costa (Transporte de Ekman), fazendo com que águas profundas frias (cerca de 12 ºC a 15 ºC, ricas em nutrientes da Corrente das Malvinas) aflorem à superfície. O reflexo microclimático dessa água fria na cidade de Cabo Frio é:", "alternativas": {"A": "Provocar tempestades diárias de chuva torrencial de verão.", "B": "Um microclima local semiárido e atipicamente seco com vegetação de caatinga e dunas costeiras, pois a água superficial gelada esfria o ar rente ao mar e inibe fortemente as correntes de convecção de chuvas.", "C": "O aquecimento da praia para temperaturas de 60 graus Celsius.", "D": "A queima de todas as árvores por cinzas vulcânicas marítimas.", "E": "O congelamento de todos os peixes que nadam na praia."}, "resposta_correta": "B", "justificativa": "O Transporte de Ekman deflete águas superficiais a 90º à esquerda do vento NE no Hemisfério Sul, forçando a Corrente Central do Atlântico Sul (ACAS) gelada e fértil a emergir na plataforma continental. A TSM rebaixada estabiliza a baixa troposfera, inibindo a convecção de chuvas e gerando o enclave semiárido litorâneo fluminense de Cabo Frio.", "possui_imagem": false},
  {"id": 240, "uid": "CIEN-8-240", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "A Escala Saffir-Simpson e a Física do Olho do Furacão", "dificuldade": "Difícil", "enunciado": "A intensidade de furacões é classificada de Categoria 1 a 5 pela Escala Saffir-Simpson com base na velocidade sustentada dos ventos. No centro exato de um furacão maduro de Categoria 5 encontra-se o 'olho do furacão', uma área de cerca de 30 a 60 km de diâmetro onde, paradoxalmente, as condições meteorológicas caracterizam-se por:", "alternativas": {"A": "Ventos de 500 km/h com fogo e relâmpagos contínuos no chão.", "B": "Ventos relativamente calmos e suaves, céu parcialmente claro e ausência de chuvas, provocados por um fluxo descendente de ar seco (subsidência no olho) cercado pela muralha de nuvens Cumulonimbus (parede do olho) onde sopram os ventos mais devastadores.", "C": "Abertura de uma fenda no fundo do oceano que suga todos os navios.", "D": "Congelamento de todo o mar em menos de um segundo.", "E": "Pressão atmosférica extremamente alta de mais de 2.000 hPa."}, "resposta_correta": "B", "justificativa": "O olho de um ciclone tropical maduro abriga a mais baixa pressão barométrica de superfície do sistema (<920 hPa); a forte conservação do momento angular impede que o ar convirja até o centro geométrico, forçando ar estratosférico a descender (subsidência adiabática quente e seca) que dissipa nuvens no olho, cercado pela violenta parede do olho (eyewall).", "possui_imagem": false},
  {"id": 241, "uid": "CIEN-8-241", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Gases de Efeito Estufa e Potencial de Aquecimento Global (GWP)", "dificuldade": "Difícil", "enunciado": "Em acordos climáticos internacionais (como o Protocolo de Kyoto e o Acordo de Paris), os gases de efeito estufa são comparados através do 'Potencial de Aquecimento Global' (GWP - Global Warming Potential) em um horizonte temporal de 100 anos, adotando o CO2 como referência padrão (GWP = 1). Gases como o gás metano (CH4) e o óxido nitroso (N2O) apresentam GWP100 de cerca de 28 e 273, respectivamente. Isso significa que:", "alternativas": {"A": "O metano desaparece da atmosfera em menos de 10 segundos.", "B": "A emissão de 1 tonelada de gás metano retém, ao longo de 100 anos, a mesma quantidade de calor na atmosfera que a emissão de cerca de 28 toneladas de dióxido de carbono, evidenciando que certos gases possuem capacidade de forçante radiativa por molécula imensamente superior à do CO2.", "C": "O óxido nitroso resfria o planeta 273 vezes mais rápido que o gelo.", "D": "O CO2 é o único gás perigoso e os outros não aquecem a Terra.", "E": "O metano é um gás inerte que não interage com radiação infravermelha."}, "resposta_correta": "B", "justificativa": "O GWP integra a eficiência radiativa molecular do gás (capacidade de absorção em janelas espectrais do infravermelho de onda longa) combinada com seu tempo de residência na atmosfera em relação ao CO2; o metano possui bandas de absorção radiativa intensas, tornando o controle de emissões de CH4 prioritário para mitigação climática rápida.", "possui_imagem": false},
  {"id": 242, "uid": "CIEN-8-242", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Ondas de Frio e a 'Friagem' na Região Norte do Brasil", "dificuldade": "Difícil", "enunciado": "Durante invernos rigorosos no Cone Sul, quando massas de ar polar atlânticas continentais de grande espessura avançam pelo interior da América do Sul contornando a leste a Cordilheira dos Andes, elas conseguem atingir estados da Amazônia Ocidental como Rondônia, Acre e sul do Amazonas. A queda brusca de temperatura de mais de 35 ºC para valores abaixo de 14 ºC nessa região equatorial é o fenômeno da:", "alternativas": {"A": "Geada de praia.", "B": "Friagem amazônica.", "C": "Inversão térmica do cerrado.", "D": "El Niño polar continental.", "E": "Brisa orográfica equatorial."}, "resposta_correta": "B", "justificativa": "A friagem é a incursão de ar polar subantártico canalizado pela calha depressional entre os Andes e o Planalto Central; a massa densa avança rapidamente pelas planícies do Chaco e Pantanal rompendo a barreira tropical e derrubando as temperaturas em plena Amazônia Ocidental em dezenas de graus Celsius em poucas horas.", "possui_imagem": false},
  {"id": 243, "uid": "CIEN-8-243", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Circulação Geral da Atmosfera: Células de Hadley, Ferrel e Polar", "dificuldade": "Difícil", "enunciado": "O transporte planetário de calor do Equador em direção aos polos é organizado em três grandes células convectivas meridianas de circulação em cada hemisfério da Terra. Da Linha do Equador em direção ao Polo, a sequência correta dessas células é:", "alternativas": {"A": "Célula de Ferrel -> Célula Polar -> Célula de Hadley.", "B": "Célula de Hadley (tropical) -> Célula de Ferrel (latitudes médias) -> Célula Polar (altas latitudes).", "C": "Célula de Coriolis -> Célula de Kelvin -> Célula de Wagner.", "D": "Célula de Newton -> Célula de Joule -> Célula de Ohm.", "E": "Célula Convectiva Única sem rotação."}, "resposta_correta": "B", "justificativa": "O modelo tricelular de circulação geral estratifica a atmosfera em: Célula de Hadley termicamente direta (ar ascende na ZCIT e descende nos cinturões subtropicais de alta pressão a ~30º); Célula de Ferrel indireta (entre 30º e 60º impulsionada por sistemas frontais); Célula Polar termicamente direta (entre 60º e os polos).", "possui_imagem": false},
  {"id": 244, "uid": "CIEN-8-244", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Microfísica de Nuvens: Processo de Bergeron-Findeisen", "dificuldade": "Difícil", "enunciado": "Em nuvens frias cuja temperatura situa-se entre 0 ºC e -40 ºC, gotículas de água líquida super-resfriada (que permanecem líquidas abaixo de zero grau por ausência de núcleos de congelamento) coexistem com cristais microscópicos de gelo. O 'Processo de Bergeron-Findeisen' explica o crescimento veloz dos flocos de neve nessas nuvens baseado no princípio físico de que:", "alternativas": {"A": "A água líquida evapora mais rápido sob a luz da lua cheia.", "B": "A pressão de vapor de saturação sobre a água líquida é maior do que sobre a superfície do gelo na mesma temperatura negativa; isso cria um gradiente contínuo no qual as gotículas de água evaporam e o vapor resultante sublima/desublima rapidamente sobre os cristais de gelo, fazendo os cristais crescerem até caírem por gravidade.", "C": "O gelo é mais leve que o ar e sobe para o espaço sideral.", "D": "As gotículas de água se transformam em gás carbônico comprimido.", "E": "Os cristais de gelo repelem o vapor d'água por eletricidade estática."}, "resposta_correta": "B", "justificativa": "Pelo mecanismo de Bergeron-Findeisen-Wegener, a menor pressão de vapor de equilíbrio sobre o gelo em relação à água super-resfriada induz difusão molecular contínua de vapor: a água líquida evapora alimentando a deposição direta sobre o gelo, permitindo crescimento rápido de cristais até o limiar de precipitação por peso próprio.", "possui_imagem": false},
  {"id": 245, "uid": "CIEN-8-245", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Ciclo do Carbono e Acidificação dos Oceanos", "dificuldade": "Difícil", "enunciado": "Os oceanos absorvem cerca de 25% a 30% de todo o dióxido de carbono (CO2) emitido anualmente pela queima de combustíveis fósseis pela humanidade. Embora atue como um amortecedor contra o aquecimento global, a dissolução em larga escala de CO2 na água marinha gera a 'Acidificação dos Oceanos' através da reação: CO2 + H2O <-> H2CO3 <-> H+ + HCO3-. O aumento de íons hidrogênio (H+) na água do mar provoca como impacto biológico direto:", "alternativas": {"A": "O congelamento de todos os recifes de coral da Austrália.", "B": "A redução na disponibilidade de íons carbonato (CO3^2-), dificultando gravemente a síntese e provocando a dissolução das conchas e esqueletos de carbonato de cálcio (CaCO3) de corais, moluscos, crustáceos e plâncton calcário na base da cadeia alimentar marinha.", "C": "A transformação da água salgada em ácido sulfúrico concentrado.", "D": "A proliferação de tubarões voadores nas praias.", "E": "O aumento do oxigênio dissolvido até fazer o mar ferver."}, "resposta_correta": "B", "justificativa": "O excesso de íons H+ reage com íons carbonato livres (H+ + CO3^2- -> HCO3-), diminuindo o estado de saturação de aragonita e calcita (Ω). Organismos calcificadores marinhos gastam mais energia metabólica para secretar esqueletos calcários e recifes de corais sofrem bioerosão química acelerada.", "possui_imagem": false},
  {"id": 246, "uid": "CIEN-8-246", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Ilhas de Calor Urbanas e Poluição por Ozônio Troposférico", "dificuldade": "Difícil", "enunciado": "Em grandes áreas metropolitanas densamente urbanizadas, a substituição da vegetação por asfalto, prédios altos que barram o vento e a emissão massiva de calor por carros e ar-condicionado formam as 'Ilhas de Calor Urbanas'. Em dias quentes e ensolarados, a alta temperatura combinada com emissões de óxidos de nitrogênio (NOx) e compostos orgânicos voláteis (VOCs) acelera reações fotoquímicas secundárias que geram na troposfera:", "alternativas": {"A": "Chuva de ácido clorídrico concentrado pura.", "B": "Ozônio troposférico (O3 ao nível do solo), um poluente oxidante altamente tóxico que irrita severamente as vias aéreas, queima tecidos vegetais e causa danos cardiovasculares na população urbana.", "C": "Camada de ozônio que cura o câncer de pele instantaneamente.", "D": "Vapor de água mineral medicinal que despolui o ar.", "E": "Gás oxigênio puro que resfria a cidade a zero grau."}, "resposta_correta": "B", "justificativa": "Diferente do ozônio estratosférico protetor benéfico, o ozônio troposférico ao nível do solo é um poluente secundário agressivo gerado pelo smog fotoquímico sob forte irradiação solar: NOx + VOCs + luz solar -> O3. Sua inalação causa lesão celular oxidativa pulmonar e redução no rendimento agrícola periurbano.", "possui_imagem": false},
  {"id": 247, "uid": "CIEN-8-247", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Efeito Estufa Runaway e o Passado de Vênus", "dificuldade": "Difícil", "enunciado": "Modelos de astrobiologia e climatologia comparada planetária estudam o planeta Vênus, cuja temperatura superficial atinge infernais 465 ºC (quente o suficiente para derreter chumbo), apesar de estar mais longe do Sol que Mercúrio. A causa do calor extremo de Vênus foi o colapso por 'Efeito Estufa Desenfreado' (Runaway Greenhouse Effect) em seu passado geológico, no qual:", "alternativas": {"A": "Vênus foi atingido por dez cometas de carvão mineral atômico.", "B": "A evaporação de seus antigos oceanos injetou volumes maciços de vapor d'água (potente gás de efeito estufa) na atmosfera, retendo calor em retroalimentação positiva incontrolável até que toda a água evaporou, foi perdida para o espaço e o ciclo biogeoquímico colapsou, acumulando uma atmosfera densa composta por 96% de CO2.", "C": "O núcleo de Vênus explodiu como uma bomba de hidrogênio.", "D": "Vênus parou de girar e caiu em direção ao centro do Sol.", "E": "A atmosfera venusiana é feita de ferro líquido incandescente."}, "resposta_correta": "B", "justificativa": "O paradigma do Runaway Greenhouse Effect de Kasting modela a instabilidade climática máxima: à medida que a irradiação solar aumentou, a evaporação oceânica injetou vapor na troposfera superior; a retenção térmica excedeu o limite de Komabayashi-Ingersoll, secando os oceanos e dissociando H2O por fotólise, consolidando uma atmosfera fóssil ultra-densa de 90 atm de CO2 puro.", "possui_imagem": false},
  {"id": 248, "uid": "CIEN-8-248", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Sistemas de Alerta Precoce de Desastres e o Radar Doppler", "dificuldade": "Difícil", "enunciado": "Na gestão de riscos de desastres naturais pelo Centro Nacional de Monitoramento e Alertas de Desastres Naturais (Cemaden) no Brasil, utilizam-se radares meteorológicos com tecnologia Doppler e dupla polarização. A dupla polarização (polarização horizontal e vertical simultânea) do feixe do radar revolucionou a previsão imediata porque permite aos meteorologistas:", "alternativas": {"A": "Enxergar o interior de residências urbanas à distância.", "B": "Diferenciar com precisão matemática a forma e o tipo das partículas atmosféricas (distinguindo granizo sólido de gotas de chuva líquida pesada e identificando fumaça ou pássaros), permitindo estimar com altíssima acurácia a taxa real de precipitação em áreas de risco de deslizamento de terra.", "C": "Parar tempestades de chuva disparando ondas de calor no céu.", "D": "Medir a temperatura do asfalto das ruas para trânsito.", "E": "Prever terremotos profundos na placa sul-americana."}, "resposta_correta": "B", "justificativa": "Radares polarimétricos transmitem ondas com oscilação ortogonal em dois planos: parâmetros como refletividade diferencial (ZDR) e fase diferencial específica (KDP) discriminam a esfericidade dos alvos hidrometeorológicos, isolando granizo volumoso de chuva convectiva intensa e mitigando desastres geotécnicos.", "possui_imagem": false},
  {"id": 249, "uid": "CIEN-8-249", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Instabilidade Baroclínica e Ondas de Rossby Planetárias", "dificuldade": "Difícil", "enunciado": "As correntes de jato polares em altitude (Jet Streams) circundam o planeta ondulando em meandros gigantescos chamados 'Ondas de Rossby planetárias'. O mecanismo dinâmico que gera essas ondulações e sustenta a troca de massas de ar quentes e frias entre latitudes tropicais e polares baseia-se na:", "alternativas": {"A": "Fricção de aviões comerciais que voam na mesma rota.", "B": "Instabilidade baroclínica decorrente da conservação da vorticidade potencial absoluta em um fluido atmosférico estratificado sujeito à variação do parâmetro de Coriolis com a latitude (o efeito beta, β = df/dy).", "C": "Atração magnética das montanhas de ferro do Polo Norte.", "D": "Temperatura dos vulcões do centro da África.", "E": "Rotação da Lua ao redor da Terra em 28 dias."}, "resposta_correta": "B", "justificativa": "As ondas planetárias de Rossby surgem como resposta restauradora da atmosfera à variação do efeito de Coriolis com a latitude (gradiente meridiano de vorticidade planetária β = 2 Ω cos φ / R). Perturbações no jato polar meandram e transferem calor latente e sensível em escala global através da instabilidade baroclínica.", "possui_imagem": false},
  {"id": 250, "uid": "CIEN-8-250", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "8º Ano", "ano": "8º Ano", "modulo": "Módulo 19: Clima, Previsão do Tempo e Fenômenos Atmosféricos", "tema": "Atribuição Científica de Eventos Extremos (Climatologia de Atribuição)", "dificuldade": "Difícil", "enunciado": "Com o avanço dos supercomputadores e da ciência do clima, pesquisadores do World Weather Attribution (WWA) realizam estudos de 'Atribuição de Eventos Climáticos Extremos' logo após grandes inundações ou secas históricas. O método estatístico-computacional rigoroso utilizado nesses estudos consiste em:", "alternativas": {"A": "Afirmar que todo evento meteorológico teria acontecido da mesma forma sem a humanidade.", "B": "Comparar simulações climáticas de alta resolução do mundo real atual (com a concentração observada de gases de efeito estufa emitidos pela humanidade) com simulações contrafactuais do mundo que existiria sem as emissões humanas, quantificando probabilisticamente em quanto a atividade humana tornou aquele evento específico mais provável ou mais intenso.", "C": "Contar quantas árvores foram derrubadas na cidade no dia da chuva.", "D": "Adivinhar o tempo com base em contos folclóricos antigos.", "E": "Medir a temperatura de meteoros que caíram no mar no último mês."}, "resposta_correta": "B", "justificativa": "A ciência da atribuição climática de eventos extremos utiliza modelos climáticos acoplados globais e regionais alimentados com e sem forçantes antropogênicas (atribuição factual vs. contrafactual). Por análise de probabilidade extrema (Risk Ratio / Fraction of Attributable Risk), determina-se formalmente a contribuição das emissões de GEE na severidade e tempo de retorno do evento extremo.", "possui_imagem": false}
];
